/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-0SiVi\":[\"兆米和千兆米出現在行星科學。地球直徑和軌道距離以原始米為單位是很尷尬的；帶有前綴的兆米或科學記數法使數字保持可讀性。\"],\"-4BlXE\":[\"美國的木工仍然使用英尺和英寸，包括分數英寸。接受過公制培訓的木工轉換計劃必須根據適合關鍵零件決定是軟轉換（最接近方便的毫米）還是硬轉換（精確為每英寸 25.4 毫米）。\"],\"-66dxX\":[\"一平方碼約等於 0.836 平方公尺。地毯、織物和景觀美化經常以平方碼為單位引用面積。\"],\"-6aMA_\":[\"一平方公分 (cm²) 等於 10⁻⁴ 平方公尺。這是學校和實驗室熟悉的小表面單位。\"],\"-7W-el\":[\"<0>廣告資料：</0>在徵得同意後啟用廣告時，Google AdSense和合作夥伴可能會處理 Cookie 和裝置識別碼以展示和衡量廣告。\"],\"-B-lAA\":[\"What volume unit pairs with kilograms for SI density?\"],\"-BwTJr\":[\"Pick economy style (L/100 km or mpg). Convert distance and fuel volume into the units that formula needs. Convert highway pace with km/h ↔ mph when comparing trips across countries. Only then compute or convert the economy figure with the correct gallon definition.\"],\"-C9xP8\":[\"工作習慣面積：200 平方英尺至平方公尺。首先轉換長度：1 ft = 0.3048 m，因此 1 ft² = 0.092 903 04 m²。那麼 200 × 0.092 903 04 = 18.580 608 平方公尺。注意平方因子－跳過這一步將是災難性的錯誤。\"],\"-Erj6j\":[\"即時結果\"],\"-EvUuc\":[\"是的。 Units Converters 可供學生、專業人士及日常任務免費使用。結果僅供參考——始終遵循安全關鍵工作的業界標準。\"],\"-J5iWY\":[\"立方英尺\"],\"-MPLZZ\":[\"即使地板以面積出售，襯墊、黏合劑和裝飾有時也按長度出售。單獨追蹤數量類型，這樣您就不會像平方米一樣對待線性米。\"],\"-PC2P3\":[\"一分升 (dL) 等於 100 毫升。一些國家的烹飪和營養標籤使用分升。\"],\"-SGpOv\":[\"Because 14 lb make a stone, leftover pounds always run from 0 to 13 in normal speech. Saying “11.4 stone” casually might mean 11 st 4 lb to a listener—or 11.4 × 14 lb to a spreadsheet. Those disagree. Prefer “11 st 4 lb” in writing.\"],\"-TpHs4\":[\"有關轉換杯子、公升、湯匙和茶匙的實用廚房指南，以及在稱重時擊敗體積以實現一致的烘焙。\"],\"-Udhzz\":[\"聯絡我們 | Units Converters\"],\"-ZAtn2\":[\"換算表\"],\"-a6gBA\":[\"化學品池容量：公升和立方米\"],\"-cHB7E\":[\"Use feet to metres when US real-estate listings, lumber lengths, or flight levels described in feet must feed metric planning tools, EU building codes, or GPS apps set to metres. Survey notes and climbing guidebooks also flip between these. Divide feet by 3.28084, or multiply by 0.3048 exactly.\"],\"-f_6jA\":[\"Common mistakes\"],\"-iy9_F\":[\"Recipes use grams for most ingredients. Kilograms appear for large dough batches (1 kg flour). Milligrams appear in nutrition labels and caffeine or supplement contexts—1,000 mg = 1 g. Do not dose medicine from a kitchen scale unless the device and procedure are appropriate; this guide is about cooking units.\"],\"-jAHTX\":[\"正好 1 000 000 000 奈米 (10⁹ nm)。一奈米等於 10⁻⁹ 米。\"],\"-mdYJ1\":[\"儀器製造商開始標記固定點，例如融化的冰、沸水或人體溫度。固定點的選擇以及固定點之間的度數產生了相互競爭的尺度。在約定確定之前，甚至編號方向（一端為零）也發生了變化。\"],\"-n86uv\":[\"5K 是五公里（約 3.1 英里）。比賽名稱中的 K 總是讀作公里。\"],\"-oEWCf\":[\"A foot per second (ft/s) equals exactly 0.3048 metres per second. Engineering, ballistics, and some US technical contexts use feet per second.\"],\"-tbTIi\":[\"當圖表列出每 10,000 公升的劑量時，請將泳池容積轉換為公升，除以 10,000，然後乘以列出的劑量。在每個中間數旁邊寫下單位。\"],\"-uY40k\":[\"何時使用 \",[\"tFrom\"],\" 與 \",[\"tTo\"]],\"-uhfR3\":[\"一旦每個單元映射到一個基礎，任何對都會分兩步驟進行轉換。這比儲存每個單元與其他單元的巨大矩陣更易於維護，並且它可以保持因子一致。\"],\"-uxhlJ\":[\"戶外公里和英里\"],\"-vpOo3\":[\"艾爾\"],\"-w9nPE\":[\"燃料、實驗室和工業\"],\"-xcRjp\":[\"科學等級：\"],\"-y0hUl\":[\"Milligram\"],\"-yU7G4\":[\"我們可能會不時更新這些服務條款。發布變更後繼續使用本網站即表示接受修訂後的條款。我們鼓勵您定期查看此頁面。\"],\"-ztKvx\":[\"牛頓和其他歷史尺度\"],\"00BfTm\":[\"有限元素和 CFD 模型對於單位一致性是無情的。選擇SI作為模型，轉換輸入，轉換輸出。混合單元牌組是傳奇的失敗模式。\"],\"01oAfy\":[\"平方米\"],\"02KbvL\":[\"An international mile per hour (mph) equals exactly 0.44704 metres per second. It is the everyday road-speed unit in the United States and United Kingdom.\"],\"03-4zJ\":[\"Units Converters 由位於巴西的Voyager Tecnologias LTDA 營運。隱私問題，請聯絡<0>voyagertecnologias@gmail.com</0>。\"],\"055uyK\":[\"A centimetre per second (cm/s) equals 0.01 metres per second. Laboratory flow rates and slow mechanical motions are often expressed in cm/s.\"],\"06TQZF\":[\"They run in opposite directions: higher mpg is better; lower L/100 km is better. Convert with proper factors before comparing a US mpg sticker to a metric L/100 km sticker.\"],\"0AIRPc\":[\"Confusing mg with µg (micrograms)—a 1,000× error that is dangerous for medication. Tablet strength in mg is not the same as dose if you take multiple tablets—convert the total mass you swallow. Do not assume mg of a vitamin equals mg of elemental nutrient without the salt form factor.\"],\"0ArAQV\":[\"使用明確的方法測量一次（當精確度很重要時，可使用壁掛式測距儀）。轉換為表格所需的單位。圓形僅用於顯示。仔細檢查英尺和英寸是否沒有互換。\"],\"0B7LAd\":[\"大麥\"],\"0CAVbP\":[\"國際吋正好是25.4毫米。國際英尺正好是 0.3048 m。一公升正好是 0.001 立方公尺。在通常的實驗室意義上，一立方厘米正好是 1 毫升（1 立方厘米 = 10⁻⁶ 立方米）。這些是定義，而不是測量。\"],\"0F9UuU\":[\"A gram (g) equals one thousandth of a kilogram. It is the familiar metric unit for kitchen scales, nutrition labels, and small packages.\"],\"0G_7_W\":[\"管道和木材的標稱尺寸並不總是實際測量的尺寸。單位轉換無法修復標稱與實際不符的情況—測量您擁有的零件。\"],\"0KApmg\":[\"您無法使用廚房尺驗證 20 nm 特徵。將儀器與規模相匹配：電子顯微鏡和奈米專業計量學；微米級光學顯微鏡；千分尺和毫米坐標測量機。轉換不能升級儀器的解析度。\"],\"0OJ9Po\":[[\"tQuantity\"],\" 轉換\"],\"0TIAUP\":[\"Get volume units straight\"],\"0TOxMR\":[\"Scientific experiments often need milliseconds or microseconds. Convert 0.0025 s to milliseconds (2.5 ms) carefully: multiply seconds by 1,000 for milliseconds, by 1,000,000 for microseconds. Off-by-thousand errors are common when SI prefixes and sexagesimal time mix.\"],\"0UCLPw\":[\"了解為什麼二進制浮點會產生奇怪的轉換殘差，當這些錯誤很重要時，以及十進位或有理算術如何保持單位轉換器的可信度。\"],\"0Vwwul\":[\"Millisecond\"],\"0Ww9ut\":[\"No. A leap year is a calendar year with an extra day. A Julian year is a constant duration equal to the average length of a year in the old Julian leap pattern (365.25 days).\"],\"0dLIIp\":[\"How many seconds are in an hour?\"],\"0fJzsZ\":[\"Is 100 on the sign mph or km/h?\"],\"0hQ0Q4\":[\"公頃\"],\"0nEBio\":[\"Multiply knots by 1.852. Example: 100 kt = 185.2 km/h.\"],\"0usQ4p\":[\"UI 轉換器通常會透過四捨五入到固定的小數位數來隱藏問題。使用者看到乾淨的結果而不會注意到內部噪音。當另一個系統使用原始浮點數時就會出現問題：CAD 核心、CSV 匯出或比較全精度字串的單元測試。\"],\"0y9e1o\":[\"A curtain drop of 84 inches is 7 feet exactly—standard floor-length drapery. A workbench at 36 inches high is 3 feet, matching many metric 900 mm benches within a few millimetres.\"],\"15Tpag\":[\"Multiply the min/km pace by 1.609344. Example: 5:00 /km ≈ 8:03 /mile. Or convert via km/h ↔ mph and back to pace.\"],\"1IEF32\":[\"哪些換算係數在紙上是準確的\"],\"1Ip6j3\":[\"Use outer dimensions, including bulges and protruding handles. Soft packs are measured as the rectangular envelope they occupy. Convert all three sides into one length unit before multiplying. Mixing centimetres and inches in the same product is a classic quote killer.\"],\"1L66kB\":[\"了解單位轉換背後的機制——基本單位、轉換係數、尺寸分析，以及為什麼連結轉換會小心地保持答案準確。\"],\"1Qcw4d\":[\"Identify whether the source value is knots. Convert with 1.852 to km/h when talking to metric land audiences. Keep internal logs in knots if your charts are nautical. Dual-label passenger briefings (“8 knots, about 15 km/h”) when helpful.\"],\"1RF6BO\":[\"Economy depends strongly on driving speed. Converting km/h ↔ mph lets you compare trips or test conditions fairly before you compare L/100 km or mpg results.\"],\"1Rafvn\":[\"在選擇米與英尺之前，先選擇長度、面積與體積。許多「單位」問題都是變相的數量問題，尤其是在施工估算中。\"],\"1RaqL_\":[\"科學級單位\"],\"1SDUel\":[\"何時更重視重量而不是體積\"],\"1VRa7f\":[\"Units Converters 由 <0>Voyager Tecnologias LTDA</0> 開發和維護。我們是一個小團隊，熱衷於建立高品質的數位實用程序，以卓越的技術解決日常問題。\"],\"1WacFx\":[\"換算公式\"],\"1e_JkI\":[\"Digital tools often store seconds (or milliseconds) as the base and format displays as hh:mm:ss. When you convert, prefer going through seconds for multi-step work: hours → seconds → minutes, rather than chaining rounded intermediate displays.\"],\"1ilaSd\":[\"The kilogram (kg) is the SI base unit of mass. It is defined by fixing the Planck constant and is the reference for everyday weighing and science.\"],\"1tCIxd\":[\"Convert seconds to minutes for race results, microwave experiments, and API timeouts when logs show raw seconds. Divide seconds by 60. Sports broadcasting and backend SLAs both humanize seconds this way.\"],\"2-MYa-\":[\"Planck長度是一個基本物理常數，代表了關於空間和重力的經典觀念崩潰的尺度。它的大小約為 1.6 × 10⁻³⁵ 米，用於理論物理。\"],\"208s5O\":[\"一旦代數自動化，線上轉換器就會成為速度工具而不是拐杖。您將在繪製或劑量之前發現倒置因素、錯誤的數量類型和溫度偏移錯誤。即使您信任某個特定網站，這項技能也很重要，因為您仍然需要驗證其數量模式和舍入行為。\"],\"218ZDU\":[\"硬轉換使用精確的因子，然後根據保留容差意圖的規定規則進行舍入。軟轉換在其他系統中選擇一個方便的附近標稱值。兩者都是有效的策略——但它們是不同的策略。在修訂區塊中寫下您使用的是哪一個。\"],\"24A_yj\":[\"在某些地區，手機螢幕、筆記型電腦和桌面配件以英吋為單位銷售，即使其他地區則以公制單位銷售。將這些英吋視為行銷慣例，如果您需要公制包或袖子中的間隙，請進行轉換。\"],\"24rSD1\":[\"Multiplying by 1.6 (the linear mile factor) instead of ~2.59 is the standard mistake. Township grids and “sections” (1 sq mi) convert cleanly; irregular coastal counties still use the same factor on their reported area. Keep water vs land area labels intact after converting.\"],\"25a9CX\":[\"SI 通常最適合科學和國際工程，但本地規範、工具和受眾可能需要習慣單位。當他們這樣做時，仔細轉換並記錄權威系統。\"],\"27B7uY\":[\"值得信賴的土地轉換工作流程\"],\"29C6iW\":[\"了解更多\",[\"tQuantity\"]],\"2Aplq9\":[\"Use the mile-per-hour ↔ kilometre-per-hour converter for exact values when a work zone lists an unusual number. Anchors are for glance checks; exact math is for planning and disputes.\"],\"2VWuzt\":[\"透過我們的指南學習\"],\"2aQdBR\":[\"A 4×6 inch photo is 24 in², about 155 cm² of print area. A 1 in² ventilation hole is 6.45 cm² for metric airflow notes.\"],\"2cR6Dq\":[\"1 公頃 = 10 000 平方公尺。 1 平方公里 = 100 公頃 = 1 000 000 平方公尺。 1 英畝 ≈ 0.404 686 公頃。 1 英畝 ≈ 4 047 平方公尺（更準確地說是 4 046.856 422 4 平方公尺）。根據與調查/國際英尺討論相關的美國習慣土地測量中的定義，1 英畝 = 43 560 平方英尺。記住公頃和英畝到平方公尺的對；需要時導出其餘部分。\"],\"2fKQ-1\":[\"提示：開爾文在 SI 書寫中從不使用度數符號（K，而非 °K）。 1 K 的變化相當於 1 °C 的變化。對於烘焙，首先轉換配方，然後針對風扇烤箱進行調整。\"],\"2mpp6P\":[\"Units Converters is a free educational utility operated by \",[\"0\"],\". Please read these limitations before relying on any result.\"],\"2nr-Ad\":[\"杯子\"],\"2op5th\":[\"面積、體積和衍生量\"],\"2wazXz\":[\"單一基數使每個單元定義保持一致並減少儲存因子的數量。當你信任直接因素時，它們就很好；基本單元路徑是軟體和檢查手動計算的可靠模式。\"],\"2xIadB\":[\"<0>您發送的回饋：</0> 姓名、電子郵件和訊息（如果您使用我們的聯絡資訊或回饋表）。\"],\"2yEcJZ\":[\"快速、準確且易於使用的長度、溫度、面積和體積單位轉換器。科學精確，舍入誤差為零。\"],\"3-O-U2\":[\"Rhode Island’s land area near 1,034 sq mi is about 2,678 km². A 10 sq mi flood zone is roughly 25.9 km² for metric emergency maps.\"],\"30hVC9\":[\"當實驗室協議顯示 250 nm 而卡尺讀數為毫米時，十的冪思維可以防止恐慌。首先轉換為公尺：250 nm = 2.5 × 10⁻⁷ m = 0.000 25 mm－遠低於卡尺解析度。轉換正確；儀器選擇錯誤。\"],\"324qxJ\":[\"No. You need both distance (mile↔km) and volume (gallon↔litre) factors, and you must know whether the gallon is US or imperial.\"],\"32nfzA\":[\"Dimensional weight formulas in practice\"],\"350ym0\":[\"From sketch to order form\"],\"35GwnE\":[\"精密單位轉換器：公制、英制和科學\"],\"3CoO29\":[\"分升\"],\"3E5zLe\":[\"Nautical miles and knots travel together. If you convert speed to km/h, convert distance to kilometres too before dividing for time.\"],\"3E7v2_\":[\"家裡的毫米和厘米\"],\"3Fv6-r\":[\"三種刻度，兩種零\"],\"3N9RRw\":[\"跨境通訊量\"],\"3NPiUv\":[\"湯匙在國際上也有所不同。許多公制湯匙的容量為 15 毫升；一些傳統的澳洲湯匙是 20 毫升。當配方很重要時，最好選擇稱重的成分或毫升的量度。\"],\"3P9P3g\":[\"A stone equals 14 avoirdupois pounds, or exactly 6.35029318 kilograms. Body weight in the United Kingdom is still often quoted in stones and pounds.\"],\"3PqcjI\":[\"在國外租車時，請注意行車電腦顯示的是公里還是英哩。在旅途中以錯誤的心理單位重置平均值會產生無意義的成本估算。\"],\"3R4dl3\":[\"Is 1.30 hours the same as 1 hour 30 minutes?\"],\"3SMznx\":[\"使用Units Converters，即表示您確認您已閱讀、瞭解並同意受本服務條款和我們的隱私權政策的約束。如果您不同意，請不要使用網站。\"],\"3SRSvY\":[\"日常生活中的長度單位：從毫米到英里\"],\"3UzgKd\":[\"For durations over 24 hours, decide whether to display total hours (36 h) or days plus hours (1 d 12 h). Converting total seconds into either presentation is fine—just label the result so readers know which form you chose.\"],\"3ZVFSt\":[\"天氣和烹飪主導攝氏溫度和華氏溫度的使用。舒適的室溫約為 20–22 °C (68–72 °F)。體溫約 37 °C (98.6 °F)。烤箱食譜可能會同時列出兩者；請務必確認轉換後的烤箱設定是否與您的設備標記相符。\"],\"3aowmP\":[\"Grams are usually clearer for small ingredients and metric recipes. Ounces are fine if the whole recipe and your scale stay in ounces. Pick one system per bake.\"],\"3bUZ78\":[\"化學圖表和安全性\"],\"3coptQ\":[\"透過中間步驟保持完全精度。給觀眾一輪：烹飪部落格可能會顯示小數點後一位；機械車間可能需要三個。在多步驟計算中提前捨入會產生原始測量中不存在的誤差。\"],\"3eng2d\":[\"Dimensional (volumetric) weight is a billing weight derived from package dimensions using a carrier divisor. You typically pay on the higher of actual scale weight and dimensional weight.\"],\"3gBC8W\":[\"有效數字應反映測量能力和功能需求。轉換捲尺尺寸後列出八位小數會假裝您沒有精度。檢查員應該被告知哪些數字是有效的，哪些是轉換顯示的假象。\"],\"3k5XM4\":[\"我們的轉換器專為準確性和速度而設計。與其他可能存在較小舍入誤差的工具不同，我們使用專門的庫來確保每個小數點都是正確的。這對於科學計算、工程任務或任何精確度至關重要的情況尤其重要。\"],\"3kl9_I\":[\"Writing 1.5 kg as 1.5 g on a scale that reads grams underdoses by 1,000×. Shipping dimensional weight in kg is unrelated to converting product mass to grams—keep those workflows separate. Jewelry grams are mass; carats are different.\"],\"3lxmj2\":[\"我們的公里 ↔ 英里轉換器頁麵包含常見道路距離的表格，因此您可以快速翻譯行程註釋。\"],\"3mhTKi\":[\"遠足地圖可能使用以米為單位的等高線間隔，而越野地圖則使用英里。 GPS 設備設定應與地圖和團體語言相匹配，以減少集合錯誤。\"],\"3pCUdM\":[\"全球可訪問性：\"],\"3r4LPB\":[\"微米 (μm) 涵蓋了電池和許多製造公差。奈米 (nm) 涵蓋可見光波長和奈米顆粒尺寸。 ångström (Å) 等於 0.1 nm 或 10⁻10 m，在晶體學和化學中的鍵長中仍然很常見。\"],\"3r5jgz\":[\"SI 純粹主義者喜歡納米或皮米，許多期刊都接受其中一種。協作時，就表格的單位達成一致，並在補充資料中保持一致的轉換。審閱者註意到圖 1 使用 nm 而表 2 使用 Å 時沒有轉換說明。\"],\"3tIoob\":[\"10 m/s is about 22.4 mph—a stiff cycling headwind. Terminal-velocity ballpark 50 m/s is roughly 112 mph before posture and drag details.\"],\"3u-0-0\":[\"提示：將工程圖端對端保存在一個系統（公製或英制）中。僅在專案邊界處進行轉換以避免公差疊加。當團隊跨越國家時，雙標籤高度和道路距離。\"],\"3u90fF\":[\"A height of 175 cm is 5.74 feet, usually spoken as 5 ft 9 in. A 240 cm curtain fabric cut is 7.87 feet—order 8 feet of material if the shop sells by the foot.\"],\"3vXqnf\":[\"一國際英哩正好等於 1.609344 公里。粗略估計，8 公里 ≈ 5 英里。\"],\"3vk9Xp\":[\"Minutes to seconds: multiply by 60. Hours to seconds: multiply by 3,600. Days to hours: multiply by 24. Reverse with division. For mixed inputs like 2 h 15 min 40 s, convert each part to seconds, add, then convert to the target unit once.\"],\"3z_7Nd\":[\"Use yards to metres when US fabric, turf, or concrete “by the yard” quotes must match metric project plans. Quilters and civil estimators working with mixed suppliers rely on this. One international yard is exactly 0.9144 m.\"],\"47xD74\":[\"Alternatively, convert pace to a speed in km/h, convert speed to mph, then convert mph back to min/mile. Use whichever chain produces fewer rounding steps for you.\"],\"49XKfg\":[\"A flight that leaves at 17:00 and lands at 19:00 local at the destination may last 8–12 hours depending on zones. Always trust block time (a duration) from the airline for “how long you sit,” and local times for “when to be at the gate.”\"],\"4FE7_g\":[\"為什麼我的蛋糕在正確轉換後仍然燒焦？\"],\"4HE7vS\":[\"Clinic forms may ask for kilograms while your bathroom scale shows pounds, or the reverse. Convert the reading you actually measured; do not “feel” a number in the other unit. A 2–3 lb morning fluctuation is normal; a unit mix-up of 2.2× is a medical-record disaster.\"],\"4JISh_\":[\"飛米\"],\"4O0cEB\":[\"How many pounds are in one kilogram?\"],\"4OnBIV\":[\"貿易技能中的英吋、英尺和碼\"],\"4Qgkrl\":[\"Dual-label key sessions: “5:30 /km (8:51 /mile) ≈ 10.9 km/h (6.8 mph).” The first time takes a minute; the clarity lasts a season.\"],\"4S_eXT\":[\"Convert litres to cubic feet when metric cooler, tank, or heater capacities must match US appliance and HVAC catalog language. Divide litres by about 28.3168. Importers localizing EU product sheets use this pair.\"],\"4SxPEz\":[\"Using ÷1.6 is fine for rough driving; for calibration use the exact factor. Wind forecasts in km/h vs mph change perceived severity—convert before comparing to Beaufort mental models. Do not convert pace min/km with a pure speed formula without inverting correctly.\"],\"4WS4sV\":[\"光日\"],\"4WT--N\":[\"面積測量表面積：長度的平方。體積衡量空間：長度的立方。如果沒有厚度或深度等附加信息，平方米 (m²) 無法轉換為公升（體積）。如果一個工具提供了這種轉換，那麼它要么是錯誤的，要么是默默地假設了一個高度。\"],\"4XMbOB\":[\"這兩個系統都不是比較正確的。一公尺的路和一碼的布料都可以測量長度。改變的是擴展、國際交流和保持算術簡單的容易程度。工程師、科學家和世界上大多數人都預設使用公制。某些地區的建築業、航空業、美國的烹飪業以及較舊的法律文件仍然嚴重依賴英製或美國的習慣單位。\"],\"4ZCZap\":[\"一公里 (km) 等於 1,000 公尺。它是道路距離、地圖和體育比賽的標準公制單位。\"],\"4Z_hj5\":[[\"tFrom\"],\" 至 \",[\"label\"]],\"4_SW3I\":[\"一平方毫米 (mm²) 等於 10⁻⁶ 平方公尺。工程圖和小部件橫截面通常使用它。\"],\"4bbTla\":[\"Convert pounds to kilograms or grams before combining with metric volumes. 1 lb ≈ 453.592 g. Kitchen scales that show ounces need the same care: convert oz → g, then apply density.\"],\"4bnTBN\":[\"在<0>長度</0>、<1>溫度</1>、<2>面積</2>和<3>體積</3>之間快速轉換。無論您是學生、工程師還是業餘愛好者，我們的工具都能提供從日常測量到高級科學數據的高精度結果。\"],\"4dfhhk\":[\"立方英里\"],\"4eyt5-\":[\"假設您需要將<0>\",[\"exampleInput\"],\"</0>\",[\"tFrom\"],\"轉換為\",[\"tTo\"],\"。使用與上述計算機相同的基本單元電橋，<1>\",[\"exampleInput\"],\"</1>\",[\"0\"],\"等於<2>\",[\"exampleOutput\"],\"</2>\",[\"1\"],\"。\"],\"4htqm_\":[\"Disclaimer | Units Converters\"],\"4izzev\":[\"日常流暢意味著無需計算器即可了解大致尺寸：信用卡長約 85 毫米；門口高約2m；城市街區各不相同，但通常只有幾百公尺； 5K 跑是 5 公里。\"],\"4jhles\":[\"正好一萬平方米。一公頃是每邊 100 公尺的正方形。\"],\"4oZ5j_\":[\"我可以僅從長度單位轉換池體積嗎？\"],\"4qZFYZ\":[\"板英尺\"],\"4qu2HU\":[\"In everyday speech, a year is what calendars do: birthdays, fiscal periods, and school terms follow Gregorian rules with leap days. In astronomy and many scientific constants, a Julian year is a fixed duration of exactly 365.25 days, each day 86,400 seconds—exactly 31,557,600 seconds.\"],\"4wUv2L\":[\"我們的 \",[\"tQuantity\"],\" 轉換器如何運作\"],\"4yOpty\":[\"Interval workouts that mix “400 m repeats” with “mph recovery jogs” need both length and speed converters. Write every line with units before you lace up.\"],\"4yUaO4\":[\"A 100 m dash is about 109.4 yards. Ordering 3 m of upholstery fabric means about 3.28 yards; round up if the bolt is sold in whole yards only.\"],\"5-L30Y\":[\"簡短的決策秘訣\"],\"528nU7\":[\"Proxima Centauri at about 4.25 ly is roughly 4.02×10¹³ km away. Saying that out loud shows why probes take decades even at high speed: kilometres make the gap concrete.\"],\"56W9Uj\":[\"A “5:00 min/km” pace is 12 km/h. A “8:00 min/mile” pace is 7.5 mph. Those are different efforts—convert carefully before you race your training partners’ screenshots.\"],\"58dnGV\":[\"Payroll and aviation sometimes use decimal hours (1.5 h). Sports and media use 1:30. To convert decimal hours to minutes, multiply the fractional part by 60. To convert hh:mm to decimal hours, divide minutes by 60. Never read the minutes field as a decimal fraction.\"],\"59sdtS\":[\"一奈米 (nm) 等於十億分之一公尺 (10⁻⁹ m)。它是光、奈米技術和薄膜波長的日常單位。\"],\"5A1BRJ\":[\"從 CAD 或 GIS 工具匯出的 CSV 有時會遺失單位元資料。在轉換之前重新連接單元，並檢查大小：500 平方米的房屋面積可能是平方米； 500 000 英畝的土地可能不是英畝。\"],\"5ABbuU\":[\"Assuming every “cup” is 250 mL when the recipe is US customary (240 mL) shifts sugar and flour enough to change texture. Scooping flour by volume is already imprecise—conversion cannot fix packing density. Liquid cups and dry cups are the same volume unit; weight still differs by ingredient.\"],\"5CuV4Q\":[\"面積測量表面積：房間以平方公尺或平方英尺為單位，土地以公頃和英畝為單位。選擇下面的起始單位，然後轉換為任何其他面積單位，無需舍入漂移。\"],\"5Fh9kd\":[\"US bathroom scales and forms almost never use stone. If you move between the UK and US, you will translate between stone↔lb and stone↔kg often. Freight and science do not use stone—keep it in the body-weight and informal UK context.\"],\"5Hk-XC\":[\"我們如何使用資訊\"],\"5JPpQY\":[\"The metre per second (m/s) is the SI derived unit of speed. Physics and engineering treat it as the base unit for velocity and speed conversions.\"],\"5MU6OU\":[\"如果孩子要旅行或閱讀國際媒體，請教他們這兩種系統。雙重讀寫能力是一種實用的生活技能，而不是一種政治宣言。廚房溫度計、道路地圖集和來自另一個國家的縫紉圖案足以練習轉換，而無需單獨使用工作表。\"],\"5P4d2U\":[\"請聯絡 Voyager Tecnologias LTDA 諮詢 Units Converters。發送回饋或透過電子郵件聯絡我們：voyagertecnologias@gmail.com。\"],\"5PxpgF\":[\"Oven roast at 180 °C is 356 °F (often rounded to 350 °F on US dials). A mild 22 °C room is about 72 °F—typical comfort wording in US building guides.\"],\"5Rjv-n\":[\"地塊面積可以是英畝；建築面積可以是平方公尺或平方英尺。他們測量不同的多邊形。如果轉換單位但混合了錯誤的多邊形，則容積率計算會失敗。\"],\"5_adq5\":[\"An hour equals 3,600 seconds, or 60 minutes. Civil timekeeping, labour, and travel durations are usually expressed in hours.\"],\"5eZ6SO\":[\"當以 ± 公差轉換標稱值時，轉換限值（上限和下限），然後重新表述標稱值和公差，或使用一致的捨入規則轉換標稱值和公差，以免無意中縮小允許區域。\"],\"5gLOyE\":[\"服務條款 | Units Converters\"],\"5i4RiS\":[\"A candy thermometer reading of 300 °F is about 149 °C for soft-crack stage in metric candy charts. Weather at 68 °F is 20 °C—handy when packing for a city that posts only Celsius.\"],\"5jFarL\":[\"我們的目標是僅收集運行和改進網站所需的內容：\"],\"5mk-lJ\":[\"在國際市場上，土地和房產的使用面積並排使用公頃和英畝。一公頃等於 10 000 平方公尺；根據國際定義，一英畝為 4 046.856 422 4 m²。房地產清單有時會激進地進行四捨五入——驗證調查平台，而不是行銷手冊。\"],\"5o6fJj\":[\"溫度選擇取決於您是否需要絕對熱力學溫度（開爾文）或面向人類的天氣和烹飪尺度（攝氏或華氏）。\"],\"5odHYG\":[\"Sliding three decimal places the wrong way turns 500 g into 500 kg. Nutrition labels in grams per serving still need portion count before totaling kilograms for bulk prep. Do not confuse g with mg on medicine labels.\"],\"5qFrDO\":[\"半導體製程節點歷史上使用奈米品牌；謹慎解釋行銷節點與實體門長度。儘管如此，奈米仍然是小型電子特徵的語言家園。關於奈米顆粒的材料論文同樣預設直徑為 nm，表面積為 m²/g，不要混合這些數量類型。\"],\"6-lWKx\":[\"一公尺比一碼長嗎？\"],\"61CiXo\":[\"Convert grams to milligrams when a lab balance reading in grams must match pharmaceutical or supplement labels in mg. Multiply grams by 1,000. Compounding and nutrition science use this constantly.\"],\"6A1R02\":[\"For exports, customs may care about net and gross mass in kilograms even when your commercial invoice was drafted in pounds. Keep both actual mass and package cube documented so logistics and compliance teams share one truth.\"],\"6AiOIQ\":[\"我應該如何比較測試中的轉換器結果？\"],\"6Al-Ue\":[\"After you trust net area. Add 5–15% (more for patterns), then convert to the seller’s unit if needed and round up to packaging.\"],\"6B5JWe\":[\"攝氏度和攝氏度\"],\"6DLZ9r\":[\"當您的來源資料、標準或儀器已報告該單位時，請選擇 <0>\",[\"tFrom\"],\"</0>。當與需要不同 \",[\"tQuantity\"],\" 約定的團隊、工具或文件協作時，請切換到 <1>\",[\"tTo\"],\"</1>。\"],\"6PMmOj\":[\"說明單位的不確定性。將 1.540 0 Å 轉換為奈米應保留有效數字：如果精度是真實的，則為 0.154 00 nm。\"],\"6PosYV\":[\"工程圖應聲明轉換政策。混合方法的全球團隊生產出幾乎適合的零件，這比明顯不適合的零件更糟。幾乎合適的零件會浪費檢查時間並削弱供應商之間的信任。\"],\"6RddZQ\":[\"A knot is one international nautical mile per hour, equal to 1852/3600 metres per second. Aviation and maritime navigation report speed in knots.\"],\"6TrT9O\":[\"英國食譜有時會使用英製品脫和公制重量——這種混合在當地有意義，但卻讓進口商感到困惑。對於便攜式版本，將液體轉換為毫升，將乾貨轉換為克。\"],\"6U7zRe\":[\"US customary tablespoons are 14.8 mL and Australian tablespoons are 20 mL—do not assume every tbsp is metric 15 mL. Heaping vs level spoons dominate error more than unit math. Do not convert spoon volumes to grams without the ingredient density.\"],\"6UYTy8\":[\"Minute\"],\"6VHY1j\":[\"5K 比賽是五公里還是五英里？\"],\"6VO62n\":[\"一立方公里 (km³) 等於十億立方公尺。地質學和海洋學將其用於巨大的自然體積。\"],\"6XgEPi\":[\"Hour\"],\"6bBy6I\":[\"公制與英制：您應該使用哪一種系統？\"],\"6clLDQ\":[\"A 12 oz steak is about 340 g—handy for metric doneness charts per centimetre thickness. First-class mail at 3.5 oz is about 99 g.\"],\"6dN923\":[\"Converting knots cleanly\"],\"6g7YAo\":[\"許多商店只驗證一個單位的範圍。使用錯誤的係數進行轉換，或在一個字段中將英尺/英寸與厘米混合，會觸發這些檢查。\"],\"6h3o07\":[\"腳（國際）\"],\"6hTphd\":[\"Convert avoirdupois pounds to kilograms for passport medical forms, EU shipping labels, and metric gym programs when the starting number is in pounds. Multiply lb by 0.45359237 exactly. Couriers and coaches use this daily.\"],\"6ho4DE\":[\"烘烤溫度：攝氏和華氏度\"],\"6j5rE1\":[[\"name\"]],\"6jG3Ph\":[\"Convert square centimetres to square inches for US packaging die-lines, bandage sizes, and small panel cutouts when the CAD file is metric. Divide cm² by 6.4516. Print finishers and medical device labeling use this often.\"],\"6m-c2x\":[\"Real-world example\"],\"6y0UdC\":[\"記住一些與你的身體和家庭息息相關的錨點：你的身高（厘米和英尺/英寸）；您的門寬度；本地賽道 100 m；在熟悉的道路上行駛一英里。錨點勝過抽象表格以進行快速估計。\"],\"7-1d79\":[\"如果軟體將 25.4 儲存為二進位浮點數，則在任何轉換運行之前可能已經出現輕微錯誤。乘以另一個不精確的因子會加劇誤差。即使演算法在概念上是正確的，斷言嚴格相等的往返測試也會失敗。\"],\"7-A57D\":[\"Programming libraries distinguish Instant/ZonedDateTime from Duration/Period. Convert seconds with duration tools; convert zones with zone databases (IANA). Do not roll your own offset table from memory.\"],\"71wsvF\":[\"杯子的一致性甚至更差。美國習慣杯、美國營養標籤法定杯和公制杯（通常為 250 毫升）都出現在食譜中。始終確定來源採用的杯子。當部落格省略該細節時，請謹慎轉換或找到相同食譜的加權版本。\"],\"7C1JIS\":[\"<0>同意偏好：</0>您是否接受或拒絕儲存在您的瀏覽器（localStorage）中的非必要cookie。\"],\"7C3Rik\":[\"天文單位\"],\"7CoI9M\":[\"Contact us at <0>\",[\"0\"],\"</0> if you spot an error or need clarification about how a conversion is defined.\"],\"7D3Du8\":[\"CAD 雙重尺寸標註應從主要單位導出次要單位，而不是交替使用相反的單位。基層單位擁有設計權。次要價值是溝通的輔助工具，而不是第二個真理來源。\"],\"7DaEzk\":[\"Shipping cares about mass and dimensional volume separately for billing. Density explains why pillows bill on volume and steel bills on mass, but the carrier formula still wins for price.\"],\"7Fd9fc\":[\"有關公制和英制單位、溫標、SI前綴、烹飪換算和精密測量的深入指南。\"],\"7Fpl88\":[\"Common mix-ups with land units\"],\"7FyB9w\":[\"Worked conversion patterns\"],\"7GXDvT\":[\"一毫米 (mm) 等於 0.001 公尺。它是小物體、工程圖和降雨量的常用日常公制單位。\"],\"7IA3Mr\":[\"Freight and courier services may use kilograms worldwide even when the shipper thinks in pounds. Dimensional weight is a separate rule (volume-based billing). Convert actual scale weight correctly first; then apply the carrier’s dimensional-weight formula in the unit the carrier specifies.\"],\"7IvdVj\":[\"Ordering from room perimeter instead of area. Perimeter helps trim length; it does not equal carpet area.\"],\"7JKA3u\":[\"現場清單\"],\"7Krvzl\":[\"Mixing troy ounces (precious metals) with avoirdupois ounces (food and freight). This site’s everyday ounce unit is avoirdupois. Gold and silver use a different ounce—do not convert jewellery the same way you convert flour.\"],\"7LsmlS\":[\"對於矩形：長×寬×平均深度。將所有三個長度保持在同一單位，計算立方長度（立方米或立方英尺），然後如果您的化學圖表需要升，則轉換為公升。\"],\"7QsmKa\":[\"如果您轉換存檔的法律描述，請記下測量機構使用的紀元和英尺定義。 GIS 專業人員關心這一點；後院園丁通常不會這樣做。\"],\"7Qx5-T\":[\"Portioning meal prep: convert the weekly protein target to grams, divide into containers, and ignore ounces until you publish a US-facing blog post.\"],\"7SXyp_\":[\"The console was likely in mph while you expected km/h (or the reverse). Check the unit label before you trust the number.\"],\"7SkS_Y\":[\"快速心算：將公頃乘以 2.47 估算英畝；將英畝乘以 0.4 估算公頃。然後用精確的轉換器進行精煉以進行法律工作。現場估算可以使用粗略的因素；合約和地籍更新不應該。\"],\"7TK6ys\":[\"Work shifts logged as “7.5 hours” are durations. Convert to minutes (450) for payroll systems that want minutes. Time-zone entry only matters for when the shift started, not for how long 7.5 hours is.\"],\"7U0oLh\":[\"艾薩克·牛頓根據自由冷卻材料和其他參考文獻對溫標進行了實驗。牛頓標度出現在一些轉換器中，作為一種歷史奇觀，在接近冰點時為零，在沸騰時具有較小的度數。\"],\"7UFvIc\":[\"雙精度足以進行單位轉換嗎？\"],\"7VxoBS\":[\"當您必須比較、製造、劑量或跨系統導航時進行轉換。如果當地建築規範、速度限製或包裝標籤已與您的工具匹配，請在該系統中工作並僅在介面（進口、出口和發布的規格）處進行轉換。\"],\"7_ePmj\":[\"Use density = mass / volume with consistent weight and volume units, convert kilograms, grams, litres, and cubic metres, and avoid cup-vs-gram mistakes.\"],\"7_lrbG\":[\"約塔梅特雷\"],\"7edIF8\":[\"避免在同一段中混合 nm 和 Å 而不進行轉換。專家可以切換；混雜的觀眾迷失了方向。當幻燈片從微米級的細胞寬度跳躍到奈米級的膜厚度且尺度之間沒有語言橋樑時，同樣的建議也適用。\"],\"7fyhDy\":[\"Two meanings of “year”\"],\"7h4xrB\":[\"Multiply mph by 1.609344 for an exact value. For a mental estimate, multiply by 1.6. Example: 70 mph ≈ 112.7 km/h.\"],\"7nkrrp\":[\"Track races may publish times to 0.01 s while road races use whole seconds. Converting a 3:45 marathon split into decimal minutes for pace math is useful; inventing hundredths the watch never measured is not. Preserve the precision you actually recorded.\"],\"7o1zK6\":[\"我們包括用於高級科學研究的罕見且精確的單位，例如 Planck 長度、玻爾半徑和 Ångström。\"],\"7r_Iz_\":[\"Using 4,000 m² per acre is a rough cut that drifts ~1.2%. Acre-feet measure water volume, not area—do not drop the “feet” and convert as pure acres. City lots listed in fractions of an acre need full decimal acres before multiplying.\"],\"7tI8CF\":[\"保留您實際使用的前綴的少量參考。您不需要記住 yocto 和 yotta 來進行建築工作；你確實需要毫冷、微冷和公斤冷。如果你閱讀材料或電子論文，請添加 nano；如果您使用行星或資料中心物理工廠規模，請添加兆級和千兆級。\"],\"7tkhyb\":[\"釀造和飲料行業歷來依賴當地定義的桶子和加侖。現代品質系統越來越標準化升，同時保留傳統的行銷名稱。盡可能將行銷單位視為標籤，將生產單位視為公升。\"],\"8-CHL5\":[\"提示：不要將地板平方米與油漆升數混淆－面積和體積是不同的數量類型。\"],\"81pHBk\":[\"Convert litres to cubic metres for water tanks, aquarium sums, and HVAC airflow-adjacent liquid volumes when SI building models want m³. One cubic metre is exactly 1,000 L. Civil and aquarium hobby math share this pair.\"],\"82_S3f\":[\"Dividing by 2.0 overstates m/s. Posted ramp speeds in mph become unsafe inputs if left unconverted in a metric model. Treadmill mph to m/s uses the same factor as vehicle speed.\"],\"82hkkt\":[\"測量鏈（岡特鏈）等於 66 英尺，或約 20.117 公尺。它是英語國家土地測量的基礎。\"],\"82v0CX\":[\"簡單、快速、科學級精度。在幾秒鐘內將任何東西從奈米轉換為光年。\"],\"87ZOlX\":[\"A 18 ft³ refrigerator is about 510 L—compare to European fridge labels in litres. A 2 ft³ minifridge is roughly 56.6 L of internal volume.\"],\"8AULTO\":[\"它是如何運作的\"],\"8BQeht\":[\"Example: 2.5 Julian years = 2.5 × 365.25 = 913.125 days. Example: 10,000 days ÷ 365.25 ≈ 27.378 Julian years. Keep enough decimals when the result feeds another scientific formula.\"],\"8HXvHC\":[\"SI 透過現代計量學中的基本常數定義了開爾文，完成了從冰浴到量子標準的旅程。出於直覺，日常用戶仍然會轉換為攝氏度。實驗室筆記本仍應記錄感測器韌體發出的量程—此處的假設會導致多度偏差。\"],\"8IehbN\":[\"在線分享食譜時，請包括兩個秤。您的國際讀者不必猜測您指的是哪種「氣痕」文化。\"],\"8Jd9P3\":[\"公司：\"],\"8P_FxZ\":[\"Compute area in square metres, then multiply by about 10.7639—or use an area converter. Do not convert only one wall length to feet.\"],\"8QF2qf\":[\"Convert feet per second to mph when a US lab, wind-tunnel, or projectile chronograph reads ft/s but you want road-speed intuition. Divide ft/s by 1.46667, or use mph = ft/s × 15/22. Safety briefings often want mph.\"],\"8Qpa7Q\":[\"硬體加速和 GPU 管道通常會強制浮動。在這些情況下，請在 CPU 或伺服器上保留十進位的權威轉換，並將 GPU 浮點視為顯示或中間近似值。\"],\"8S1T6W\":[\"150 seconds of rest is 2.5 minutes between sets. A 3,600-second timeout is 60 minutes—one hour for a long job.\"],\"8TLHSU\":[\"When teaching mixed audiences, give knots first (ops truth) and a converted gloss second (public truth).\"],\"8U1Wou\":[\"土地面積與水量\"],\"8WkbAX\":[\"As a duration unit in simple converters, 1 day = 24 hours. Civil clock days can be 23 or 25 hours across daylight-saving transitions.\"],\"8c995T\":[\"是的。絕對零度為 0 K，等於 -273.15 °C。普通的熱力學系統沒有達到低於該值的溫度。\"],\"8eHaYx\":[\"Measuring real rooms\"],\"8euFNe\":[\"瀏覽全部指南\"],\"8fs_RU\":[\"Convert metres to feet for room dimensions, athletic track splits, and building heights when the source is metric but the audience thinks in feet. Architects reviewing SI drawings for a US client and runners comparing race distances use this pair often. One metre is about 3.28084 international feet.\"],\"8g-qDy\":[\"提示：將工程圖端對端保存在一個系統（公製或英制）中。僅在專案邊界處進行轉換以避免公差疊加。\"],\"8iPd_0\":[\"本服務以<0>\\\\「按原樣」</0> 和<1>\\\\「可用」</1> 提供，不提供任何形式的明示或暗示的保證，包括但不限於準確性、完整性、適銷性或針對特定用途的適用性。\"],\"8jHem_\":[\"種子和施肥量將面積單位與質量混合：公斤/公頃與磅/英畝。分別轉換面積和質量，然後合併。維度分析可防止比率倒掛。\"],\"8lvaZJ\":[\"Why bakers prefer weight\"],\"8nJn60\":[\"Convert miles to kilometres when US highway distances, flight route charts in statute miles, or bike computer settings must match metric signage and European navigation. Couriers quoting door-to-door miles for overseas clients need the km figure. Multiply miles by 1.609344.\"],\"8vdUGj\":[\"Dividing by 3,600 incorrectly as 3,000. Displaying only whole hours hides useful fractional hours for short jobs. Stopwatch sports times in seconds convert cleanly; including countdown pauses is a measurement issue.\"],\"8zKQrL\":[\"團隊\"],\"9-uAp_\":[\"Pediatric and athletic charts may use kilograms internationally. Convert once from a measured scale reading. Re-weigh rather than eternally converting an old stone value after training cycles.\"],\"94_ABr\":[\"10 st ≈ 63.5 kg ≈ 140 lb; 11 st ≈ 69.9 kg ≈ 154 lb; 12 st ≈ 76.2 kg ≈ 168 lb; 14 st ≈ 88.9 kg ≈ 196 lb. Anchors help conversation; exact converters help forms.\"],\"957mDG\":[\"Julian calendar dates (the historical calendar Julius Caesar introduced) are yet another topic. “Julian year” as a 365.25-day unit should not be confused with Julian calendar day numbering or Julian Day Count (JD), though the shared adjective confuses newcomers.\"],\"959Vfh\":[\"攝氏度這個詞在歷史上描述了一百級的等級。如今，攝氏已成為科學交流中的首選名稱，與開爾文正式聯繫在一起。\"],\"96dZEM\":[\"Practical workflow\"],\"9AIeUi\":[\"Get mass units straight\"],\"9B12Hm\":[\"News articles sometimes convert knots to mph incorrectly by using 1.6 (the statute mile factor) instead of about 1.15. When accuracy matters, re-convert from the original knot value.\"],\"9BCuew\":[\"Tare the scale (subtract pallet or container weight) when the rate applies to net shipment weight. For multi-piece shipments, know whether the carrier sums chargeable weights per piece or allows shipment-level aggregation—those rules change optimization tactics.\"],\"9Bp5Rv\":[\"其他因素經過測量或歷史四捨五入。較舊的測量英尺、當地土地測量或實驗常數可能帶有不確定性。當一個因子是近似值時，轉換後的結果會繼承這種不確定性——如實報告重要數字。\"],\"9DO-KV\":[\"建立個人轉換錨\"],\"9E6g4y\":[\"APIs should store instants in UTC or with explicit offsets, and store durations in seconds. Display layers apply zones. Mixing display strings into arithmetic is the bug.\"],\"9F1FDN\":[\"它們來自加侖的不同歷史定義。美國液體加侖定義為 231 立方英寸（約 3.785 公升）。英國歷史上使用的英制加侖較大（約 4.546 L）。務必檢查配方、燃油經濟性資料或化學品安全表所假定的加侖數。\"],\"9FEF2i\":[\"立方碼\"],\"9Fk_m2\":[\"此處，公制滴落量標準化為 50 微升。藥房和實驗室說明有時會透過滴劑來計量液體。\"],\"9INfx0\":[\"遵循期刊和您所在領域的規範。晶體學通常仍然使用埃格斯特倫（ångströms）；奈米科學的大部分內容更喜歡納米。手稿的一致性最為重要。\"],\"9K1siw\":[\"英制（國際）\"],\"9KfN-m\":[\"A 20-knot wind is 37 km/h—near a strong breeze on land-based km/h apps. A ship cruising at 15 kn makes about 27.8 km/h over water.\"],\"9MpX2H\":[\"第三方廣告\"],\"9OMJOQ\":[\"How many days are in a Julian year?\"],\"9OP0of\":[\"Example bridge: speed (km/h) = 60 ÷ pace (min/km). Pace (min/km) = 60 ÷ speed (km/h). For miles: speed (mph) = 60 ÷ pace (min/mile). Always track whether the pace distance is a kilometre or a mile.\"],\"9Qs99X\":[\"電子郵件：\"],\"9R2Q_O\":[\"Area first, then conversion\"],\"9Ru4GA\":[\"平方奈米\"],\"9T3uW6\":[\"CNPJ:\"],\"9Z89rA\":[\"距離單位顯示在燃油經濟性（L/100 公里 vs 英里/加侖）。僅換算旅行長度並不能換算經濟數據－經濟數據需要有自己的公式。\"],\"9aBORt\":[\"面積和體積需要平方和立方前綴\"],\"9aKMyD\":[\"Mental anchors\"],\"9brUFH\":[\"Convert days to hours for shipping ETAs, antibiotic courses, and server uptime when plans use days but operations think in hours. Multiply days by 24 for civil mean days. Logistics and on-call rotations rely on this.\"],\"9cgJA5\":[\"這個網站如何改進？\"],\"9fW-dh\":[\"If a log says a job finished at 01:10 after starting at 23:50, the duration is 80 minutes (or 1 h 20 min), including the midnight crossing. Convert that duration with time units; do not subtract the clock faces as decimal numbers without handling day rollover.\"],\"9hxz2e\":[\"持久的長度範例\"],\"9iWFRw\":[\"圓形英制\"],\"9j9_c5\":[\"對於混合團體，請在共享行程中發佈公里和英里。雙倍總數阻止「還能走多遠？」車裡的爭吵。\"],\"9l599X\":[\"我應該在論文中使用埃姆還是奈米？\"],\"9mFi34\":[\"Using 2 or 4 feet per yard is a quick mental error. Square yards and cubic yards are not converted by multiplying by 3—that factor is only for linear yards. Keep partial yards (2.5 yd = 7.5 ft) as decimals.\"],\"9mS3qf\":[\"未找到類別 | Units Converters\"],\"9pJyPJ\":[\"天文單位 (AU) 大致相當於地球與太陽的距離，約 1.496 × 10^1 公尺。行星軌道和太空船軌跡經常使用 AU。一光年約 63 241 天文單位。\"],\"9utJAy\":[\"工作習慣：將 12 英尺轉換為公尺。準確使用 1 英尺（國際）= 0.3048 m。 12 × 0.3048 = 3.6576 m。對於顯示，您可以根據公差寫入 3.658 m 或 3.66 m。\"],\"9wG3f-\":[\"Packaging choices that change chargeable weight\"],\"9wW_0V\":[\"Nutrition labels and package net weights\"],\"A2Nh9c\":[\"了解 Units Converters 如何收集和使用數據，包括 Cookie、PostHog 分析和 Google AdSense 廣告。\"],\"A3LmyE\":[\"Convert seconds to hours for uptime reports, render-farm jobs, and endurance sports when logs show seconds but humans want hours. Divide seconds by 3,600. Cloud billing dashboards often store seconds underneath.\"],\"A5neWO\":[\"相關換算器\"],\"ADsjhY\":[\"烹飪後果\"],\"AGI27x\":[\"適合學生和專業人士的高精度單位轉換。立即轉換數百個單位。\"],\"AHRDPK\":[\"溫標描述了物體的熱度或冷度。攝氏溫度和華氏溫度主導著日常生活；開爾文是SI科學標度。使用精確的公式在它們之間進行轉換，而不是浮點快捷方式。\"],\"AIqsCx\":[\"Convert acres to square metres when a US land deed in acres must feed metric civil engineering, drainage calculations, or EU-style planning apps. One acre is exactly 4,046.8564224 m². Surveyors and solar designers use this for panel layout density.\"],\"ALn0nW\":[\"為什麼溫度轉換不同？\"],\"AO7lxi\":[\"立方微米\"],\"AP4oUf\":[\"平方英里\"],\"ASs9cS\":[\"Exactly 60 seconds make a minute; 60 minutes make an hour; 24 hours make a day in ordinary civil usage. Those ratios are exact for conversion between these units. Mistakes come from treating decimal hours like sexagesimal minutes—writing 1.30 h when you mean 1 h 30 min (which is 1.5 h).\"],\"AWwdQz\":[\"Age, birthdays, and why they diverge\"],\"AXEawP\":[\"Microgram\"],\"AXhspr\":[\"歐洲產品資料表以平方公尺為單位；許多北美床單使用 ft²。如果安裝人員和供應商不同意，請保留包含兩欄的單一項目表。\"],\"AXoYRC\":[\"Tonne (Metric)\"],\"AZvQdm\":[\"每次轉換都會經過精心定義的 \",[\"tQuantity\"],\" 基本單位。我們使用任意精確度的十進制算術，因此科學工作、家庭作業和專業估計的結果保持穩定。\"],\"A_E97M\":[\"ERP 系統中的自動轉換器需要對貨幣相關數量和規定尺寸進行十進制算術。二進制浮點剩餘物顯示為植物之間不匹配的雜湊值。\"],\"A_Yltl\":[\"由於在日常使用中 1 Å = 10⁻10 m，因此換算後是 10 的乾淨冪，非常適合十進制算術，而且與常規單位因子相比，更不容易出現奇異的浮點戲劇。仍然標記每一列；乾淨的數學並不能成為模稜兩可的標題的藉口。\"],\"Ab1IcB\":[\"在線上分享您自己的食譜時，請在杯子旁邊發布毫升和克。每個國家的未來讀者都會感謝您，並且您將減少真正屬於單元問題的支援問題。\"],\"Aex9bg\":[\"大約 9.46 兆公里（9.46 × 10^2 公里），取決於所使用的確切年份定義。為了進行精確的工作，請使用轉換器記錄的常數透過儀表進行轉換。\"],\"Af82OU\":[\"Using 2.2 lb/kg is fine for luggage estimates but drifts on commercial invoices. Do not confuse avoirdupois pounds with troy pounds used for precious metals. Force in pounds-force vs mass in pounds is a physics trap—this conversion is mass to mass.\"],\"Afd4_y\":[\"Converting km to miles then forgetting to square the factor (use ÷2.59, not ÷1.61) understates area badly. Lakes and admin boundaries may use different shoreline rules—unit conversion does not fix definition differences. Do not mix nautical miles into land area.\"],\"AmmtnH\":[\"衝擊、氯和酸性產品可以使用不同的圖表約定。將體積一次轉換為您可以為每個產品重複使用的「家庭單位」。\"],\"ApnX7Q\":[\"Convert grams to kilograms for shopping, lab reagents, and postage when fine scales use grams but tariffs and recipes batch in kilograms. Divide grams by 1,000. Food service and compounding pharmacies jump this scale often.\"],\"AqwQEc\":[[\"0\"],\" | Units Converters 指南\"],\"B0NIBw\":[\"閱讀較舊的英國資料時，除非另有說明，否則假設為英制加侖。閱讀美國材料時，除非指定公制杯子，否則假定採用美國液體測量。\"],\"B3phg2\":[\"大眾科學青睞光年，因為旅行時間的比喻很直觀。研究論文通常傾向於秒差距。它們之間的轉換是透過米進行常規長度轉換。\"],\"B6ZO29\":[\"溫度轉換是仿射（比例加偏移），而不是簡單的乘法。這就是「除以二」民間傳說失敗的原因。使用適當的轉換器或精確的公式。\"],\"B6_cWQ\":[\"簡單的烘焙工作流程\"],\"BB3hek\":[\"Race finish time ≈ pace × distance when units match. Convert a marathon distance to kilometres or miles to match your pace unit before multiplying. A marathon is 42.195 km or 26.21875 miles—not 42 miles.\"],\"BQPexS\":[\"Human age in years is a civil concept tied to calendar dates, not a pure second count divided by 31,557,600. Leap days, time zones, and local midnight rules affect birthday boundaries. Do not convert a person’s age with Julian years unless you are doing a physics-style duration exercise and say so.\"],\"BR8_kT\":[\"A 3 m³ water delivery is 3,000 L—about sixty 50 L barrels. An aquarium billed as 0.36 m³ is a 360 L tank in hobby shop language.\"],\"BRAW5m\":[\"儀表板和 UI 轉換器應預設為區域設定敏感的單位，但允許覆蓋。記住用戶偏好，而不違反法律標籤要求。記錄的分析事件應儲存規範單位，以便偏好變更不會破壞歷史聚合。\"],\"BTiJ7H\":[\"廚房的核心體積關係\"],\"BVxiN6\":[\"對於海洋和航空而言，將海裡分開——它們與法定英里不同。\"],\"BXmAOD\":[\"生物學和機械加工中的微米\"],\"BcL8Ac\":[\"Do I need a time zone to convert hours to minutes?\"],\"BiFdAo\":[\"開爾文溫度和絕對溫度\"],\"BmfykU\":[\"指南\"],\"BmsDT1\":[\"A 23 kg airline allowance is about 50.7 lb—just over a common 50 lb US checked-bag limit. A 100 kg barbell is roughly 220.5 lb on a US plate math board.\"],\"BnJzQv\":[\"了解 Units Converters、我們對科學精確度的承諾、零捨入誤差轉換工具背後的技術。\"],\"Bproz9\":[\"Learn how carriers bill the higher of actual weight and dimensional (volume) weight, convert kilograms and pounds correctly, and measure boxes so quotes match invoices.\"],\"BpyhsK\":[\"km/h, mph, and m/s in reports\"],\"BqL2-s\":[\"美國以外的大多數醫療和 ID 系統都以厘米為單位儲存高度（例如 175 公分）。米 (1.75 m) 在科學文本中更清晰，但在需要整數厘米的表格中卻很尷尬。\"],\"Br0a7Q\":[\"A half-acre suburban lot is about 2,023 m². A 10-acre solar field offers roughly 40,469 m² of land before setbacks and roads.\"],\"Bsnqds\":[\"提示：開爾文在 SI 書寫中從不使用度數符號（K，而非 °K）。 1 K 的變化相當於 1 °C 的變化。\"],\"Bum03c\":[\"Logging “job took 2:30” without saying h:mm vs hh:mm:ss recreates decimal-hour bugs. ISO-8601 durations (PT2H30M) fix the ambiguity.\"],\"BxXGvi\":[\"一分米 (dm) 等於 0.1 公尺或 10 公分。它出現在公制教育和一些工業規範中。\"],\"C-H7bp\":[\"責任限制\"],\"C3r5wf\":[\"一公尺等於 1 000 毫米、1 000 000 微米或 1 000 000 000 奈米。從nm爬升到m就是爬十的九次方。這一跨度涵蓋了 DNA 寬度、細菌、人類毛髮、昆蟲和人體尺度的物體——這也是科學傳播如此依賴尺度階梯的原因。\"],\"C420Ed\":[\"付諸實踐\"],\"C4gpAv\":[\"當結果看起來令人驚訝時，請詢問您是否轉換了單位或意外轉換了數量。這個問題就可以拯救專案。第二個快速檢查是幾何的：這個數字是否意味著深度、厚度或從未說明過的覆蓋率？缺少幾何形狀通常意味著有人將面積視為體積。\"],\"C7uWe7\":[\"本隱私權政策解釋了當您使用 Units Converters 時，Voyager Tecnologias LTDA（「我們」）如何收集、使用和分享資訊。\"],\"C7uhe0\":[\"Ounces and pounds in US recipes\"],\"C87HOb\":[\"公制和SI一樣嗎？\"],\"CAPENq\":[\"不會。與 °C 和 °F 不同，現代風格寫的是 300 K，沒有度數符號。單位是開爾文。\"],\"CHp68X\":[\"Label every log line: distance unit, volume unit, economy style. Dual-display dashboards are fine; dual-meaning spreadsheets are not.\"],\"CKIz2Y\":[\"永不失敗的轉換模式\"],\"CKM_It\":[\"一國際英畝約等於 4,047 平方公尺。它仍然是美國和英國的主要陸地面積單位。\"],\"CKyk7Q\":[\"返回\"],\"CPaJqI\":[\"Airspeeds and ATIS winds are typically in knots. One knot = 1.852 km/h = about 1.15078 mph. When a POH lists V-speeds in knots, convert for a passenger explanation if you want—but memorize and fly the knot values you trained with.\"],\"CU9R4b\":[\"We calculate conversions with arbitrary-precision decimal arithmetic (Decimal.js) and published unit definitions. Results are intended for learning, everyday planning, and general technical reference.\"],\"CWPZJa\":[\"英畝英尺\"],\"CZpj_s\":[\"Using “2.5 acres per hectare” is close but high by about 1%. Confusing hectares with square kilometres (100 ha = 1 km²) blows land deals by two orders of magnitude. Pasture stocking rates change with area unit—convert area before applying head-per-acre rules.\"],\"CbTonE\":[\"極端單位教導尺度堆疊：從Planck長度到可觀測宇宙跨越了幾十個數量級。前綴米和科學計數法是橋樑。實驗室牆上的一頁刻度梯（nm、μm、mm、m）比另一張前綴瑣事幻燈片可以防止更多錯誤。\"],\"CdAYjA\":[\"如果你始終如一的話，這兩種方法都有效。大多數人以一個單位計算面積，添加廢物，然後轉換為供應商的包裝單位。\"],\"CdD4XN\":[\"精密加工和計量可能會以微米（或商店行話中的微米）為單位指定公差。確認繪圖的微米是否意味著微米——在現代實踐中幾乎總是肯定的。當圖紙將微米公差與英寸公差混合在一起時，請在向客戶報價之前將系統轉換為權威系統。\"],\"CeG8fO\":[\"If you convert metres to feet on only one side of a rectangle before multiplying, the area is wrong. If you convert both sides to feet and multiply, you get square feet directly. If you multiply in metres, convert with an area converter. Pick one path and stay on it.\"],\"CgfJlz\":[\"<0>使用資料：</0>查看的頁面、根據 IP 得出的​​大致位置、裝置/瀏覽器類型以及推薦資訊 — 通常在您同意後透過分析工具取得。\"],\"CjGnuz\":[\"Checklist before you buy a label\"],\"CjTgKQ\":[\"Car drivers often think in mph or km/h and underestimate boat/aircraft speeds quoted in knots because the numbers look “smaller.” Fifteen knots is not a jogging pace—it is about 28 km/h over ground if SOG matches.\"],\"CngmkZ\":[\"建立對從奈米到米的長度的直覺——十的冪、日常類比以及跨 SI 前綴的乾淨轉換習慣。\"],\"CnvyXZ\":[\"為什麼攝氏與開爾文大小相同？\"],\"CpMczN\":[\"若要將英里每小時轉換為公尺每秒，請分別轉換長度和時間，然後合併。寫出因子的完整乘積，以便取消每個不需要的單元。一旦你知道了複合尺寸，同樣的方法就可以擴展到密度、壓力和能量。\"],\"CqR5NF\":[\"電子表格有時會將溫度儲存為標題中沒有單位的數字。然後下游腳本應用錯誤的公式。始終用刻度標記列，包括度數符號或字母 K。\"],\"CrLxAB\":[\"Dividing by 365 only ignores the average leap day. Using 365.2425 (Gregorian) is better for civil history, not for Julian-year based constants. Do not convert “trading days” with 365.25.\"],\"CrsICs\":[\"平方米和平方公里是SI友善的面積單位。全球土地測量均採用公頃（1 公頃 = 10 000 平方公尺）。英畝在美國土地主題中占主導地位，並出現在許多英語財產記錄中。國際投資者通常需要將這三項內容整合到一份情況說明書中。\"],\"CuqvVE\":[\"健行和跑步活動\"],\"CuujzZ\":[\"Convert kilometres to miles for road trips, race results, and fuel economy discussions when maps or cars show km but drivers think in miles. Tourism, logistics, and running (5K, 10K) all cross this boundary. One international mile is exactly 1.609344 km.\"],\"Cvs5DP\":[\"Example directionality: about 8 L/100 km is roughly 29–30 US mpg (order of magnitude check). Always recompute with exact factors for claims or regulations.\"],\"D16asK\":[\"主要的\"],\"D1yKic\":[\"Layover math: if landing is at one local time and departure at another, convert both to UTC (or another single offset), subtract to get a duration in seconds or minutes, then format. Do not convert time zones by “adding duration units” blindly.\"],\"D2P6Qz\":[\"A detector cooled to 77 K is about −321 °F—colder than dry ice (−109 °F). Human skin temperature ~306 K is about 91 °F, matching infrared thermometer expectations.\"],\"D6nVvu\":[\"公司詳情\"],\"D73kiV\":[\"為什麼我的地板報價與計算器不同？\"],\"D8Thx0\":[\"Cubic feet appear in US tanks and fridges. Convert ft³ → m³ or litres before using a metric density table.\"],\"D8cLPv\":[\"Confusing hectolitres with hectolitres of pure alcohol (a tax statistic) versus beer volume. Using ×1,000 (as if converting kL) overshoots. Decalitres (10 L) are another step—do not mix daL and hL labels on farm tanks.\"],\"DB6GbG\":[\"Switch inches to feet when a tape reading in inches is longer than a foot and you need architectural or lumber language (room height, joist spacing, fabric cuts). Carpenters often measure in inches then report in feet and leftover inches. Twelve international inches make exactly one foot.\"],\"DB7w-2\":[\"飛米 (fm)，又稱費米，等於 10⁻15 公尺。核物理學家它來測量原子核和核子的大小。\"],\"DCLceB\":[\"長度測量距離－從材料科學中的奈米到天文學中的光年。該中心收集日常和科學長度單位，因此您可以打開任何對進行公式、表格和高精度轉換。\"],\"DGCK_s\":[\"Not professional advice\"],\"DHuMm6\":[\"Convert hectolitres to litres for brewery output, wine harvest tanks, and agricultural liquid fertilizer when industry quotes hL but cellar or field gear is labeled in L. Multiply hL by 100. European beer statistics are often in hectolitres.\"],\"DLKAlh\":[\"Convert hours to seconds for computation timeouts, video timecode budgets, and physics problems that need SI seconds from a human hour count. Multiply hours by 3,600. Software and lab DAQ systems prefer seconds.\"],\"DPKPR5\":[\"60 mph is exactly 88 ft/s—the classic driving-physics mnemonic. A baseball at 90 mph is 132 ft/s toward the plate.\"],\"DPodsc\":[\"一阿米 (am) 等於 10⁻18 公尺。當描述與原子核大小相當的距離時，它很有用。\"],\"DQIUZW\":[\"Using “3 feet per metre” undershoots by nearly 10%. Ceiling heights listed as 2.4 m are about 7.87 ft, not 8 ft—important for ladder and furniture clearance. Do not mix statute miles (for long distance) into short metre-to-foot room math.\"],\"DSQp0D\":[\"Is 23 kg the same as 50 lb for airline bags?\"],\"DSdsOn\":[\"No. One hour is always 60 minutes as a duration. Time zones only change clock labels for moments in time.\"],\"DU39ti\":[\"350°F 是攝氏多少度？\"],\"DVjsxz\":[\"Rounding rules matter as much as the divisor. Some carriers round each dimension up to the next centimetre; others round the final chargeable weight up to the next half kilogram. Convert units first, then apply rounding in the order the tariff states.\"],\"DWgR4U\":[\"我們使用Google AdSense來顯示廣告。 Google 及其合作伙伴可能会根据您之前访问本网站或其他网站的情况，使用 Cookie 或类似技术来投放广告，但须遵守您的同意选择。您可以在<0>Google 廣告政策</0>了解更多信息，並在<1>Google 廣告設定</1>管理廣告個人化。\"],\"DY9sZd\":[\"了解這些尺度的存在有助於閱讀較舊的論文，但對於新的工作，更喜歡使用攝氏度來表示交流，使用開爾文來表示絕對熱力學量。\"],\"DYR0BH\":[\"我應該對每次測量進行雙重標記嗎？\"],\"DZkjcm\":[\"小數庫（例如，decimal.js、Big.js 或語言本機小數）以 10 為基數儲存數字。精確的小數因數（例如 0.3048 和 0.001）在所選精度範圍內保持精確。關心正確性的單位轉換器通常透過十進制基本單位進行轉換。\"],\"DZsWq3\":[\"什麼是光年？距離，而不是時間\"],\"DbDx5L\":[\"一國際英里正好是 1.609344 公里。對於旅行計畫來說，這個因素就足夠了。您很少需要比十分之一公里或英里更高的精度。\"],\"DbFygU\":[\"Exact relationship: 1 mph = 1.609344 km/h because the international mile is exactly 1.609344 km and the hour is the same in both units. Conversely, 1 km/h ≈ 0.621371192 mph. For dashboard glances, many drivers remember “multiply mph by 1.6” or “multiply km/h by 0.62,” then refine when planning.\"],\"Dc6r_W\":[\"測量腳和歷史警告\"],\"Dd4MGI\":[\"支援電子郵件：<0>\",[\"supportEmail\"],\"</0>\"],\"Dd8R82\":[\"我們可能會不時更新本隱私權政策。當我們這樣做時，頂部的「最後更新」日期將會改變。更改後繼續使用網站即表示您接受更新後的政策。\"],\"DdkR-D\":[\"描述您的問題，我們會盡快回覆您。\"],\"DeHj7V\":[\"海拔增益也是一種長度——通常以公尺或英尺為單位。與水平距離分開轉換增益；它們是計劃中的不同列。\"],\"DeyDo0\":[\"國際轉帳\"],\"Dg4jBX\":[\"攝氏征服了國際天氣預報、美國以外的烹飪以及大多數工程教育。它與開爾文度大小一致，使得科學轉換變得整潔。\"],\"DkfdV1\":[\"是的。一公尺約 1.094 碼，約 3.281 英尺。一米比一碼稍長。\"],\"DpUgLQ\":[\"用於轉換任何配方的可靠工作流程\"],\"DqGaXj\":[\"將單元與任務相匹配\"],\"DsvDLu\":[\"A metric tonne (t) equals 1,000 kilograms. Industry, shipping, and agriculture use tonnes for bulk cargo and large loads.\"],\"Dt2lOd\":[\"尺度直覺是科學教育、微加工和生物學領域的專業技能。轉換器給出數字；類比給出判斷。擁有一組共同地標的團隊可以更少地浪費時間爭論結果是否合理。\"],\"DxvqBO\":[\"©\",[\"0\"],\"Units Converters。版權所有。\"],\"Dz_BPx\":[\"華氏度的實用刻度\"],\"E30KJo\":[\"Treating 1/8″ as “3 mm” (true value ≈ 3.175 mm) stacks error across a part with many holes. Fractional inches must become decimals before multiplying. Do not confuse thousandths of an inch (mil) with millimetres—1 mil is 0.0254 mm, not 1 mm.\"],\"E9jbKj\":[\"一百公升 (hL) 等於 100 公升。釀造、葡萄酒生產和穀物貿易歷來都青睞百升。\"],\"EAX9Yw\":[\"No. Fluid ounces measure volume; scale ounces measure mass. Convert volume and mass separately, using density if you must bridge them.\"],\"ECCEhO\":[\"一立方碼約等於 0.765 立方公尺。美國的建築和景觀美化以立方碼購買混凝土、土壤和覆蓋物。\"],\"ED605G\":[\"實用的財產和農業例子\"],\"EFwY8C\":[\"在轉換工程常用單位時，首選精確的 SI 因子。喜歡貿易和土地的書面法律定義。僅在滿足這些約束後才傾向於在某個領域舉行社區會議。\"],\"EHFvuN\":[\"軟體預設值會影響一切。 CAD 模板、感測器韌體和 CSV 導出器會默默地選擇單位並對其進行審核。項目開始時十五分鐘的預設審查可以防止隨後數週的法醫單位考古工作。\"],\"EHclsu\":[\"秒差距更大——大約 3.26 光年。專業天文學通常喜歡秒差距；外展通常喜歡光年。\"],\"EIl6-2\":[\"Our Julian year ↔ day converter pages exist specifically to keep that definition visible—use them when reconciling catalogue values or teaching why a light-year is a length.\"],\"ENpdhX\":[\"Units Converters | Fast & Precise Unit Conversion Tool\"],\"EPtcRf\":[\"<0>溫度：</0>攝氏度、華氏度、開爾文度和牛頓度。\"],\"EUgW7r\":[\"經典的 0.1 + 0.2 問題遇到單位\"],\"EV9SSM\":[\"孩子們\"],\"EWZu3-\":[\"GPX 工具有時會在內部預設使用儀表。匯出設定可以靜默切換顯示單位；在共用路線之前驗證總總數。\"],\"EYzeDq\":[\"一立方英尋約等於 6.12 立方公尺。歷史上的海運貨物和疏浚環境使用立方英尋。\"],\"EcmlKU\":[\"生物學和化學總是以微升和納摩爾濃度來討論。精密零件的機械圖可能會標示微米公差。電子產品從微米特徵尺寸遷移到奈米節點——前綴是產業詞彙的一部分。\"],\"EghcSN\":[\"選擇語言\"],\"EgpmZP\":[\"Multiplying by 100 or 10,000 from digit-counting slips. Concrete “cubic metres” are solid volume; do not assume the same number of litres of mix water without the recipe. Gas metres in m³ are not liquid litres without density and state conditions.\"],\"EiLAfk\":[\"攝氏度換算華氏度：°F = °C × 9/5 + 32。華氏度換算攝氏度：°C = (°F − 32) × 5/9。將偏移量和 9/5 因子一起記住－丟掉任何一個步驟都是常見的課堂錯誤。\"],\"Ek008v\":[\"當您需要國際協作、科學報告或簡單擴充時，請選擇指標。當您的本地規範、工具和供應商已經存在時，請選擇英製或美國習慣，並記錄選擇。如果兩個值都來自一個主單元，則二維圖紙可以在車間提供幫助。\"],\"EnxBSk\":[\"Jet streams and ATIS winds are typically in knots. Airport visibility and runway lengths may use metres or feet—different quantities. Do not treat a wind of 15 kt like 15 km/h; that underestimates wind by nearly half.\"],\"EpuR3A\":[\"A 12 m yacht length overall is about 39.4 feet for marina berth booking in the US. A 3 m sofa wall needs roughly 9.8 feet of clear space—buyers often round up to 10 feet when shopping.\"],\"EqUGWT\":[\"因為每一步都是十的因數，心算很簡單：2.4 km 是 2 400 m； 75 公分是 0.75 m。電子表格和 CAD 工具可以乾淨地處理公制，國際標準（ISO、IEC、大多數科學期刊）期望使用 SI 單位或明確定義的公制導數。\"],\"Eqve2s\":[\"Sports science may log m/s. Multiply by 3.6 for km/h, then convert to pace with 60 / (km/h). Example: 3.33 m/s ≈ 12 km/h ≈ 5:00 min/km.\"],\"EtsosN\":[\"首先轉換列印的配方溫度，然後應用風扇調節。不要混合步驟，否則您將重複更正。\"],\"EuXeB_\":[\"不。它是距離的度量：光在一年內傳播多遠。時間比喻有助於直覺，但單位本身就是長度。\"],\"EwoQqu\":[\"Use our kilogram ↔ pound tools for the mass side and cubic metre ↔ litre tools when you reason about cube. Then apply the carrier formula—converters handle units; tariffs handle money.\"],\"EwtKsD\":[\"Units Converters 上的所有內容、品牌、佈局和軟體（不包括第三方資料）均為 Voyager Tecnologias LTDA 或其授權人所有，並受適用的智慧財產權法保護。您可以將本網站用於個人、非商業轉換目的。未經事先書面許可，您不得複製、抄襲、重新發布或商業利用我們的內容或技術。\"],\"ExTSN0\":[\"否。對於更改，請跳過偏移量。 Δ°F = Δ°C × 9/5，ΔK = Δ°C。將 +32 或 +273.15 應用於差異是不正確的。\"],\"EzSMrQ\":[\"公引\"],\"F0-dhG\":[\"44 ft/s is 30 mph—a common residential speed comparison. A fall speed of 100 ft/s is about 68 mph before drag limits.\"],\"F1yJs-\":[\"Spreadsheets aggravate this: formatting a cell as time versus number changes what “1.5” means. When exchanging files, store an explicit unit column (“hours decimal” or “seconds”) instead of relying on cell format alone.\"],\"F4Jah4\":[\"為什麼美式和英國加侖不同？\"],\"F6likP\":[\"華氏 (Daniel Gabriel Fahrenheit) 在 18 世紀初生產了可靠的水銀溫度計，並以方便的數字表示熟悉的天氣和體溫。水在攝氏 32 度結冰，在攝氏 212 度沸騰，這兩個點之間有 180 個分區。這些數字既是科學選擇，也是工程選擇。\"],\"F6pmwv\":[\"Splits on odd distances (5K, 10K, half) are easier in the distance unit printed on the bib. Convert published pace after you fix the distance language.\"],\"F7GQy7\":[\"千分尺\"],\"F8XkNg\":[\"Why can’t I convert cups of flour with water’s density?\"],\"F8v0B_\":[\"您始終乘以等於一的比率。數字因子看起來像乘法還是除法取決於您編寫比率的方式。如果您要消除的單位位於測量的分母中，請將其放入因子的分子中，以便將其消除。\"],\"F9Ur1v\":[\"A 1,200 sq ft bungalow is about 111.5 m² for a European energy certificate. A 200 sq ft deck needs about 18.6 m² of board coverage before waste.\"],\"FAO7bP\":[\"Convert \",[\"0\"],\" and more.\"],\"FCcyCC\":[\"A 75 m² flat is about 807 sq ft—typical one-bedroom sizing talk in US cities. Ordering vinyl for 20 m² means roughly 215 sq ft; add waste percentage after converting.\"],\"FER9kS\":[\"No. Cubic metres measure volume. Shipping cost uses actual mass and a dimensional-weight formula. Volume helps you compute dimensional weight but is not the invoice by itself.\"],\"FFQFcV\":[\"開啟針對這兩個單元客製化的公式、參考表、工作範例和簡短常見問題的轉換對。\"],\"FJHV07\":[\"A 50 cm² adhesive patch is about 7.75 in²—compare to US first-aid box labels. A business card near 46 cm² is roughly 7.1 in².\"],\"FJsRhQ\":[\"透過乘以 10⁻⁹ 將 nm → m 轉換。透過除以 1 000 將 nm → µm 轉換。在實驗筆記本中明確保留 10 的冪。每次轉換後進行單行尺寸檢查，可以在大多數轉錄錯誤進入紙本草稿之前發現它們。\"],\"FMo4Be\":[\"A 1,000 km² national park is about 386 sq mi. A wildfire mapped at 50 km² covers roughly 19.3 sq mi for US incident reports.\"],\"FNRfvh\":[\"回首頁\"],\"FOKanD\":[\"根據定義，開爾文和攝氏度具有相同的大小。刻度僅因零的位置而不同：開爾文從絕對零度開始；攝氏度偏移 273.15。\"],\"FQVDnS\":[\"“2 hours 15 minutes” is a duration. “14:15” is a clock reading. Converters that change seconds into hours answer duration questions. Time-zone shifts and DST change clock labels without changing how long a process took.\"],\"FV-M_m\":[\"對於許多顯示器來說，四捨五入後差異是不可見的。對於與財務相關的劑量、數控刀具路徑、合法土地面積或期望完全相等的自動測試斷言，這些殘差會成為真正的錯誤。\"],\"FXES9z\":[\"美國表格通常需要英尺和剩餘英寸（5 英尺 9 英寸），而不是小數英尺（5.75 英尺）。小數英尺在調查軟體中很好用，但在醫學問卷中卻讓人感到困惑。\"],\"F_Kw4m\":[\"A 3-minute plank hold is 180 seconds on a phone timer. Developing film for 7.5 minutes means 450 seconds on a metronome-style process clock.\"],\"Fh0gaF\":[\"Waste factors of 5–15% are common; patterned carpet can need more for matching. Apply waste after you trust net area. Converting units does not replace waste judgment.\"],\"FiEaL3\":[\"我們可能會顯示第三方提供的廣告，包括 Google AdSense。這些合作夥伴可能會使用 cookie 或類似技術來顯示相關廣告，但須遵守您的同意選擇和我們的隱私權政策。我們不控制第三方廣告的內容，也不對其行為負責。\"],\"FkodHJ\":[\"微米和微米一樣嗎\"],\"Fm5IVm\":[\"一兆公尺 (Mm) 等於一百萬公尺（1,000 公里）。它對於行星尺度的距離很有用。\"],\"Ft4_7k\":[\"喜歡以平方米為基礎進行換算。英畝 → 平方米 → 公頃是透明且易於審計的。僅最後捨入到法律或農藝背景所需的精度。標題報告和 GIS 圖層應在檔案名稱或圖層元資料中命名單位，以便下載保持明確。\"],\"FtpbJk\":[\"Dividing by 28 or 30 casually for sales copy is fine; for chargeable shipping volume use the precise factor. Do not convert litres of fuel directly to engine displacement in cubic inches without the right chain. Chest freezer “litres” are usually internal volume, same idea as ft³ capacity.\"],\"FtrmVo\":[\"導航、跑步和騎自行車以公里或英里為單位，具體取決於國家。配速（分鐘/公里與分鐘/英里）是一種相互轉換，人們在比賽壓力下會犯錯——在比賽開始前進行轉換，而不是在間歇期中進行轉換。\"],\"FuV6GZ\":[\"是的，距離和速度共享相同的長度單位（公里/小時和英里/小時）。仔細轉換；在高速公路上，小錯誤很重要。\"],\"FvnUXm\":[\"When a US telehealth portal rejects a weight, check whether it expects lb and you typed kg (or the reverse). Unit mismatch looks like physiologically impossible input.\"],\"FwOFRr\":[\"行之有效的產業模式\"],\"FxCqni\":[\"華氏度\"],\"G-NV0Y\":[\"Carpet and flooring are sold by area—square metres or square feet—not by a single length. The reliable workflow is: measure length and width in one unit → multiply for area → convert area if the seller uses another unit → add waste → round up to pack coverage.\"],\"G6yWBM\":[\"地板報價需要面積（平方公尺或平方英尺），而不是單一長度。如果您將房間長度從米轉換為英尺，但在相乘之前忘記以相同的方式轉換寬度，則面積將因長度比例因子（而不是其平方）而出現錯誤，並且對於材料訂單而言仍然是災難性的。\"],\"GBcBVU\":[\"公制單位是如何組織的\"],\"GI4ARo\":[\"一平方分米 (dm²) 等於 0.01 平方公尺。它位於公制面積階梯中的厘米和米平方之間。\"],\"GMvNL5\":[\"For ordinary duration conversions between day, hour, minute, and second as defined here, yes—1 day = 24 hours. Calendar date arithmetic and leap seconds are separate problems.\"],\"GN2514\":[\"Using 1.6 as a permanent factor is fine for rough estimates but drifts on long routes; prefer 1.609344 for odometer math. Do not confuse nautical miles (1.852 km) with statute/international miles. Speed limits in km/h are not the same numbers as mph after conversion.\"],\"GN8M4d\":[\"A Julian year equals exactly 365.25 mean solar days (31,557,600 seconds). Astronomy uses the Julian year as a fixed long-duration time unit.\"],\"GO6Qpp\":[\"一立方微米 (μm3) 等於 10⁻18 立方公尺。細胞生物學和微粒研究通常以這種方式報告體積。\"],\"GSr0rF\":[\"開啟選單\"],\"GYEDYg\":[\"土地面積換算一目了然：英畝、公頃、平方公尺和平方公里——以及測量歷史中的確切因素和陷阱。\"],\"Ge7-Dm\":[\"A laptop listed as 35.6 cm wide is 14 inches (35.6 ÷ 2.54). A European jeans waist of 81 cm is about 31.9 inches—close enough to pick a US size 32, then confirm the brand’s size chart.\"],\"Gfkeis\":[\"Using 30 L per ft³ is a rough estimate (~6% high). Shipping “dimensional weight” in ft³ is not the same as liquid litres of capacity—confirm whether the spec is internal volume. Natural gas ccf is hundred cubic feet of gas, not liquid litres.\"],\"Ggv1Zo\":[\"常見問題：\",[\"tFrom\"],\"至\",[\"tTo\"]],\"GiEH4u\":[\"How many grams are in an ounce?\"],\"GiSGSO\":[\"在日常長度中，厘米經常出現，但科學家在技術繪圖中通常更喜歡使用毫米或米。使用符合當地慣例並保持數字可讀的前綴。\"],\"Gid6Sb\":[\"切勿在未平方的情況下對面積使用線性英里到公里係數。面積換算與長度換算不同。 10% 的長度係數誤差在平方後變成大約 21% 的面積誤差——大到足以在租賃談判中產生影響。\"],\"Gkj2vG\":[\"Third-party ads and links\"],\"GnRuu0\":[\"Some consoles let you display pace. Confirm whether that pace is per mile or per kilometre. A 6:00 pace sounds easy per mile and brutal per kilometre.\"],\"GoyGZ5\":[\"公分\"],\"Gp92Y2\":[\"肘節是一種基於前臂的古代長度單位，此處標準化為 0.4572 公尺。它出現在歷史建築和聖經學術中。\"],\"GpEDw7\":[\"光學顯微鏡分辨率的討論模糊了微米和奈米尺度，取決於技術。將單位與儀器有意義的精度相匹配。將儀器的 12.345 µm 報告為 0.2 µm，在從毫米轉換後會產生錯誤的置信度。\"],\"GpGrm4\":[\"A 2,500 L bright tank is 25 hL on a production schedule. Milk intake of 12,000 L in a morning is 120 hL for a co-op report.\"],\"GqMz0I\":[\"定義比例的固定點\"],\"GrBwfT\":[\"該網站基於 TanStack Start 和 React 19 構建，針對您鍵入時的即時加載和即時結果進行了最佳化。\"],\"GsWptO\":[\"從英尺和英寸轉換為公制時，先將整個高度轉換為英寸，然後轉換為厘米，最後四捨五入一次。分別對每個步驟進行四捨五入可能會產生您未測量的公分。\"],\"GtE1iJ\":[\"Converting metric and US training plans\"],\"GuJItQ\":[\"Using 30 g per ounce is a rough kitchen shortcut (~6% high). Fluid ounces measure volume, not weight—do not convert fl oz with this mass pair. Troy ounces for silver and gold differ from avoirdupois ounces.\"],\"GzLnft\":[\"A Gregorian mean year is 365.2425 days—close but not identical to 365.25. Calendar age in birthdays is not Julian-year duration. Leap-second tables affect civil time, not the Julian-year day count definition used here.\"],\"H34q0n\":[\"烘焙配方對液體比例很敏感。將 250 mL 公制杯更換為 240 mL 美製杯編寫的配方，可悄悄添加液體。蛋糕和麵包可能仍然有效；馬卡龍和層壓麵團可能不會原諒它。專業廚房透過稱重幾乎所有東西來避免歧義。\"],\"H44uN7\":[\"一平方英里約等於 2.59 平方公里。美國和英國的地理統計數據通常以平方英里表示大面積。\"],\"H7OUPr\":[\"Day\"],\"H87kj4\":[\"面積不是長度\"],\"HAYZTF\":[\"Trip computers may let you switch L/100 km ↔ mpg. After switching, reset averages; old samples mixed under another unit display still confuse humans even if the computer converted correctly.\"],\"HCBVZC\":[\"四捨五入、有效數字和顯示\"],\"HEqFN-\":[\"A cup of flour can vary by tens of grams depending on scooping and humidity. A 120 g portion does not. Grams and ounces measure mass; cups measure volume. When a recipe lists weight, trust the scale and convert units—do not re-approximate with cups unless you accept variability.\"],\"HFxio6\":[\"Planetary fact sheets may list periods in days or in years—check the footnote. If a year is undefined, ask whether they mean 365.25 d, 365.2425 d, or Earth’s actual orbital period (which differs slightly from both).\"],\"HHeAbn\":[\"A 200 L chest freezer is about 7.06 ft³ on US retail tags. A 1000 L IBC tote is roughly 35.3 ft³ for warehouse slot planning.\"],\"HHu18M\":[\"使用配方作者假定的杯子標準，或將配方轉換為毫升和克。公制杯 (250 mL) 和美製杯 (~240 mL) 不可互換用於精密烘焙。\"],\"HII3iR\":[\"A 5,000 m training interval is a 5 km workout. A 42,195 m race distance is the marathon’s 42.195 km official length.\"],\"HMCYfQ\":[\"一皮米 (pm) 等於 10⁻12 公尺。它通常用於化學中的原子半徑和鍵長。\"],\"HRyxe7\":[\"堆場（國際）\"],\"HSp70r\":[\"如果兩種單位選擇具有同等的可讀性，請選擇一種能夠最大限度地減少方程式或機器轉換步驟的單位。更少的轉換意味著更少的機會反轉因子或忘記平方面積比例。\"],\"HTgMtz\":[\"應力、壓力、密度和流量組合單位。將每個基本尺寸轉換為因數的正確冪。壓力轉換誤差通常始於線性使用的長度或面積係數。\"],\"HaSyAZ\":[\"是的。 Units Converters 可供學生、專業人士及日常任務免費使用。結果僅供參考。\"],\"High-precision unit conversion for students and professionals. Convert hundreds of units instantly.\":[\"High-precision unit conversion for students and professionals. Convert hundreds of units instantly.\"],\"HjRGcU\":[\"Where time zones actually matter\"],\"HshOlm\":[\"Tide atlases and racing handicaps assume nautical miles and knots. Converting a race course to statute miles without converting the rating math breaks comparisons between seasons and fleets.\"],\"HzdxZ3\":[\"為什麼要使用我們的 \",[\"quantity\"],\" 轉換器？\"],\"I2PMyS\":[\"攝氏溫度在冬季氣候中很常見。負開爾文對於普通熱力學溫度來說沒有物理意義。如果轉換器從有效輸入路徑產生負開爾文，則公式的實作是錯誤的。\"],\"I4MWpI\":[\"If your scale shows kg but your coach talks stone, keep training logs in kilograms and convert only for the coach’s summary. One source of truth beats dual editing every session.\"],\"I5tDdr\":[\"Pound (Avoirdupois)\"],\"I7lEIb\":[\"Packaged food in metric markets lists net weight in grams or kilograms; US labels use ounces and pounds. A 500 g block of cheese is about 1.10 lb; a 1 lb package is about 454 g. For recipes, prefer grams on a digital scale—volume cups vary by packing, but mass does not.\"],\"I9AUvo\":[\"為什麼要使用我們的 \",[\"tQuantity\"],\" 轉換器？\"],\"IAabNJ\":[\"我們對精準度的承諾\"],\"IB9sOh\":[\"一尋等於 1.8288 公尺（6 英尺）。水手們傳統上用它來表示水深。\"],\"ID54oN\":[\"細菌大小、人體細胞直徑和微加工通道通常以微米為單位。 7-8 µm 大小的紅血球是經典的教學範例。植物細胞和許多原生動物的體積可以達到數十或數百微米，這就是為什麼生物學講座在句子中間跳躍前綴的原因。\"],\"IDLKQN\":[\"為什麼 1 平方公里等於 1 000 000 平方公尺？\"],\"IGLs5H\":[\"When do I add waste factor?\"],\"IHKGd9\":[\"37 km/h wind is 20 knots—common small-craft advisory territory depending on local rules. A ferry at 40 km/h is about 21.6 kn.\"],\"II2IKg\":[\"Convert Fahrenheit to Kelvin when US process specs (°F) feed equations that need absolute temperature—ideal gas work, thermal noise, or materials science. Convert °F→°C first, then add 273.15, or use K = (°F + 459.67) × 5/9.\"],\"IIEWyi\":[\"48 hours of ferment time is 2 days on a kitchen calendar. A 168-hour work stretch is 7 days—one full week of continuous hours.\"],\"IIV9CL\":[\"Treating linear metres of skirting like square metres of carpet. Treating roll width as area. Forgetting hallways. Using interior paint-area estimates (which subtract windows) for flooring (which usually should not).\"],\"IMhaKg\":[\"A week is exactly 7 days in these converters. Months and calendar years are not fixed-length in the same way—use dedicated month/year units when that is what you mean, not 30 × day guesses baked into hour math.\"],\"INLttC\":[\"A grain equals exactly 0.00006479891 kilograms. Historically based on a grain of cereal, it still appears in ammunition, archery, and precious-metal weighing.\"],\"IOHLeD\":[\"Pool chemicals and fertilizers often dose by mass per volume of water. Convert the pool volume to litres, convert product mass to grams, then apply the label—not the other way around.\"],\"IOXbAM\":[\"DIY 層架、3D 列印和相框都受益於毫米，因為公差很嚴格，而且公分的小數很容易出錯。對於許多製造商來說，19 毫米的架子銷孔比 1.9 公分的銷孔更清晰。\"],\"IOmGBB\":[\"How do I convert min/km to min/mile?\"],\"ISY-Yi\":[\"Convert between running pace (minutes per kilometre) and speed in km/h or mph, set treadmills correctly, and compare race paces across metric and US displays.\"],\"IUm2Di\":[\"9 metric teaspoons of cocoa is 3 metric tablespoons for a brownie batch. A ½ tsp salt pinch is 1/6 tablespoon—usually left as teaspoons for readability.\"],\"IVvE-e\":[\"µ 和 m 有什麼差別？\"],\"IZeM_y\":[\"Convert acres to hectares for farmland, conservation land, and solar-farm footprints when US acreage must match metric agricultural stats. One hectare is 10,000 m²; one acre is 4,046.8564224 m², so 1 acre ≈ 0.404686 ha.\"],\"IeyIcS\":[\"單位選擇無法修復不良的測量結果。它只能清楚地呈現測量結果。轉換後如實說明不確定性和重要數字。將不確定的值轉換為華而不實的微小單位並不會使測量更加精確。\"],\"IiYyf2\":[\"Using 8-hour “workdays” by accident when the context was continuous hours. 36 hours is 1.5 days, not 1 day 36 hours written carelessly. Keep UTC hour counts aligned if the day boundary matters legally.\"],\"IjdnEx\":[\"Practical conversion habits\"],\"IjrTUc\":[\"好的工程是將數字表示與您將用數字做出的決定相匹配。製造、醫學和法定計量的單位轉換需要小數或理性數學；天氣小部件不會轉換城市溫度。如有疑問，請選擇更嚴格的表示法 - 小數的性能成本通常小於靜默往返錯誤的成本。\"],\"Ijyjkr\":[\"確定食譜的規模。轉換為您烤箱的規模。如果需要，調整風扇。充分預熱。用您將使用的架子上的烤箱溫度計進行確認。\"],\"Ik5E9h\":[\"清晰瀏覽 SI 前綴（毫、厘、千、兆、納等），以便您可以縮放長度、面積和體積，而不會忘記 10 的冪。\"],\"IkJbH4\":[\"An average month equals 30.436875 days (one-twelfth of a Julian year). It approximates the mean Gregorian calendar month for long-term conversions.\"],\"InyonT\":[\"為工作選擇合適的單位\"],\"IoAuJG\":[\"正在發送...\"],\"Is9UbN\":[\"A ¼-20 tap drill often uses a 0.201″ hole, about 5.11 mm—handy when your metric drill set jumps in 0.1 mm steps. Plywood sold as ¾ inch is 19.05 mm; European 18 mm sheet is close but not identical for tight dados.\"],\"IuLd0Z\":[\"Pace is an inverse speed\"],\"Iw0UOq\":[\"Which year does a light-year use?\"],\"IzEkB5\":[\"No. One knot is about 1.15 statute miles per hour. Knots pair with nautical miles; mph pairs with statute (land) miles.\"],\"J1IXTw\":[\"Rounding to “1.5 km per mile” understates distance by about 7%. Mixing nautical miles into car navigation produces large errors. Pace (min/mile vs min/km) must be converted separately from pure distance—do not reuse the same shortcut without adjusting time.\"],\"J5LfsL\":[\"Free online unit converter for Length, Temperature, Area, and Volume. Get instant, high-precision results for metric and imperial units.\"],\"J5icM8\":[\"One US cup of water is 240 mL; two cups of broth in a soup is 480 mL. A metric cake that wants 250 mL milk is essentially one metric cup, not a level US cup.\"],\"J6ptGt\":[\"科學檔案中的溫度資料應使用什麼單位？\"],\"JEmvHO\":[\"Airlines often market 23 kg as “50 lb,” but 23 kg is about 50.71 lb. Pack below the kilogram limit after converting with an exact factor, and leave a buffer for scale differences.\"],\"JH5zFD\":[\"當受眾和標準發生衝突時，同時發布：主要單位用於合規性，次要單位用於本地清晰度，並附有明確的轉換說明。雙重標籤勝過沉默的假設。使主要單位在視覺上占主導地位，以便讀者知道如果舍入不同，哪個值獲勝。\"],\"JHXQdU\":[\"在估算排水費的滲透表面時，請務必保持 m² 或 ft² 單位；切換中間電子表格是許可證數字出錯的原因。\"],\"JJc0Lk\":[\"Digital kitchen scales often toggle between g and oz (and sometimes lb:oz). Learn your scale’s tare button and unit button before you cream butter. Switching units mid-recipe without zeroing is a common way to double salt.\"],\"JKSPe7\":[\"如果攝氏是國際標準，為什麼我們仍然使用華氏？\"],\"JQqy6Y\":[\"與來自另一個國家或行業的同事一起審查一個樣本輸出。如果他們讀錯了，你的單位選擇就會失敗——即使數學是完美的。在第一批貨物未通過進貨檢驗之前，對設備的可用性測試聽起來有些過分。\"],\"JRDMxI\":[\"一立方英尺約等於 28.3 公升。暖通空調、航運和美國建築通常以立方英尺為單位測量體積。\"],\"JT7-iP\":[\"走另一條路會倍增。 0.003 m = 3 mm = 3 000 µm = 3 000 000 nm。在前綴單位旁邊寫上科學記數法可以捕捉滑動錯誤。在匯出剝離單元元資料的 CSV 檔案時，雙重寫入特別有用。\"],\"JTggU3\":[\"Updating one dimension after furniture plans change but forgetting to recompute area and reconvert. Build the habit: any geometry change triggers a full pass through the workflow.\"],\"J_hVSQ\":[[\"0\"]],\"JaIZlG\":[\"常見的轉換錯誤\"],\"JaOjwB\":[\"1.2 kg of sugar for syrup is 1,200 g on a recipe card. A 0.025 kg spice purchase is 25 g—typical jar size.\"],\"Jequ1n\":[\"Response time:\"],\"JgyaEz\":[\"對於風扇烤箱我需要不同的轉換嗎？\"],\"Jjp531\":[\"當您的儀器、圖紙或當地標準已經使用該單位時，請使用 \",[\"tFrom\"],\"。當您的協作者、法規或工具期望 \",[\"tQuantity\"],\" 的約定時，首選\",[\"tTo\"],\"。在清晰的邊界處進行轉換並標記每個數字。\"],\"Jq91sW\":[\"Exactly 365.25 days, defined as 31,557,600 seconds. That fixed length is why astronomy prefers it for duration math.\"],\"JrAEfM\":[\"Duration conversions that stay honest\"],\"JrHqjD\":[\"One relationship, three roles\"],\"JsRaBA\":[\"房地產清單隨意將面積與建築面積進行比較，但沒有明確說明，這將土地足跡與居住空間混淆了。閱讀調查定義。\"],\"K07l5q\":[\"Dividing by 1.6 (statute thinking) yields the wrong knot value. Gusts in km/h converted without noting “gust” vs sustained mislead seamanship decisions. GPS km/h over ground is not the same as speed through water in knots.\"],\"K26O7q\":[\"我們和我們的合作夥伴使用 cookie 來分析網站流量、個人化內容並提供相關廣告（例如Google AdSense）。點擊“接受全部”，即表示您同意我們使用 cookie，詳情請參閱我們的<0>隱私權政策</0>。您可以拒絕非必要的 cookie 並且仍然使用轉換器。\"],\"K2b08X\":[\"使用公里來表示米可以產生數千個單位的距離——通常是旅行、跑步路線和地理尺度。為建築物、房間和短的室外路段保留儀表。\"],\"K4_ggM\":[\"Convert inches to millimetres when a US fractional drill size, sheet-metal gauge note, or 3D-print dimension must land on a metric CNC program or European fastener chart. Machinists and makers do this whenever CAM software expects mm. Multiply inches by 25.4 for an exact millimetre value.\"],\"K5MpCS\":[\"基本儲存可確保您的語言和同意選擇發揮作用。只有當您點擊我們 Cookie 橫幅上的「全部接受」後，用於分析和廣告的非必要 Cookie 才會載入。您可以隨時透過頁腳中的「Cookie 設定」改變主意。\"],\"K6Vh90\":[\"關於 Units Converters\"],\"K7f7Ew\":[\"Same mass, different everyday labels\"],\"KDdKFc\":[\"雙精度 (float64) 足以滿足顯示舍入後的許多日常轉換，但當您需要位元穩定的往返、法定計量或嚴格的自動化測試時，它並不能取代精確的小數因數。對於權威轉換器，喜歡小數或有理數。\"],\"KDw4GX\":[\"再試一次\"],\"KEEL4-\":[\"為這次旅行選擇一個計劃單位。將所有腿轉換為該單位。增加緩衝，少走彎路。然後，如果需要，才將摘要轉換為當地路標單位。\"],\"KEiMvb\":[\"先匹配數量，然後匹配單位\"],\"KGZLJU\":[\"步長和步行距離估計值通常混合米和分鐘。計步器和手機可能會報告公里數，而您的心智圖則以街區或英里為單位。在已知路徑上校準一次。\"],\"KI6QJZ\":[\"乾燥與液體測量\"],\"KIjlk9\":[\"Use km/h ↔ mph converters for the speed side and kilometre ↔ mile for distance; apply the 60/pace bridge for the reciprocal relationship.\"],\"KJCno7\":[\"立方公里\"],\"KKMdB4\":[\"最後更新日期：2026 年 7 月 13 日\"],\"KNOYmB\":[\"Seconds, Minutes, and Hours: Precision That Matters\"],\"KU3oCa\":[\"Calibration and belt wear affect true speed slightly. Unit conversion assumes the console’s number is correct; performance testing may need an external check.\"],\"KUJ7qS\":[\"秒差距（視差秒）約為 3.26 光年，在專業天文學中是首選，因為它與視差測量緊密相關。調查論文可能會報告宇宙距離的兆秒差距。\"],\"KY0PLM\":[\"Our kilogram ↔ pound converter pages include common luggage and body-weight tables so you can sanity-check a result in seconds before you argue with a check-in agent or a spreadsheet.\"],\"KYESmC\":[\"人們如何實際使用毫米、厘米、米、公里、英寸、英尺和英里，以及如何為家庭、旅行和 DIY 選擇合適的單位。\"],\"KYgd7M\":[\"一光年測量距離\"],\"KYs_tX\":[\"Convert square kilometres to square miles for country size, wildfire perimeters, and city area comparisons in international news. Geographers and emergency management briefings use both. One square mile is 2.589988110336 km².\"],\"KZsVok\":[\"Ignoring local daylight-saving transitions when you need wall-clock hours across a spring-forward night (23-hour civil day). Sidereal days differ slightly from solar days—irrelevant for parcel delivery, relevant for astronomy. “Business days” are not 24-hour multiples.\"],\"KdKXh4\":[\"1 ngström 等於 0.1 奈米（100 皮米）。將 ångströms 乘以 0.1 即可得到奈米。\"],\"Kfx-3R\":[\"A metric carat equals exactly 0.0002 kilograms (200 milligrams). Jewellers use carats to express the mass of gemstones such as diamonds.\"],\"Kh9Y3o\":[\"Centimetre per second\"],\"Ki1FlF\":[\"A 40-acre parcel is about 16.2 hectares—common quarter-quarter section talk in metric reports. A 5-acre hobby farm is roughly 2.02 ha for EU subsidy forms.\"],\"KnLaXP\":[\"立方奈米\"],\"KnvYE8\":[\"立方百米\"],\"KoOxS5\":[\"如果您接受 cookie，我們可能會使用 PostHog (posthog.com) 來了解人們如何使用 Units Converters，例如哪些頁面受歡迎、大致區域以及基本設備或瀏覽器資訊。 PostHog 代表我們處理這些數據，以便我們可以改進網站。當您拒絕 cookie 時，分析功能將會停用。了解更多<0>PostHog 的隱私權政策</0>。\"],\"Kopxec\":[\"立方十米\"],\"KrqAV3\":[\"為什麼網路商店拒絕我的身高？\"],\"KsOw0Z\":[\"SI 總是正確的選擇嗎？\"],\"KxbM14\":[\"Convert days to weeks for long training blocks, visa stays, and content calendars when a day count must become week language. Divide days by 7. Athletes periodizing plans and PMs phasing releases use this.\"],\"KyK9gJ\":[\"體積涵蓋容量和三維空間——廚房中的升、建築中的立方米以及精細的科學單位。當食譜混合杯子和毫升時請小心轉換。\"],\"L-VeS4\":[\"Metre per second\"],\"L7Ysq_\":[\"Learn why astronomy uses a Julian year of 365.25 days, how that differs from Gregorian calendar years, and when to convert days and years with each definition.\"],\"L8cWHH\":[\"Mach is a ratio to local speed of sound, not a fixed SI-style speed unit like knots or km/h. This converter set focuses on absolute speed units; use performance charts for Mach.\"],\"LAw-mP\":[\"在便利貼上寫下 °C 和 °F，以供您重複使用的家庭食譜。雙標籤可防止週末爭吵和燒焦托盤。\"],\"LBKpMd\":[\"下面您將找到常見 <0>\",[\"tFrom\"],\"</0> 到 <1>\",[\"tTo\"],\"</1> 值的快速參考表，以及任何可用的公式，因此您可以一目了然地比較結果，而無需重新輸入每個金額。\"],\"LDQTXo\":[\"關於Units Converters|我們的使命與技術\"],\"LIMr6t\":[\"通常是由於中間舍入、歷史上不同的腳定義或浮點顯示模式。就確切因素、單一轉換路徑和共享舍入政策達成協議。\"],\"LKhkZX\":[\"任何轉換之前的第一個問題是：我要測量什麼物理量？然後才選擇單位。數量錯誤使單位錯誤相形見絀。\"],\"LMqmDO\":[\"Understand L/100 km vs mpg thinking through speed, distance, and volume—convert trip length and pace correctly before you compare car efficiency figures.\"],\"LN3JSA\":[\"公制與美製產品表\"],\"LNBguy\":[\"If the question is “how long,” use second/minute/hour/day converters. If the question is “what time is it there,” use zone conversion. If the question is both—“how long until 09:00 in another city”—convert the target instant, then subtract from now as a duration.\"],\"LPJ1TE\":[\"US retailers quote ft²; many international and commercial specs use m². Keep a project sheet with both columns. Convert the net area, then apply waste in your working unit, then convert again only if packaging demands it.\"],\"LSLt5W\":[\"牛頓溫標 (°N) 由艾薩克牛頓設計。它將水的冰點定為 0 °N，沸點定為 33 °N。\"],\"LSorPc\":[\"保持前導數字可讀\"],\"LWnof8\":[\"為什麼加工商列出單杯單位？\"],\"LYljkI\":[\"Treadmill buttons and silent unit switches\"],\"LZPLTP\":[\"21 days of meal prep is 3 weeks. A 10-day antibiotic leftover discussion is about 1.43 weeks—usually left in days for clarity.\"],\"LaTAoV\":[\"皮米\"],\"LcET2C\":[\"隱私權政策\"],\"Ldr5MD\":[\"Mistakes that empty the truck\"],\"LhMjLm\":[\"Time\"],\"LhRT5N\":[\"在美國較早的書籍中，糖果階段和肉類熟度經常以華氏度引用，而在其他地方則以攝氏度引用。以與轉換烤箱設定點相同的方式轉換目標探頭溫度，然後使用校準溫度計進行驗證。\"],\"Lj2TEf\":[\"Dividing by 1,000 (thinking like metres→kilometres) makes the plot 10× too large in hectares. A hectare is 100 m × 100 m, not 1,000 m × 1,000 m. Keep building footprint m² separate from whole-parcel hectares in reports.\"],\"Lkvtx4\":[\"風扇（對流）與傳統風扇\"],\"LwL41_\":[\"Subtracting 32 after scaling instead of before reverses the formula. Body-temperature shortcuts (“subtract 30, halve”) are rough; 98.6 °F is 37 °C exactly in the usual teaching pair, but real readings vary. Freezing is 32 °F, not 0 °F—do not map 0 °F to 0 °C.\"],\"LwP5Y5\":[\"攝氏、華氏和開爾文解釋\"],\"M168bP\":[\"立方分米\"],\"M4KE2C\":[\"覆蓋物和表土以體積（立方米或公升）出售，但以選定的深度分佈在面積（平方米）上。體積=面積×深度，長度單位一致。將幾英尺的深度與平方米的床混合在一起是一種維度的混搭。\"],\"M76E5N\":[\"平方英尺\"],\"MDjDOw\":[\"Forgetting three zeros turns a 5,000 m run into “5 m.” Elevation gain in metres is not the same as horizontal distance in kilometres—do not divide elevation by 1,000 and call it a trail length. Keep scientific notation (1.5e4 m) straight when pasting from spreadsheets.\"],\"MG3-ZM\":[\"一立方米等於 1,000 公升。這個 SI 關係是精確的，是度量池數學最簡潔的橋樑。\"],\"MGeKne\":[\"Use centimetres to feet for body height, fabric length, and small room clearances written in cm on clothing or furniture sites but discussed in feet. Parents tracking child height and interior designers switching between EU and US catalogs use this. There are 30.48 cm in one international foot.\"],\"MHl0mQ\":[\"攝氏度和開爾文的大小相同。這就是為什麼將攝氏度轉換為開爾文是加法：T(K) = t(°C) + 273.15。華氏度更小：一華氏度是攝氏度的 5/9。\"],\"MJ55BJ\":[\"一公頃 (ha) 等於 10,000 平方公尺（100 英畝）。全球農業和土地管理報告的田地面積以公頃為單位。\"],\"MPmdf0\":[\"湯匙（公制）\"],\"MQXnn-\":[\"滴\"],\"MUQdT7\":[\"使用面積轉換器（或乘以精確的平方公尺到平方英尺係數）。不要將米轉換為英尺，也不要忘記對比例進行平方。\"],\"MXhvVh\":[\"十公升\"],\"MYhaIK\":[\"為了簡單起見，許多工具都會選擇一個通用的定義—通常是美製杯或公制杯。當您需要明確的結果時，請閱讀該工具的文檔並首選基於升的測量值。\"],\"MbaNs0\":[\"Convert light-years to kilometres when popular science distances (nearby stars, galaxy separations) must become a terrestrial kilometre scale for comparison or calculation. Planetarium scripts and astronomy outreach use this pair. One Julian light-year is about 9.4607×10¹² km.\"],\"MbfgGR\":[\"Prefer whole grams for home baking. Tenths of a gram help for yeast or salt in small loaves if your scale resolves them. Converting 0.25 oz of yeast to grams (about 7.1 g) is clearer than leaving fractional ounces on a sticky note.\"],\"Mk46TY\":[\"Water boiling at 100 °C is 373.15 K in steam-table lookups. A lab bath at −40 °C is 233.15 K—below the freezing point of mercury, relevant for some thermometer discussions.\"],\"MkR0Sw\":[\"回顧時間和我們所看到的\"],\"MlE27Y\":[\"Gym plates in metric gyms are often 1.25, 2.5, 5, 10, 15, and 20 kg. US customary gyms use 2.5, 5, 10, 25, 35, and 45 lb plates. A “20 kg plate” is about 44.1 lb—not a 45 lb plate. When following a program written in the other system, convert working weights, then choose the nearest plate combination and log what you actually lifted.\"],\"Mpzx-l\":[\"Convert square inches to square centimetres for packaging labels, gasket cross-sections, and sheet sticker sizes when US print specs meet metric manufacturing. Multiply in² by 6.4516 exactly (since 1 in = 2.54 cm).\"],\"My0Q3W\":[\"A 1.5 L soft drink is 1,500 mL for calorie apps that expect millilitres. Mixing 0.25 L of stock means 250 mL on a kitchen measuring jug.\"],\"N5JSCo\":[\"Exactly 1.852 km/h, because the international nautical mile is exactly 1,852 metres and a knot is one nautical mile per hour.\"],\"N7wd8d\":[\"對於食品儲藏室的主食來說，重量勝過任何品脫的定義。一品脫藍莓和一品脫米飯是市場慣例，而不是實驗室數量。\"],\"NC2AI2\":[\"長度\"],\"NCSre5\":[\"Questions about the product, accuracy reports, or partnerships can be sent through our Contact page. We aim to reply within two business days.\"],\"NIu6uZ\":[\"Convert metres per second to kilometres per hour for weather winds, physics problems, and athletics when SI base speed must become everyday road units. Multiply m/s by 3.6 exactly. Meteorology and school labs share this pair.\"],\"NL39Lv\":[\"Orbital periods, pulsar timing educational examples, and stellar age order-of-magnitude charts often prefer a fixed year so plots do not depend on calendar reform history. Simulation timesteps labeled in years usually mean this fixed unit unless stated otherwise.\"],\"NMPfUh\":[\"Is density a unit you can convert like kilometres?\"],\"NPlROR\":[\"保留小參考卡：US gal ≈ 3.785 L；英制加侖 ≈ 4.546 L；公制杯 = 250 mL；美國法定杯 = 240 毫升。這四個數字可以防止大多數廚房災難。\"],\"NPq2gb\":[[\"fromLabel\"],\" 至 \",[\"toLabel\"]],\"NSKeEf\":[\"Exactly 14 avoirdupois pounds. One stone is also exactly 6.35029318 kilograms via the international pound.\"],\"NZsHs1\":[\"<0>科學等級：⟦​​1⟧ 包括玻爾、Ångström和秒差距等稀有單位。\"],\"NgkOcN\":[\"本隱私權政策目前以英文提供。如有疑問，請聯絡 voyagertecnologias@gmail.com。\"],\"NjLlsq\":[\"Wind shear of the mental kind\"],\"NmFWqV\":[\"專為日常和科學用途設計\"],\"NnGSWC\":[\"Waste, pattern match, and roll width\"],\"Nngtz6\":[\"Convert km/h to m/s for drag equations, ballistic apps, and lab write-ups that need SI base units. Divide km/h by 3.6. Engineering fluid notes and school physics prefer m/s.\"],\"No-Vxm\":[\"人們混淆這些詞是因為日常語言很鬆散。我们说一个房间有 20 平方米，一个游泳池可以容纳 50,000 升，一块田地有 2 英亩，然后要求转换器在这些数字之间跳转，而不检查尺寸。\"],\"NoA-sZ\":[\"攝氏度和華氏度是日常間隔尺度：相同的度數測量溫差，但選擇它們的零點是為了方便人類。開爾文是絕對熱力學標度：零開爾文是絕對零，此時分子運動達到理論最小值。\"],\"Nq1fZ8\":[\"Sliding the decimal nine places the wrong way (×10⁹ instead of ×10⁻⁹) is the classic error. Do not confuse nm with µm (micrometres)—1,000 nm = 1 µm. Ångströms (0.1 nm) are yet another scale; convert Å→nm first if needed.\"],\"Nrg13g\":[\"方碼\"],\"Nu4oKW\":[\"描述\"],\"Nz6P6E\":[\"Convert into the unit the carrier’s rate card uses for chargeable weight, then compare actual and dimensional weight in that same unit.\"],\"O2S2Tn\":[\"If the text mentions light-years, astronomical constants, or SI-style durations, interpret “year” as Julian unless another convention is stated. If the text mentions birthdays, tax years, or history timelines, use calendar rules.\"],\"O4C-EF\":[\"英語國家重複使用品脫、誇脫和加侖等單字來表示液體計量單位，然後以不同的方式標準化它們。美國液體加侖為 231 立方英寸（即 3.785 411 784 公升）。一英制加侖為 4.546 09 L。這大約是 20% 的差異，大到足以破壞稀釋數學和飲料產量規劃。\"],\"O4_gQW\":[\"單位轉換指南 | Units Converters\"],\"OB2sQ-\":[\"烹飪體積換算：杯子、公升和湯匙\"],\"OCsIdb\":[\"轉換就是乘以一\"],\"OHrgxR\":[\"無論您是將身高換算為表格、將房間面積換算為地板、將烤箱溫度換算為配方，還是將池體積換算為化學品，Units Converters 都會為您提供清晰的結果以及上下文 — 單位描述、工作示例以及解釋數字背後系統的指南。\"],\"OJLklK\":[\"Is 12.5 stone the same as 12 st 5 lb?\"],\"OJaUnH\":[\"Metric tonnes appear on freight, not parcels. One metric tonne is 1,000 kg (about 2,204.62 lb). Do not confuse it with a US ton (short ton) or UK long ton when reading ocean quotes.\"],\"OMSKkw\":[\"建築師和室內設計師根據當地規格和軟體預設值選擇米或英尺。天花板高度接近 2.4 m（約 8 英尺）是常見的住宅標準。將海外家具尺寸導入本地平面圖時請小心轉換。\"],\"OOBbxV\":[\"引號可能包括浪費、模式匹配或不同的捨入。先比較同一單位的淨面積，然後再討論附加項目。\"],\"OOgS84\":[\"Hours, minutes, seconds, days, and weeks convert among themselves as pure spans: 1 h = 60 min = 3,600 s; 1 d = 24 h; 1 wk = 7 d. Those factors do not care whether you are in Tokyo or Toronto.\"],\"OPOKGZ\":[\"保留泳池資料卡\"],\"OTifQT\":[\"一英里等於多少公里？\"],\"OU1qS8\":[\"威廉·湯姆森（開爾文勳爵）提出了絕對熱力學溫度。開爾文從絕對零度開始，並使用與攝氏度相同的度數。氣體行為和統計力學方程式更喜歡絕對尺度，因為比率和絕對值表現得很乾淨，沒有任意偏移。\"],\"OUVAnT\":[\"Pace and speed link time to length (min/km, km/h). Convert the time portion with time units, convert the length portion with length units, then recombine. Changing only one side breaks the rate.\"],\"OXtWeT\":[\"智慧財產\"],\"OY86E0\":[\"Using 2.2 as if it were exact for legal or shipping work. It is a handy approximation, not the definition. Multiplying by 2.2 and also adding a “safety pound” without knowing which scale unit you started from compounds error.\"],\"OaYVBV\":[\"一光分鐘是光一分鐘傳播的距離，大約1800萬公里。日地光時間約八光分鐘。\"],\"ObatIZ\":[\"Contract law and finance use calendar or business-day conventions. Scientific converters do not replace those legal definitions.\"],\"Oc5anK\":[\"一旦您確定了杯子的定義，杯子中列出的庫存、葡萄酒和牛奶就會透過簡單的比例因子轉換為公升。減少會改變濃度，但不會改變換算數學：減少一半的 500 毫升仍然是關於剩餘內容的體積聲明。\"],\"Ocfc0k\":[\"公畝\"],\"OfxjPc\":[\"連貫系統為每個數量選擇一個基礎。對於長度，SI 使用米。英尺、英里、奈米和光年都可以表示為米的倍數。對於面積，相關SI單位是平方公尺；體積，立方公尺。公升很方便，但仍然透過立方米來定義。\"],\"Oi5xN4\":[\"Forgetting the leftover pounds after whole stone (11 st 4 lb ≠ 11.4 st in the casual sense people speak). Using 6 kg per stone is rough. Stone is not used for freight—do not put stone on a bill of lading.\"],\"OjzTFj\":[\"Set the instrument cluster and phone navigation to the local unit. Convert any handwritten pace notes from home. Recalculate ETA with distance and average speed in one system. Recheck the first three posted limits against your display.\"],\"OpPtVE\":[\"No. Convert lengths into one system first, or convert the finished area with an area converter. Mixed units in the product L × W are invalid.\"],\"OrotT6\":[\"Convert m/s to mph when SI sensor logs, drone telemetry, or physics results must be explained in US customary road units. Multiply m/s by about 2.23694. Research papers often leave speed in m/s until the public summary.\"],\"Otkaib\":[\"一塊木板（木板測量面積）大約等於 0.00774 平方米，即一英吋乘一英尺木板的表面積。木材業使用相關的委員會措施。\"],\"Ovv7QR\":[\"我們是誰\"],\"OwOFA9\":[\"佔地 2.5 英畝的業餘農場約為 1.01 公頃或約 10 117 平方米。 40公頃的果園面積為0.4平方公里，約98.8英畝。這些大概有助於閱讀國際清單。\"],\"P0Yqo4\":[\"Ground speed from GNSS is also often shown in knots in cockpit devices. A car-oriented app on a tablet may default to mph; switch units so your ETAs match sectional-chart thinking in nautical miles.\"],\"P2WxBN\":[\"粗略比較、遊戲、數據視覺化和許多科學模擬都可以容忍浮動誤差，因為模型的不確定性使表示誤差相形見絀。關鍵是了解你的耐受力。如果一毫米很重要，那麼浮標就需要紀律或更換。\"],\"P2tpOX\":[\"地點：\"],\"P6r3Wv\":[\"開爾文 (K) 是熱力學溫度的 SI 基本單位。絕對零度為 0 K；水的三相點定義為 273.16 K 附近。\"],\"PHCamF\":[\"How do I convert mph to km/h quickly?\"],\"PHahRE\":[\"溫度會偏移：攝氏度和華氏度是仿射標度，而不是純粹的比率。將 20 °C 轉換為華氏度並不是簡單地乘以 1.8；您必須應用正確的偏移量。長度、面積和體積轉換幾乎總是純比例因子——溫度是常見的例外。\"],\"PKNAUK\":[\"The conventional light-year uses the Julian year: the distance light travels in vacuum in 365.25 days of 86,400 seconds each.\"],\"PKojqY\":[\"劑量取決於體積\"],\"PKuW0V\":[\"Countries that use metric post body weight and baggage limits in kilograms. US gyms, some airlines’ US-facing pages, and older medical charts still speak in pounds. If you travel, train, or shop across those systems, convert once into a single “home unit,” then keep every note in that unit until you must publish the other.\"],\"PMm8O1\":[\"Convert minutes to seconds for workout intervals, exposure times, and PLC timers when coaches or cameras speak in minutes but devices count seconds. Multiply minutes by 60. HIIT clocks and lab protocols share this pair.\"],\"PMyP81\":[\"同意首選項將保留在您的瀏覽器中，直到您清除網站資料或更改它們。僅在回應和改進服務所需的時間內保留回饋訊息。分析和廣告保留遵循每個提供者的政策。\"],\"PN32f0\":[\"這些條款的變更\"],\"PO5-UO\":[\"我們的面積中心和平方米↔平方英尺轉換器頁麵包括常見房間尺寸的表格，因此您可以快速檢查承包商報價。\"],\"PX7ryq\":[\"什麼時候該使用公里而不是米？\"],\"PYUG3T\":[\"Broadloom rolls have fixed widths. Installers compute cuts from room dimensions and roll width—not from area alone. Still, purchasing starts from credible total area so the quote’s square footage matches your sketch.\"],\"PZilhx\":[\"符號很重要：m 表示毫，M 表示兆。當你的意思是毫米時，寫成「Mm」是一場三個數量級的災難。教導初級人員在信任 CAD 匯出之前仔細閱讀符號。\"],\"PZtSIm\":[\"Accuracy, liability, and use limitations for Units Converters conversion tools and educational guides.\"],\"PbQ5rS\":[\"資料儲存也使用兆和千兆，但二進制倍數（mebi、gibi）使該域變得複雜。不要將二進制前綴混淆引入到物理單位轉換中——米仍然是十進制。\"],\"PbVtIn\":[\"Assuming 1 ft ≈ 0.3 m is rough; over a 100 ft span the error is about 0.5 m. Ceiling fans and door kits sold in feet can fail metric rough openings if you round aggressively. Distinguish nautical miles and statute miles from feet before converting long distances.\"],\"PfKowa\":[\"如果表格只接受兩位小數的米，則 175 cm 變為 1.75 m。盡可能保留公分值作為權威測量值。\"],\"PfUo8Q\":[\"Multiplying by 10 is a rough rule that undershoots by ~7%. Converting only one side’s metres to feet then squaring is correct; converting the area with a length factor (×3.28) without squaring is wrong. Balcony and interior areas are often priced differently—convert each zone separately if needed.\"],\"Pj1TgM\":[\"精確因素與測量因素\"],\"PjwxLc\":[\"When an overseas seller lists m² and your contractor thinks in ft², send both totals. Dual reporting catches silent conversion errors faster than arguing about a single number.\"],\"PnJZV8\":[\"天文單位 (au) 是地球與太陽的平均距離，剛好是 149,597,870,700 公尺。它是太陽系距離的標準尺度。\"],\"PoJ1RI\":[\"Keep a paper trail: density value + source + temperature, mass with unit, volume with unit, then the computed third quantity. Unitless triangles are how lab notebooks go wrong.\"],\"PqJDOq\":[\"Weeks remain 7 days. Converting weeks to Julian years is just weeks → days → Julian years. There is no special “Julian week.”\"],\"PrUagd\":[\"What is dimensional weight?\"],\"Ps1Jhc\":[\"典型的共價鍵長度約為一到兩埃。 X 射線晶體學論文通常以埃斯特倫為單位報告晶格參數。轉換為奈米即偏移 ×0.1：1.54 Å = 0.154 nm。轉換為皮米乘以 100：1.54 Å = 154 pm — 有時在量子化學輸出中更受歡迎。\"],\"PtHTOZ\":[\"Gram\"],\"PtYBBn\":[\"Use square miles to square kilometres when US state or county areas must appear in metric atlases and climate datasets. Multiply sq mi by about 2.58999. Journalists localizing US stories for global readers need this pair.\"],\"Pz9b-x\":[\"US cups and fluid ounces are volumes, not masses. A “cup of flour” cannot enter mass = density × volume until you know flour’s bulk density—and that bulk density varies with packing. Prefer weighing flour.\"],\"Q-Aal_\":[\"最佳實務：測量一個系統中的兩側，相乘以獲得該系統中的面積，然後使用面積轉換器轉換面積。不要僅轉換一側。\"],\"Q3pF29\":[\"溫度轉換是仿射的，因為為了方便而選擇了零。長度單位很少需要偏移；溫度幾乎總是適用於攝氏和華氏。\"],\"Q3tCRg\":[\"Units Converters is operated by <0>\",[\"0\"],\"</0>, based in \",[\"1\"],\". We'd love to hear from you.\"],\"Q4wA-D\":[\"一立方英吋約等於 16.4 毫升。在美國，引擎排氣量長期以來一直以立方英吋為單位進行宣傳。\"],\"Q6flYH\":[\"公制長度從米開始。字首乘以或除以十：公里 (1 000 m)、公分 (0.01 m)、毫米 (0.001 m)。面積使用平方公尺和平方公里；土地通常使用公頃（10 000 平方公尺）。體積以公升（正好是 0.001 立方米）和較小的廚房度量單位（例如杯子和立方厘米）為中心。\"],\"QAcHa7\":[\"If you convert boat speed into km/h but leave chart legs in nautical miles—or worse, statute miles—your ETA will be wrong. Keep the chain consistent: nautical miles with knots, kilometres with km/h, statute miles with mph.\"],\"QD8opX\":[\"木板\"],\"QEt68F\":[\"奈米\"],\"QF4ciC\":[\"Speed links distance and time—km/h and mph on roads, knots at sea and in the air, and metres per second in science. Convert carefully so trip planning, forecasts, and instrument displays stay consistent.\"],\"QFlLNW\":[\"Using 1.5 ft/s per mph is close; precision work wants 22/15. Free-fall “fps” tables are not vehicle mph conversions—context matters. Do not confuse ft/s with ft/min used in some conveyor specs.\"],\"QKAJhy\":[\"Converting inches to cm then forgetting to square (×2.54 instead of ×6.4516) understates area by a factor of 2.54. Screen sizes in inches are usually diagonals, not areas—do not convert a “27-inch” monitor as 27 in². Paper “lb” weights are not areas.\"],\"QMJWbW\":[\"烘焙時我該使用哪個杯子？\"],\"QOJxDQ\":[\"Dividing by 3.0 or by 60 (thinking minutes) breaks the result. Car crash Δv in km/h must become m/s before kinetic-energy formulas in joules. Steady cruise in km/h converts cleanly; gust factors are separate meteorology.\"],\"QS9w41\":[\"僅適用於設計可以容忍的軟轉換。對於精確配合，乘以 25.4 後保留必要的小數，並根據保護公差帶的記錄規則進行捨入。\"],\"QSK5SE\":[\"Round durations in the unit you publish. If you report minutes, compute from exact seconds first, then round minutes. Rounding each unit field separately can create impossible times like 2 h 60 min.\"],\"QUbbvz\":[\"在轉換科學長度單位時，優先使用明確的科學記數法和筆記本中的前綴單位：2.5 µm = 2.5 × 10⁻⁶ m。雙重寫入可捕獲轉錄錯誤。\"],\"QX5f4l\":[\"The second (s) is the SI base unit of time. It is defined by the cesium atomic clock transition and underpins all other time units here.\"],\"QYOcKt\":[\"找不到指南\"],\"QZADww\":[\"A typical pattern is: dimensional weight = (L × W × H) / divisor, with L, W, H in centimetres or inches and the result in kilograms or pounds matching the divisor’s definition. Divisors differ by air vs ground and by carrier. Always use the divisor printed for your service level.\"],\"QaYB_2\":[\"Knots as the aviation default\"],\"QjOhRB\":[\"Use our hour ↔ minute ↔ second pages for the span half of the problem; keep a trustworthy world-clock for the label half.\"],\"QkUxaa\":[\"GPS apps on phones may default to mph based on locale even on a boat. Switch the app to knots or nautical miles when navigating on water so the display matches charts.\"],\"QtH51n\":[\"風扇輔助烤箱通常需要比傳統食譜假設的更低的設定點。許多麵包師在改用風扇時溫度會降低約 20 °C（約 25–40 °F）—請查看烤箱手冊。\"],\"QwoePw\":[\"單位轉換重複乘除這些值。將英吋與毫米相互轉換，或將公升與立方公尺相互轉換，您可能會看到 2.9999999997，而不是 3。物理轉換係數是準確的；計算機表示則不然。\"],\"Qxm3lS\":[\"The Julian year is a unit of time duration, not a calendar system. Saying “4 Julian years” means a specific span of seconds. Saying “the year 2026” names a civil date range. Mixing those meanings breaks orbital periods, age estimates, and light-travel explanations.\"],\"R-n0xD\":[\"7,200 seconds of encode time is 2 hours. A 540-second kilometer split talk converts to 0.15 hours only if you truly need hours—minutes are usually clearer.\"],\"R10pPW\":[\"演算範例\"],\"R2KkO0\":[\"A nanosecond (ns) equals one billionth of a second (10⁻⁹ s). Computer clock cycles and light travel over short distances are measured in nanoseconds.\"],\"R7wYzY\":[\"Is higher mpg always better than lower L/100 km?\"],\"RAk7sB\":[\"轉換前的清單\"],\"RCH8pJ\":[\"A milligram (mg) equals one millionth of a kilogram (10⁻⁶ kg). Medicine doses and laboratory samples are often measured in milligrams.\"],\"RGQ9me\":[\"Split L-shaped rooms into rectangles. Measure closets if carpet continues inside. Note doorways and transitions where material stops. For stairs, treat treads and risers with the installer’s method—stair carpet is often estimated separately from floor area.\"],\"RHBcKc\":[\"A week equals 604,800 seconds, or seven days. Work schedules, media cycles, and planning horizons commonly use weeks.\"],\"RK2Vg6\":[\"立方英吋\"],\"RMFRZ8\":[\"A 750 mL wine bottle is 0.75 L. A 5 mL medicine teaspoon is 0.005 L—useful when a protocol lists litres only.\"],\"RMa0EI\":[\"One stone equals exactly 14 avoirdupois pounds. Using the international pound, 1 stone = 6.35029318 kg. UK everyday speech still describes adult body weight in stone and pounds (“11 stone 4”), even though medical records increasingly prefer kilograms.\"],\"RPdunI\":[\"世界上大部分地區的高速公路距離以公里為單位。美國（以及其他一些國家）仍然依賴里程。導航應用程式通常會進行本地化，但印刷指南、比賽號碼布和租車儀表板可能不符合您的直覺。\"],\"RQl72i\":[\"當您在單位列表中看到牛頓力旁邊的牛頓溫度時，請仔細閱讀數量標籤 - 名稱衝突是歷史事故。好的轉換器首先按數量分組，因此溫度牛頓永遠不會與力牛頓並列，從而導致點擊錯誤的工具。\"],\"RUGtUF\":[\"日常實踐中幾乎沒有什麼。它主要出現在歷史討論和綜合轉換器中。使用攝氏或開爾文進行新的科學工作。\"],\"RUrWRo\":[\"Converting stone and pounds to kilograms\"],\"RVVJog\":[\"不同國家的道路標誌不盡相同\"],\"RVZWrs\":[\"1 m³ = 1,000 L = 1,000,000 mL. Those metric relationships are exact. Convert volume into the unit that matches your density’s denominator before multiplying.\"],\"RWLG6K\":[\"返回首頁\"],\"RZdPcg\":[\"Not reliably. Decimal stone means fraction of 14 lb (12.5 st = 12 st 7 lb). Spoken “twelve stone five” means 12 st 5 lb. Prefer explicit stone and pounds.\"],\"Rb2iDn\":[\"盡快將區域單位轉換為公升（或毫升）。以SI友好的體積工作，然後轉換回輸出所需的器具或法定單位。往返升數是防止美國/英國名稱衝突的最便宜的保險。\"],\"Rig0Vc\":[\"轉換 \",[\"translatedUnits\"],\" 等。\"],\"RkEk3w\":[\"What a stone is\"],\"RoafuO\":[\"Send feedback\"],\"RqLaw8\":[\"ell 是一種歷史上的布料長度，此處標準化為 1.143 公尺。裁縫師曾經用它來決定布料的長度。\"],\"RrnUMj\":[\"Convert stone to kilograms when a UK weight mention must enter a metric BMI calculator, racing form, or EU medical record. Multiply stone by 6.35029318. Include any extra pounds by converting them to kg and adding.\"],\"Rzra-p\":[\"Weigh ingredients in grams and ounces, convert between metric and US kitchen units, and know when mass beats cup volume for baking accuracy.\"],\"S5kgXQ\":[\"傾斜地板的平均深度通常為（淺+深）/2。如果有建築商的竣工圖，請確認－猜測深度是通常的誤差來源。\"],\"SBhuQI\":[\"為了精確，放棄估計值。使用轉換器或精確因子，然後舍入到任務的容差。估計櫥櫃的展示量就可以了；估計鏡頭焦距可能不是。\"],\"SCRBEj\":[\"當一張表中的數值跨越較寬範圍時，科學記數法會補充前綴。列內的一致性比每行巧妙的前綴切換更重要。當單位標記沒有每行都改變時，讀者比較數字的速度會更快。\"],\"SDu1SG\":[[\"tTo\"],\"是\",[\"tQuantity\"],\"的單位，用於測量和換算工作。\"],\"SEOydL\":[\"Using 5-day workweeks when the context was calendar weeks. Pregnancy “weeks” still use 7-day weeks, but trimester boundaries are medical conventions on top. Do not mix fortnight (2 weeks) without doubling.\"],\"SI83fF\":[\"一立方十公尺 (dam³) 等於 1,000 立方公尺。大型土木工程和水量可能會使用此 SI 倍數。\"],\"SLzScS\":[\"然後以兩種比例練習面積和體積，以確保平方和立方係數是自動的。大多數殘留錯誤是缺少冪，而不是缺少前綴名稱。\"],\"SNZhsc\":[\"Luggage and airline limits\"],\"SNeon4\":[\"Convert square metres to hectares for gardens, solar arrays, and small farms when a site survey in m² must match agricultural hectare language. Divide m² by 10,000. Planners jump from building footprints to plot scale with this pair.\"],\"SOcVZh\":[\"A 250 g coffee bag is about 8.82 oz—near a common 8 oz retail size after rounding. A 28 g protein snack is essentially 1 oz.\"],\"SSePFE\":[\"一澤米 (zm) 等於 10⁻²1 公尺。此 SI 單位描述了遠小於原子的亞原子尺度長度。\"],\"SUKeRV\":[\"Helpful tools\"],\"SUnXE4\":[\"一立方毫米 (mm³) 等於一微升。醫學和工程將其用於小體積固體或液體。\"],\"S_C6kV\":[\"液體、還原和替代\"],\"Sg5qt0\":[\"mpg and L/100 km conceptual bridge\"],\"SorZ2H\":[\"速度和簡單性：\"],\"SyvevJ\":[\"前綴是十的冪\"],\"T-FuEI\":[\"Moving the decimal three places left instead of right understates dose. Purity percentages apply to mass—convert units first, then apply purity. Moisture loss can change gram readings on a balance without changing the labeled mg of active ingredient.\"],\"T2IREz\":[\"在 Units Converters，我們的使命是提供網路上最準確、可靠且易於使用的轉換工具。無論您是解決物理問題的學生、從事全球專案的工程師，還是只是嘗試遵循食譜的人，我們都確保您的測量準確。\"],\"T2IycL\":[\"為什麼生物學家在同一次談話中說微米和奈米？\"],\"T70EAD\":[\"根据您居住的地方，您可能有权访问、更正、删除或限制对您的个人数据的处理，并有权反对某些处理或撤回同意。要行使這些權利，請發送電子郵件至<0>voyagertecnologias@gmail.com</0>。您也可以隨時拒絕非必要的 cookie。\"],\"TAKEyg\":[\"Use our stone ↔ kilogram and stone ↔ pound pages when you need exact splits instead of guessing leftover pounds.\"],\"TDZWi9\":[\"操作、保護和改進轉換器和導軌\"],\"TF71gP\":[\"實用的轉換策略\"],\"TG9Hex\":[\"5 英尺 10 吋等於多少公分？\"],\"THAiYG\":[\"Convert knots to km/h for marine and aviation contexts when instruments show knots but coastal forecasts or metric pilots want km/h. One knot is one nautical mile per hour = 1.852 km/h exactly. Charts and AIS traffic use knots; phones often show km/h.\"],\"THO4uc\":[\"使用轉換器作為規模健身房\"],\"THeuWL\":[\"湯匙和茶匙也有所不同。公制湯匙通常為 15 毫升，公製茶匙通常為 5 毫升，每湯匙三茶匙。抽屜裡的舊器具可能不符合這些標準——如果精準度很重要，請用量杯校準一次。\"],\"THk9v_\":[\"光時\"],\"TIIXcn\":[\"我可以將平方公尺換算成公升嗎？\"],\"TIoOUm\":[\"Gym programs written in pounds need working weights in pounds. Convert body weight only if the program indexes loads to body weight; otherwise convert the prescribed plate weights, not your nickname weight in stone.\"],\"TKPBkZ\":[\"細菌的尺寸通常約為一微米。人體細胞通常有數十微米。人的頭髮可能有 50-100 微米寬。這些標誌幫助學生檢查轉換後的數值是否荒謬。\"],\"TMETeO\":[\"工程轉換精度\"],\"TOYKlq\":[\"厘升\"],\"TO_q5m\":[\"向供應商匯出的 PLM 必須在文件中註明單位，而不僅僅是在電子郵件中。不明確的 CSV 欄位很可能會成為廢票。\"],\"TOn9Ys\":[\"英畝英吋\"],\"TQX3Zv\":[\"When sharing driving shifts with someone from another country, call out both units for the first hour (“90 km/h, about 56 mph”). Shared speech prevents one driver from “correcting” the other into a ticket.\"],\"TSw1bH\":[\"如何將 \",[\"tFrom\"],\" 轉換為 \",[\"tTo\"]],\"TVgTux\":[\"將 \",[\"tFrom\"],\" 轉換為 \",[\"tTo\"],\" 會損失精確度嗎？\"],\"T_A0L1\":[\"Convert knots, miles per hour, kilometres per hour, and metres per second for aviation and meteorology—without confusing airspeed types or nautical vs statute miles.\"],\"TbASKl\":[\"為聚會增加食譜會放大體積誤差。將主配方轉換為克和毫升，按純數字進行縮放，然後僅當您的客人堅持看到熟悉的器具時才轉換回杯子。\"],\"Tcrwd4\":[\"350 °F 的美國餅乾食譜與 180 °C 的歐洲食譜並不相同，即使這些溫度是預期的轉換對。作家輪流，烤箱運作熱或冷，風扇模式改變熱傳遞。\"],\"Tf4hTi\":[\"原子直徑約 0.1 nm (1 Å)。小分子跨度為幾奈米。許多病毒的尺寸為數十至數百奈米。可見光的波長為數百奈米——將光學與奈米語言聯繫起來。\"],\"TfYIF0\":[\"Large commercial spaces sometimes mention acres for campuses, not for a single room. One acre is 4,046.8564224 m². Do not use acre converters for a bedroom—use m²/ft².\"],\"ThjD5u\":[\"越野賽可能會宣傳「10K」（公里），而美國的訓練計劃則以英里為單位。轉換一次比賽距離並以您喜歡的單位重建配速。\"],\"Tkn2qr\":[\"我们和我们的合作伙伴使用 Cookie 来分析 PostHog 的网站流量、个性化内容并提供相关广告（例如 Google AdSense）。點擊“接受全部”，即表示您同意我們使用 cookie，詳情請參閱我們的<0>隱私權政策</0>。您可以拒絕非必要的 cookie 並且仍然使用轉換器。\"],\"Tm6UVw\":[\"千兆位元\"],\"TvYt-n\":[\"Label outputs: “duration 2 h 15 min” vs “09:00 JST.” Clear nouns prevent Slack threads from inventing physics.\"],\"TxJfTd\":[\"教學與交流量表\"],\"Tz6ERu\":[\"Foot per second is rare in aviation ops but shows up in some engineering notes. Convert via m/s or mph using a speed converter rather than inventing factors mid-briefing.\"],\"U01G6K\":[\"風扇（對流）烤箱可能需要獨立於單位轉換進行溫度調整。閱讀您的設備手冊；正確的攝氏度↔華氏度轉換仍然無法解決風扇與傳統風扇的不匹配問題。\"],\"U52Xlg\":[\"Heart-rate or power targets are independent of unit labels, but the treadmill prescription you programmed is not. Log the unit you actually used.\"],\"U6AfMQ\":[\"When a US recipe says “ounces” for solids, it usually means weight ounces. When it says “fluid ounces” or uses cup marks on a jug, it means volume. Read the word “fluid” carefully.\"],\"U6h7Kn\":[\"Use centimetres to inches when you read a metric product size—screen diagonal, waist measurement, or furniture width—and need the inch figure printed on US packaging or clothing tags. Tailors, online shoppers, and DIY buyers hit this daily. One inch is exactly 2.54 cm, so the conversion is a fixed scale factor with no temperature or material correction.\"],\"UCytWe\":[\"Cookie 設定\"],\"UDdLoM\":[\"Convert metric teaspoons to tablespoons to simplify long spoon counts in cooking and home remedies. Divide teaspoons by 3 when using the metric 5 mL / 15 mL pair. Cake recipes with many small leavening doses benefit from consolidating to tablespoons.\"],\"UGMFzJ\":[\"Use duration converters for spans. Use time-zone tools or explicit UTC offsets for wall-clock labels. This guide trains you to pick the right tool.\"],\"UHep-4\":[\"身高、家具和房間大小是人們最能感受到差異的地方。粗糙的精神錨有助於：1 m ≈ 3.28 ft；30 公分 ≈ 1 英尺； 1.6 公里 ≈ 1 英里。對於精密工作（門間隙、CNC 庫存、3D 列印），請使用精確係數，而不是記憶體。\"],\"ULqYGL\":[\"Convert cubic feet to litres for fridge interiors, grow-tent volumes, and compressed-air receiver sizing when US appliance specs meet metric lab or aquarium gear. One cubic foot is about 28.3168 L.\"],\"ULwqUx\":[\"十次方視頻和宇宙尺度圖形之所以有效，是因為它們以視覺方式行走前綴階梯。將它們與實際的轉換練習配對，以便學生可以計算，而不僅僅是觀看。\"],\"UNBdiw\":[\"NHS-style contexts may accept stones and pounds or kilograms depending on the form. Enter exactly the format requested. If it wants kilograms, convert fully; do not type stone into a kg box.\"],\"UO9JCS\":[\"It depends on the country. In most of the world, highway “100” means 100 km/h (about 62 mph). In the United States, “100” would be mph if used—always read local unit conventions.\"],\"UPaWyO\":[\"立方米 (m³) 是 SI 導出的體積單位。全世界的科學、工業和公用事業都將其視為基本體積單位。\"],\"USuKtG\":[\"面積 (a) 等於 100 平方公尺。它是傳統的公制土地單位，是更常見的公頃的基礎。\"],\"UU2L0x\":[\"每個量表的日常直覺\"],\"UWdTnl\":[\"肘節\"],\"U_ShX5\":[\"一板英尺是指 1 英尺 × 1 英尺 × 1 英吋的木材體積，約 2.36 公升。軟木和硬木交易按板英尺定價木材。\"],\"Uc3hYo\":[\"在許多公制烹飪標準中，是的：每湯匙 15 毫升，每茶匙 5 毫升。古董湯匙和一些地方用具有所不同，因此如果您需要一致性，請在壺中測量一次。\"],\"UhV2qN\":[\"一英畝英吋是指一英畝一英吋深的體積，約 102.8 立方公尺。灌溉規劃通常使用英畝英吋。\"],\"UivcOF\":[\"一光年 (ly) 是光在儒略年中傳播的距離，約 9.46 兆公里。它是最熟悉的星際距離單位。\"],\"UkCnks\":[\"英里（國際）\"],\"UkoBlY\":[\"將光年轉換為公里會產生巨大的整數。在報告中更喜歡使用科學記數法。如果您需要與目錄值一致，請檢查轉換器的光年是否與儒略年定義相符。與外展的宇宙距離相比，年份定義的不匹配很小，但當您將兩個目錄與許多重要數字進行協調時，這一點就很重要。\"],\"UltkWC\":[\"Convert metres to kilometres for race distances, hiking elevation gain written in metres of trail length, and city planning where short SI lengths become map-scale distances. Sensors and GPS traces often store metres; reports prefer kilometres. Divide metres by 1,000.\"],\"Uo19sX\":[\"一立方百公尺 (hm³) 等於一百萬立方公尺。水庫容量和河流流量通常以 hm³ 為單位。\"],\"Uxl_dU\":[\"<0>即時結果：</0>鍵入時即時轉換。\"],\"V4t9Ir\":[\"Convert millilitres to cups when a European recipe lists mL but your scoop set is cups only. Divide by your cup size (often 240 or 250 mL). Home bakers scaling drink and batter volumes use this daily.\"],\"V5Tvw0\":[\"A 500 L rain barrel is 0.5 m³. A small pool holding 25,000 L is 25 m³ for chemical dosing charts that use grams per m³.\"],\"V5YFZA\":[\"一立方公分（cm³ 或 cc）等於一毫升。醫學和引擎排氣量常用這個名稱。\"],\"V8BCPQ\":[\"GD&T 架構和基準方案在邏輯上與單位無關，但在數字上與單位相關。連貫地更新整個特徵控制框架集。\"],\"V8FT3D\":[\"Gym treadmills may default to mph in the US and km/h elsewhere. Hitting “10” intending 10 km/h on an mph treadmill is an all-out sprint (~16 km/h). Check the unit indicator every time you start a belt on travel.\"],\"VBmYgh\":[\"<0>\",[\"tFrom\"],\"</0> 和 <1>\",[\"tTo\"],\"</1> 之間的精確轉換首先以 \",[\"tQuantity\"],\" 基本單位表示源值，然後將該基值轉換為 \",[\"tTo\"],\"。對於一對一檢查：1 \",[\"0\"],\" 等於 \",[\"oneToOne\"],\" \",[\"1\"],\"。\"],\"VFTGk_\":[\"日常生活中的溫度通常為攝氏度；科學和工程經常使用開爾文，它與攝氏度具有相同的度數，但從絕對零度開始。日常尺度和科學尺度的分離本身就是公制世界的習慣。\"],\"VHl_vm\":[\"值得信賴的轉換器的實用規則\"],\"VIqLb7\":[\"A kilometre per hour (km/h) equals one kilometre of travel in one hour, or exactly 1/3.6 metres per second. Road signs worldwide display vehicle speed in km/h.\"],\"VJwMZF\":[\"本政策的變更\"],\"VKWvvx\":[\"重新檢查壁櫥和走廊區域；它們很容易被忽略，而且排序不足也會帶來痛苦。如果飾面材料繼續進入其中，則包括壁龕。\"],\"VNGnij\":[\"Convert minutes to hours for payroll, flight duration summaries, and battery-life claims when the raw timer is in minutes. Divide minutes by 60. Timesheets and travel itineraries prefer fractional or HH:MM hours.\"],\"VOckpV\":[\"How do I convert knots to km/h?\"],\"VP4uYe\":[\"Convert seconds, minutes, hours, and days without off-by-sixty errors, choose appropriate precision for sports and science, and keep timestamps consistent.\"],\"VPh8EE\":[\"Units Converters是一款面向大眾的教育工具。我們不會故意收集 13 歲以下（或您所在地區的同等年齡）兒童的個人資訊。如果您認為兒童提供了數據，請聯絡我們，我們將刪除該數據。\"],\"VPrFdY\":[\"Use kilometre ↔ mile and km/h ↔ mph pages to clean trip data, and litre ↔ cubic metre when bulk fuel deliveries show up in m³. Apply a dedicated L/100 km ↔ mpg formula when you need the economy number itself.\"],\"VXw9AH\":[\"百萬米\"],\"VYUQn1\":[\"當計劃混合單位時，請將圖形轉換為工具顯示的單位。美國的捲尺通常顯示英吋；許多公製捲尺顯示公分和毫米。雙刻度磁帶有幫助，但仍需要注意您讀取的邊緣。\"],\"VbArEP\":[\"本服務條款管轄您對 Units Converters 的使用。透過造訪或使用本網站，您同意這些條款。\"],\"Vfv6_l\":[\"牛頓溫標（不要與力單位混淆）是一個歷史溫標，有時仍列在轉換器中。它很少在現代實驗室工作中使用，但它提醒我們，在攝氏溫度和開爾文統治科學之前，許多尺度曾經相互競爭。\"],\"VlmgF-\":[\"對於小比例的面積和體積，請記住正方形和立方體。一平方微米與一平方毫米的關係不是 1 000，而是 1 000² = 10⁶。當缺少該功率時，微流體體積計算會嚴重失敗。\"],\"VwehPU\":[\"今天使用的牛頓溫標是什麼？\"],\"Vxf_Bz\":[\"Tire speed ratings and placards may list km/h even on US cars. Convert before comparing to your planned cruise speed in mph. The rating is a limit, not a suggestion to drive that fast.\"],\"VyfrRh\":[\"油漆覆蓋面積為面積；塗料採購是按量計算的。您需要牆壁面積、塗層數量和覆蓋率（平方公尺每公升）才能找到公升。如果沒有覆蓋數據，直接將牆壁平方公尺換算成公升是沒有意義的。\"],\"W-eFzo\":[\"<0>面積：</0>平方公尺、英畝、公頃及穀倉。\"],\"W4Zked\":[\"Airspeed is a speed—with extra labels\"],\"W59184\":[\"該指南不存在或可能已移動。\"],\"W7S3Hm\":[\"Does cubic metres equal shipping weight?\"],\"WA7PCY\":[\"對於絕對熱力學數據，更喜歡開爾文，對於許多實驗數據集，更喜歡帶有明確標籤的攝氏度。切勿未標記溫度數字。\"],\"WBkzOv\":[\"喜歡透過基本單位進行轉換，而不是透過許多中間習慣單位進行轉換。每一次不必要的跳躍都是抓住錯誤因素或過早回合的另一個機會。\"],\"WD9Tp-\":[\"二進制浮點數不能準確地表示許多小數因數。每次乘法或除法都會增加微小的捨入誤差。即使轉換因子在概念上是準確的，通過浮點的往返轉換通常也無法恢復原始位元。\"],\"WFyvQB\":[\"太陽能發電場和運動場的比較通常在一篇文章中引用公頃，在另一篇文章中引用英畝。在爭論哪個網站更大之前先進行轉換。\"],\"WHjBY8\":[\"毫米尺加工和產品設計。米統治著建築和人類運動。連接地標的階梯使 SI 前綴感覺像地方，而不是瑣事。\"],\"WHnM4j\":[\"Convert litres to hectolitres for brewery KPIs, dairy intakes, and bulk wine contracts that report in hL. Divide litres by 100. Trade statistics and cooperative milk collections often prefer hectolitres.\"],\"WJkwxx\":[\"長度測量距離－從材料科學中的奈米到天文學中的光年。使用此中心探索日常和科學長度單位，然後打開任何對進行高精度轉換。\"],\"WKFLlL\":[\"Meeting invites, flight itineraries, and “call me at 3 pm” messages need zone labels (CET, EST, UTC+9, etc.). Ambiguous “3 pm” is social debt. Ambiguous duration (“in 3 hours”) is relative to “now” and still needs a shared understanding of the starting instant.\"],\"WKHqM-\":[\"Weight\"],\"WLBBw6\":[\"導出單位（壓力、密度、流量）應盡可能來自一致的基礎系統。相干性減少了方程式中轉換因子的數量。\"],\"WY1BnO\":[\"Should I convert stone or pounds for a metric form?\"],\"W_4OFG\":[\"2 metric tablespoons of olive oil equal 6 metric teaspoons—handy when you only have a 5 mL spoon. A recipe calling for 1½ tbsp yeast is 4.5 tsp.\"],\"W_qbAO\":[\"Batch scaling: convert everything to grams, multiply by the scale factor, then convert back to ounces only if your audience insists. Scaling in mixed units invites rounding drift.\"],\"Wa3fck\":[\"Grams and Ounces on a Kitchen Scale\"],\"WfKhnj\":[\"Adding 50% (×1.5) understates true km/h. Aircraft indicated airspeed in knots is not mph—convert knots separately. Treadmill mph to km/h is the same factor as road speed.\"],\"WgkOAz\":[\"A 6-week physiotherapy program is 42 days. A 2-week vacation hold is 14 days of uninterrupted leave if using calendar days.\"],\"WhFxj8\":[\"華氏溫標隨著儀器貿易而傳播，並仍然根植於美國的天氣文化和一些工業實踐中。它的度數比攝氏度小，對於日常天氣談論來說感覺更細緻。這種文化影響力就是雙尺度預測對國際受眾仍然有用的原因。\"],\"WlBf88\":[\"一平方公里不是 10³ 平方米，而是 (10³)² = 10⁶ 平方米。一立方公分等於 (10⁻²)³ = 10⁻⁶ 立方公尺。忘記對前綴冪進行平方或立方是典型的 SI 縮放錯誤。\"],\"WmSRQz\":[\"不平等的公差和配合（H7/g6 風格的思維，即使歷史上以英寸表示）需要特別小心。轉換定義配合的限制尺寸，而不僅僅是單一中間值。\"],\"Wnp9Ov\":[\"Use our gram ↔ ounce and kilogram ↔ pound converters to rebuild a US recipe into metric mise en place before the oven preheats.\"],\"WtPE23\":[\"在杯子旁邊公佈毫升。將升與加侖一起發布。與失敗的批次和憤怒的評論相比，雙重標籤是便宜的。\"],\"WtrXiU\":[\"Using 4 teaspoons per tablespoon (an older US folk rule for some ingredients) breaks metric recipes. Liquid medicines may use a “teaspoon” marking that is not exactly 5 mL—prefer the mL scale on the syringe. Salt and spices packed tightly change mass a lot even when volume conversion is perfect.\"],\"WvwI2N\":[\"我們的免費線上轉換器是在公制和英制系統之間切換的最快方式。節省複雜數學的時間，並為學校、實驗室工作或建築專案獲得可靠的轉換。\"],\"WxMd7u\":[\"This site’s converters handle the building blocks—kilometres vs miles, litres vs other volumes, km/h vs mph for trip pace. Use them to sanitize inputs, then apply a proper economy formula or a dedicated economy calculator when comparing L/100 km to mpg.\"],\"WxgxzV\":[\"Why doesn’t this guide use Mach?\"],\"WzwMp2\":[\"Convert kilograms to stone for body weight in the UK and Ireland, where stone remains common in conversation and some medical contexts. One stone is 14 avoirdupois pounds, exactly 6.35029318 kg. Athletes and clinics still quote stone and pounds together.\"],\"X-Ka-p\":[\"A 750 g loaf is 0.75 kg. Buying 2,500 g of flour is a 2.5 kg bag—standard supermarket sizing.\"],\"X0e445\":[\"閱讀 Units Converters 的服務條款，包括使用免責聲明、智慧財產權、廣告、PostHog 分析和責任限制。\"],\"X36JoS\":[\"廣告\"],\"X5k61m\":[\"清楚地解釋了光年作為長度單位的含義——它與米的關係、天文學為何使用它以及它與天文單位和秒差距的比較。\"],\"X7ADLJ\":[\"Convert Kelvin to Celsius when a datasheet, blackbody formula, or cryogenics note lists K but you need everyday Celsius for baths, freezers, or weather context. Subtract 273.15. Space and semiconductor docs often stay in K until the last step.\"],\"X7ej7z\":[\"對於教育太陽系和鄰近恆星問題，簡單的光行距離是合適且明確的。為已經涵蓋擴展空間度量的課程保留宇宙學距離測量的細微差別；過早引入它常常會混淆光年長度的核心教訓。\"],\"XApVRd\":[\"Use the feedback form further down this page to describe an issue, suggestion, or question. We'll get back to you as soon as possible.\"],\"XCAO54\":[\"Irregular bays: approximate with rectangles and triangles, sum areas in one unit, then convert once. Rounding each polygon before summing can leave you short by a square metre you will notice at the seam.\"],\"XD51Kk\":[\"Julian Year vs Calendar Year\"],\"XFAKr4\":[\"如果您建立計算器 UI，請顯示足夠的精度以供使用，但不要顯示過多的數字，以免浮動雜訊看起來像訊號。透過浮點數轉換後顯示十二位小數的長度工具正在宣傳其表示錯誤。\"],\"XGP_rY\":[\"Google AdSense\"],\"XH9-3w\":[\"Aviation: airspeed in knots\"],\"XIG4FZ\":[\"Parcel shops and post offices price by weight tiers. Crossing a tier by 50 g because you mixed oz and g is an expensive lesson. Keep the shipping label’s unit visible while you pack: if the rate card is in kilograms, convert ounces to grams or kilograms before you seal the box.\"],\"XJ9IEG\":[\"Can I convert mpg by flipping the number?\"],\"XJaAmA\":[\"當專案規模發生變化時重新檢視選擇：以毫米為單位的原型可能會變成以公尺為單位的場地規劃，而無需任何人更新電子表格標題。標題很重要。為長項目建立一頁單位登記冊，列出數量、權威單位、顯示單位和轉換所有者，以便更改留下審計線索。\"],\"XKamta\":[\"Average speed on a road trip is far below the posted limit. Use a realistic average (including fuel stops) in one unit system. Convert the posted limit separately when you want to know “how fast am I allowed to go,” not “how fast will I average.”\"],\"XKo6WE\":[\"為學生、工程師、廚師以及任何需要轉換單位而無需事後猜測數學的人提供實用、原創的解釋。\"],\"XRHIH3\":[\"實踐中出現浮點錯誤的地方\"],\"XWP4R4\":[\"澤米特\"],\"XY2X9o\":[\"Multiplying by 3.0 or forgetting 3.6 leaves wind speeds looking too calm. Swimming and current speeds in m/s look tiny next to km/h—expect large-looking km/h numbers. Do not mix per-second pace clocks with this without converting time bases.\"],\"XaDs5F\":[\"土地面積仍經常使用英畝（約 4 047 平方公尺）。平面圖可能會將平方英尺與公制房間尺寸混合在一起。這種混合在跨越新舊圖紙的翻新中很常見 - 在切割材料之前，始終將整個圖紙集轉換為系統。\"],\"Xap8Hr\":[\"Planck長度和其他極端單位\"],\"XedTWK\":[\"Package net weight may show grams and ounces together. Serving sizes sometimes mix mL and g. Convert only within the same quantity type. Calories per ounce change when you confuse weight ounces with fluid ounces of a drink.\"],\"XmGuwW\":[\"家庭烹飪融合了傳統。美國食譜依賴杯子和湯匙；許多歐洲和專業糕點食譜更喜歡克和毫升。杯子是體積，而不是重量，因此即使杯子相同，一杯過篩的麵粉和一杯包裝紅糖的品質也不同。\"],\"XmONrS\":[\"一間穀倉 (b) 等於 10⁻²⁸ 平方公尺。粒子物理學家將其用作核和粒子相互作用截面的方便單位。\"],\"XpHBGy\":[\"Use knot ↔ km/h and m/s ↔ km/h tools to translate forecasts and stories, then return to knots for cockpit flows if that is your training standard.\"],\"Xqls_6\":[\"Convert kilograms to grams for baking percentages, supplement scoops, and chemistry stock solutions when the bulk bag is in kg but the formula lists grams. Multiply kg by 1,000. Baker’s percentages become easier in grams.\"],\"XskNVQ\":[\"您實際需要的公式\"],\"Xt1R7n\":[\"體積涵蓋了容量和三維空間——廚房裡的升，建築和水池裡的立方米，以及精細的科學單位。當配方或化學圖表混合杯、毫升和立方米時，請小心轉換。\"],\"XtXXfW\":[\"Economy combines volume and distance\"],\"Xtt-ms\":[\"Rule of thumb planning: time (hours) ≈ distance / speed when units match. Nautical miles with knots; kilometres with km/h; statute miles with mph. Crossing those streams is the main arithmetic failure in amateur flight planning.\"],\"Xu4jEX\":[\"A kiln note of 1800 °F is about 1255 K—useful when a ceramics paper cites peak temperature in kelvin. Room temperature ~70 °F is roughly 294 K for electronics thermal margins.\"],\"Xv57vu\":[\"從奈米向上的里程碑\"],\"XvOxd6\":[\"Label every number: “72.1 kg (11 st 4 lb).” Dual labels prevent the 11.4 disaster.\"],\"XvfqE9\":[\"Metres per second appear in scientific wind data and some European forecasts: 1 m/s = 3.6 km/h ≈ 1.94384 kt. A “10 m/s wind” is about 19.4 kt—not 10 kt.\"],\"XvxBAn\":[\"0 K 與−273.15 °C 相同嗎？\"],\"XwHg-N\":[\"廚房和陸地上的體積和麵積\"],\"Y-SutJ\":[\"將 \",[\"tFrom\"],\" 轉換為 \",[\"tTo\"],\" |精確的\",[\"tQuantity\"],\"轉換器\"],\"Y1DI3m\":[\"化學品包裝和 SDS 文件應明確註明公升或立方公尺。如果出現加侖，請尋找美國標籤和英制標籤。在稀釋計算中出現錯誤會帶來安全隱患，特別是對於濃縮液而言，20% 的體積誤差並不是表面現象。\"],\"Y1Xhts\":[\"Speed, distance, and why pace shows up\"],\"Y5XbW2\":[\"轉換英畝、公頃和平方米\"],\"YA1fYO\":[\"首先轉換為基本 SI 單位，然後轉換為目標前綴。這種兩步驟的習慣可以防止你在疲勞時陷入混亂的心理小數點移動。\"],\"YANIWB\":[\"光學和奈米技術中的奈米\"],\"YAz6UJ\":[\"Volume units at the pump\"],\"YCLtFa\":[\"Train timetables that cross borders print local times per station. Differences require zone-aware subtraction; the resulting travel time is a duration you can convert to minutes for comparisons.\"],\"YE8Pkt\":[\"遵守法律義務\"],\"YF5RAs\":[\"公里\"],\"YFMgyy\":[\"Convert Fahrenheit to Celsius for European recipes, lab protocols, and weather comparisons when the source is US customary. Fever checks and pool heaters also flip between scales. Use °C = (°F − 32) × 5/9.\"],\"YHE0TT\":[\"茶匙中的酒精和提取物看起來微不足道，直到您為人群調製雞尾酒或調味品。轉換為毫升，稱量，然後用壺或註射器分裝以確保一致性。\"],\"YHivUp\":[\"We may also use contextual networks such as Media.net, and optional affiliate links (for example Amazon Associates) on guide pages. Affiliate partners may set cookies when you follow those links. See our Disclaimer for commission disclosure. These partners only load after you accept cookies where consent is required.\"],\"YILUJE\":[\"Planck 長度（~1.6 × 10⁻3⁵ m）是基本常數的理論尺度，而不是實驗室量尺。轉換器可能會將其包含在教育目的中；它不適用於加工零件。將任何測量到 Planck 長度的實際主張視為對單位作用的誤解。\"],\"YIjZh5\":[\"專業轉換器在背景執行相同的代數運算。它們將每個單位儲存為相對於基本單位的比例（有時是偏移量），然後轉換輸入→基本→輸出。了解這種模式可以讓每個轉換器變得不那麼神秘。\"],\"YJR-DR\":[\"單位是如何定義的\"],\"YLKekz\":[\"國際碼正好等於 0.9144 公尺（3 英尺）。它常見於織物、運動場和美國習慣尺寸。\"],\"YLrn-T\":[\"切勿在二進制浮點數上測試嚴格相等的轉換器。在絕對或相對容差範圍內進行比較，或以規定的精度比較十進位字串形式。首選使用已知精確對的黃金測試，例如 1 英吋 = 25.4 毫米。\"],\"YMilyE\":[\"從早期的測溫儀到攝氏溫度、華氏溫度、開爾文溫度和牛頓溫度——溫標是如何演變的以及為什麼多種溫標仍然出現在轉換器中。\"],\"YO0ACR\":[\"為什麼高度表格會導致如此多的錯誤\"],\"YOu4q0\":[\"大多數 CPU 以二進位浮點數 (IEEE 754) 儲存非整數。在十進制中看起來很簡單的分數（0.1、0.001、2.54）通常無法用二進位精確表示。儲存的值是最接近的可表示的近似值，而近似值的算術會累積微小的殘差。\"],\"YPKA9a\":[\"The site is provided \\\"as is\\\" without warranties of any kind, express or implied. \",[\"0\"],\" does not guarantee uninterrupted availability, error-free pages, or suitability for a particular purpose. See our Terms of Service for full liability limits.\"],\"YQA630\":[\"Using 236.59 mL (US customary cup) vs 240 mL (US legal cup) vs 250 mL (metric cup) without matching the recipe’s origin. Thick batters measured in a liquid cup still need leveling technique. Do not convert mL of flour to cups and then to grams with a single universal factor.\"],\"YQHoDn\":[\"歷史上的乾品脫和誇脫添加了另一層與現代家庭烹飪很少相關但仍然存在於檔案中的層。未經檢查，請勿假設一品脫乾品脫等於一品脫液體。\"],\"YR0sYg\":[\"一公分 (cm) 等於 0.01 公尺。它是身體測量、服裝和學校科學中最熟悉的公制單位之一。\"],\"YST1aG\":[\"世界上大多數人使用的溫度尺度和測量單位。\"],\"YX3h2a\":[\"國際單位制 (SI) 中長度的基本單位。\"],\"YdoKWF\":[\"我們的升↔立方米頁麵包含參考表，可在您打開化學罐之前輕鬆進行快速健全性檢查。\"],\"YecQDf\":[\"有效數字應反映最不精確的輸入，而不是計算器的顯示。精確到毫米的捲尺並不能證明將轉換後的英吋值報告為小數點後六位。\"],\"Yg-ssR\":[\"nm → µm：除以 1 000。 µm → mm：除以 1 000。 mm → m：除以 1 000。每個步驟都是十的三個數量級。 nm → m：除以 10⁹（或乘以 10⁻⁹）。練習這些輪班，直到它們在考試或輪班壓力下自動進行。\"],\"YgbpQ6\":[\"一躍米 (ym) 等於 10⁻²⁴ 公尺。它是一個 SI 長度前綴，用於粒子和核物理環境中的極小距離。\"],\"YmJ6sD\":[\"一公製茶匙等於 5 毫升。烹飪食譜將其用於小量液體和粉末的量取。\"],\"YmsuYf\":[\"國際食譜通常將公制體積與攝氏烤箱配對，而美國食譜則將杯子與華氏度配對。使用適當的仿射公式轉換溫度；不要將烤箱設定視為體積因素。\"],\"YnThcK\":[\"Use yards to feet for American football, fabric spreads, and garden bed lengths when the quote is in yards but the tape measure reads feet. Three international feet make one yard exactly. Contractors pacing a site in yards often switch to feet for cut accuracy.\"],\"Yp8yB4\":[[\"0\"],\" 至 \",[\"1\"]],\"YrH-Uw\":[\"移液器、微米（工具）和奈米解析度階段都要求您將前綴含義與工具名稱分開。英語使用微米作為工具和單位拼字變體——上下文可以防止混淆。\"],\"YvLaWs\":[\"課堂和溝通技巧\"],\"YxzxC0\":[\"US friends and apps expect a single pound figure. Convert UK stone-and-pounds to total pounds before sharing. 11 st 4 lb = 158 lb, not “11.4 lb.” That error is an order of magnitude wrong and alarms health apps.\"],\"Yy6PSV\":[\"Density is a derived quantity (mass per volume). You convert its mass and volume parts into consistent units; you do not treat density as a simple length-style unit on this site.\"],\"YyM7nn\":[\"面積測量表面積：房間以平方公尺或平方英尺為單位，土地以公頃和英畝為單位。選擇下面的起始單位，然後轉換為任何其他面積單位，無需舍入漂移。地板和土地單元指南與這些工具完美搭配。\"],\"YyOvgd\":[\"校準證書本身使用單位——請閱讀它們。在公制 CMM 程式中，以英吋為單位設定的量塊不小心轉換為毫米是一種製程風險。\"],\"YziFbt\":[\"確定作者假設的杯子和湯匙標準。將所有體積轉換為毫升。盡可能將乾成分轉換為克。規模。僅轉換回您實際使用的工具。\"],\"Z-2qls\":[\"資料保留\"],\"Z0G7sT\":[\"我們的託管和合作夥伴可能會在您所在國家/地區以外的國家/地區處理資料。如有需要，我們會依賴這些提供者提供的適當保障措施。\"],\"Z0za9b\":[\"大多數線上轉換器都存在舍入誤差，因為它們使用標準浮點運算。我們的工具是使用 <0>Decimal.js</0> 建構的，這是一個用於任意精度十進制算術的函式庫。這意味著當您轉換單位時，您可以獲得數學上完美的結果，而不會出現其他工具中常見的「0.000000000004」工件。\"],\"Z2EPvT\":[\"公制湯匙總是 15 毫升嗎？\"],\"Z2oISo\":[\"Spices in pinches stay volumetric by nature. Convert spice weights only for large commercial batches.\"],\"Z3J4ir\":[\"當受眾或法規跨系統分裂時，就會出現雙重標籤。避免已經共享一個系統的專業文件變得混亂——清晰的單一單元標籤更好。\"],\"Z477h6\":[\"Record fuel volume added and distance driven in consistent units. Convert miles → kilometres (× 1.609344) if your odometer and pump disagree across a border rental. Convert gallons → litres if the receipt and the car computer disagree.\"],\"Z5mL6k\":[\"食品標籤制度在法律上對杯子和份量的定義可能與祖母的量杯不同。遵守包裝規定；遵循經過測試的食譜進行烹飪。當兩者在產品開發廚房中發生衝突時，應保留單獨的規格表，而不是強制使用一個模糊的杯子列。\"],\"Z7mHoI\":[\"燃油經濟性使問題更加複雜：L/100 公里與每加侖英里數的關係顛倒了體積和長度的思維。在比較不同市場的汽車時，透過全維度分析而不是記憶的近似係數進行轉換。\"],\"Z9CT1Q\":[\"Looking for a physical tool that matches this guide? Search Amazon for related measuring equipment. We may earn a commission at no extra cost to you.\"],\"Z9_zXG\":[\"開爾文\"],\"ZAGGpv\":[\"從受眾和標準入手\"],\"ZC-5dI\":[\"十米\"],\"ZCGBkz\":[\"For civil history—“how many calendar years between these two dates?”—use calendar arithmetic or a mean Gregorian year if you only need an approximation. For converting a physics duration labeled as Julian years, divide or multiply with 365.25 days per Julian year.\"],\"ZCr-px\":[\"如果你正在學習這兩個系統，請用你能看到的長度來練習——桌子寬度、行走速度、牛奶盒體積——這樣數字就固定下來了。流暢性勝過記住在壓力下不會使用的長表格。在記憶體中保留一個精確的錨點（每英吋 25.4 毫米），並在精確度很重要時導出其餘錨點。\"],\"ZKbrdx\":[\"<0>長度：</0>奈米到光年和Planck長度。\"],\"ZOiTtE\":[\"巨型、千兆和大規模措施\"],\"ZQ7HqJ\":[\"Keep a single sticky note on the dash for the first day abroad: “limits are km/h” or “limits are mph,” plus two anchor conversions you actually saw on the route.\"],\"ZQyX5Z\":[\"提交回饋\"],\"ZR5WG6\":[\"哈伯長度是與哈伯常數相關的宇宙學距離尺度，約為 10²⁶ 米，與可觀測宇宙的大小相當。\"],\"ZTiCle\":[\"為什麼要透過基本單位而不是直接因子來轉換？\"],\"ZU3Tsr\":[\"Confusion starts when people subtract clock faces in local labels without converting both instants to a common timeline. 22:00 in Paris to 08:00 next day in New York is not “10 hours” of subtraction on the printed numbers alone—you must interpret zones and dates.\"],\"ZXmZ3y\":[\"Grams, kilograms, and milligrams\"],\"ZbRlst\":[\"Students sometimes convert a wind of 15 kt to “15 mph” by changing the label without changing the number. That understates wind. Always run the factor.\"],\"ZcqHCH\":[\"Convert hours to days for project timelines, drug half-life discussions, and SLA windows when engineering logs hours but managers want days. Divide hours by 24. Incident postmortems often make this switch for readability.\"],\"ZdYW_Q\":[\"一公升 (L) 等於 0.001 立方公尺。它是飲料、燃料和家用液體的日常公制單位。\"],\"Zdx59c\":[\"Linking speed to distance and time\"],\"ZfFcAX\":[\"資訊共享\"],\"Zk5s7v\":[\"一澤米 (Zm) 等於 10²1 公尺。它是用於宇宙距離討論的 SI 極值。\"],\"ZlDKKP\":[\"更喜歡重量。麵粉堆積密度的變化足以改變麵包屑並膨脹。如果您只有杯子，請使用一致的方法（通常是湯匙和水平儀）並接受更多的批次差異。\"],\"ZlwDi6\":[\"分析\"],\"ZnNRL9\":[\"可見光的波長約為 400–700 nm。將雷射指定為 532 nm 比 5.32 × 10⁻⁷ m 更清晰。薄膜塗層和繞射問題自然存在於奈米級。只看過科學計數法的學生在轉換為奈米時經常會錯誤地計算零——並排練習這兩種形式。\"],\"ZoK1ii\":[\"Tip: knots pair with nautical miles; mph pairs with statute miles. Convert road signs before matching the number. Check whether a treadmill shows km/h or mph before you trust a “10.”\"],\"Zp9qhp\":[\"Clocks label moments; durations measure spans\"],\"Zq12B2\":[\"Decide your coaching unit (min/km or min/mile). Convert the session into treadmill speed in the console’s unit. After the run, convert back to pace for the training log so weeks stay comparable.\"],\"ZqDero\":[\"輕分鐘\"],\"ZqGv10\":[\"根據米的 SI 定義，真空中的光速恰好為 299 792 458 m/s。儒略年為 365.25 天，即 86 400 秒。將速度乘以該時間間隔即可得到天文學中所使用的光年長度。\"],\"ZstIvO\":[\"Integer division that drops the remainder hides overtime seconds—keep a decimal or a seconds remainder. Leap seconds affect UTC civil time rarely and do not change everyday workout math. Do not convert seconds of arc (angles) with a time converter.\"],\"ZwDOLi\":[\"以公升和立方公尺為單位記錄體積（如果當地供應商使用加侖，則以加侖為單位）。如果水位有顯著變化或改造，請更新該卡。\"],\"ZxHSV2\":[\"平方公里\"],\"Zz1yNB\":[\"一立方英哩約等於 4.17 立方公里。含水層或冰蓋等大型自然特徵可以用立方英里來描述。\"],\"_1PTQU\":[\"Wind reports in marine forecasts often use knots. A “20-knot wind” is about 37 km/h or 23 mph. Small-craft advice thresholds are written in knots in many countries; convert only after you understand the category boundaries.\"],\"_5hjoq\":[\"Using 0.1 m² per sq ft overstates area. Office “usable” vs “rentable” sq ft still convert with the same factor—definitions differ, units do not. Do not convert linear feet of baseboard as if they were square feet.\"],\"_798Yd\":[\"Highway efficiency depends on speed. Comparing a US road trip logged in mph with a European test cycle talked about in km/h needs speed conversion so you compare similar driving, not just similar labels.\"],\"_7YLdO\":[\"國際英吋正好等於 25.4 毫米。它仍然是美國習慣系統中的主要長度單位。\"],\"_8v4gg\":[\"在冰箱上放一張小卡片，上面寫著您最常用的對：杯子↔毫升，湯匙↔毫升，黃油棒↔克（如果您所在國家/地區相關）。習慣勝過中擊打獵。\"],\"_AG8g3\":[\"5 英尺 10 英吋總計 70 英吋。一國際英寸為 2.54 厘米，因此 70 × 2.54 = 177.8 厘米。依照表格規則進行舍入。\"],\"_EVpXF\":[\"Units Converters 可以在公分、公尺、英尺和英吋之間移動，並具有精確的係數。當您需要對常見成人身高進行快速健全性檢查時，請使用每對頁面上的工作範例。\"],\"_GYo86\":[\"Fluid ounces measure volume, not mass. “8 fl oz of milk” is not the same measurement type as “8 oz of flour” by weight. Thick syrups and flour cannot be swapped between fl oz and oz without density.\"],\"_GzALU\":[\"Planck 長度\"],\"_I5kek\":[\"全部指南\"],\"_JuTsa\":[\"Half-stone changes (7 lb ≈ 3.2 kg) are common in fitness talk. Convert the change the same way you convert absolute weight.\"],\"_LMkMS\":[\"全部接受\"],\"_LnHMO\":[\"Assuming a yard is “about a metre” leaves you short on material. Cubic yards of mulch or concrete are volume, not length—do not run them through a length converter. Keep fractions of a yard (½ yd) as 0.5 before multiplying by 0.9144.\"],\"_S1r77\":[\"The Gregorian calendar’s mean year is 365.2425 days (97 leap days per 400 years). That is about 0.0075 days (roughly 11 minutes) shorter than 365.25. Over one year the difference is tiny for casual talk; over millennia or precise ephemerides it accumulates.\"],\"_Ti6Zc\":[\"微升\"],\"_TxE4G\":[\"每國際英吋正好 25.4 毫米。使用該係數進行技術工作，而不是舊的大約 25 毫米的經驗法則。\"],\"_URfYe\":[\"Content on this site — including converters, tables, guides, and examples — is general information only. It is not legal, medical, financial, safety, or engineering advice. If your use case involves health, regulated products, structural design, or legal compliance, consult a qualified professional.\"],\"_W-19G\":[\"1 µm 等於 1 000 nm 嗎？\"],\"_cF7Rs\":[\"體積\"],\"_hBRwC\":[\"為您的工作選擇一個規模\"],\"_jQctM\":[\"到\"],\"_nJAQe\":[\"好的測量首先要選擇一個讓數字舒適的單位。家具組裝以毫米或英吋為單位。房間佈局以米或英尺為單位。公路旅行以公里或英里為單位。使用公里來描述螺距會導緻小數點變得尷尬；在公路旅行中使用毫米會迫使使用巨大的整數。舒適度是一種可用性特徵，而不是外觀偏好。\"],\"_siJPA\":[\"硬轉換和軟轉換有什麼區別？\"],\"_tLS2h\":[\"Science and some vehicle test reports use metres per second. 1 m/s = 3.6 km/h exactly. That bridge is handy: convert m/s → km/h by multiplying by 3.6, then to mph if needed. Crash-test and physics problems almost never want mph as an intermediate.\"],\"_tNHZe\":[\"US mpg usually means US gallons; UK historical mpg used imperial gallons. Always note which gallon. Metric countries lean on L/100 km or km/L.\"],\"_tTlsI\":[\"在比較轉換器輸出時，最後一位微小的差異通常來自舍入策略，而不是來自不同的物理常數。檢查兩個工具是否使用國際英吋、相同的英畝定義和相同的顯示精度。\"],\"_uNC6p\":[\"要拆分總英吋值：將英尺除以 12，並將餘數用作英吋。標記兩個數字。當您的意思是 5 英尺 9 英寸時，切勿寫“5.9 英尺”——它們是不同的高度。\"],\"_wcYGD\":[\"Convert body weight, luggage, and grocery labels between kilograms and pounds with exact factors, mental shortcuts, and habits that prevent airport and gym mistakes.\"],\"_zPIYx\":[\"記錄資料集使用的比例。在與現代攝氏系列進行比較之前，歷史天氣記錄可能需要氣象站元資料甚至尺度重建。\"],\"a-49Cg\":[\"Stone\"],\"a0_sdV\":[\"Interstate rest stops every 50 miles are about 80.5 km apart. A 26.2-mile training long run is essentially a full marathon distance in kilometres (about 42.2 km).\"],\"a13Epg\":[[\"tFrom\"],\"是\",[\"tQuantity\"],\"的單位，用於測量和換算工作。\"],\"a3pVqb\":[\"常見問題\"],\"a9FhRh\":[\"面積和體積需要平方或立方長度因子。若 1 m = 100 cm，則 1 m2 = 10 000 cm2，1 m3 = 1 000 000 cm3。忘記對係數進行平方或立方是工程作業和 DIY 材料估算中最常見的轉換錯誤之一。\"],\"a9gM7C\":[\"Align chart distance units with speed units before ETA math. Verify tablet app unit settings before navigation practice.\"],\"a9tQsz\":[\"Convert the full value you know. If you know stone and pounds, combine them (or convert via kilograms) so leftover pounds are not dropped. Forms that want kg should receive a single kilogram number.\"],\"aCRZNA\":[\"瀏覽該類別中的所有單位\"],\"aDMgNB\":[\"Decide the authoritative measurement (what the scale showed) and its unit. Convert to the destination unit with an exact factor. Round once for display according to the context—whole pounds for casual speech, one decimal for luggage, more for lab work.\"],\"aFqNBm\":[\"轉換係數的平方和立方\"],\"aFynR0\":[\"單位為\",[\"0\"],\"。\"],\"aIolGk\":[\"一立方奈米 (nm³) 等於 10⁻²⁷ 立方公尺。它描述了奈米科學中的分子尺度體積。\"],\"aM9XSi\":[\"A 10-foot shipping container width constraint is 3.048 m—container specs are often written both ways. A 6 ft person is 1.83 m, the figure hospitals and passport forms outside the US usually expect.\"],\"aNO7cW\":[\"宇宙學中存在不同的距離度量（同移距離、光度距離、角直徑距離）。從紅移到光年的隨意轉換器嵌入了宇宙學模型假設。將流行的單數轉換視為深空天體的近似值。\"],\"aNhKFf\":[\"A microsecond (µs) equals one millionth of a second (10⁻⁶ s). High-speed electronics and scientific instrumentation resolve events in microseconds.\"],\"aOCjZ7\":[\"When you redesign packaging, re-measure and re-convert. A 2 cm reduction on one side changes volume by a percent equal to that side’s relative change—worth calculating before you order 10,000 cartons.\"],\"aOkLxr\":[\"發布數據時，請註明每個表格和繪圖軸中的比例。如果雙刻度軸都是根據一個主資料集計算的，那麼雙刻度軸非常適合公共通訊。\"],\"aQtyFH\":[\"接受條款\"],\"aR_j-p\":[\"我應該輸入以米為單位的高度還是以厘米為單位的高度？\"],\"aSlQH1\":[\"Carriers care about two constraints: how heavy a parcel is, and how much space it occupies on a truck or aircraft. Actual (scale) weight is what a calibrated scale reads in kilograms or pounds. Dimensional weight—also called volumetric weight—is a billing weight computed from the package’s outer dimensions using the carrier’s divisor formula.\"],\"aVVsip\":[\"選擇系統並安全轉換\"],\"aVyHck\":[\"平方公分\"],\"aakJC9\":[\"一公頃是邊長 100 m 的正方形，很容易在公制地圖上可視化。一國際英畝等於 4 046.856 422 4 平方米，透過國際碼和英尺定義。對於大多數改造工作，這個確切的定義取代了舊的區域面積。當歷史文獻中提到的英畝沒有幾何形狀時，請將行銷四捨五入視為近似值，直到調查確認它們為止。\"],\"abg1wm\":[\"Carry-on limits are often lower and sometimes stated only in kilograms. Soft bags compress; hard cases do not. Weigh the packed bag, not the empty shell plus a guess. If you own a scale in pounds only, convert the limit first, write both numbers on a sticky note in the bag, and re-check after last-minute additions (duty-free bottles are a classic overage).\"],\"acQncn\":[\"所有 \",[\"tQuantity\"],\" 單位\"],\"adCNaD\":[\"Mile per hour\"],\"agaux1\":[\"對於定義的比例因子，物理關係是精確的。可以改變的是您顯示的位數。 Units Converters保持內部運算精確；僅對您需要的輸出進行一次舍入。\"],\"airbJ5\":[\"將精確的法律因子儲存為小數或有理數，而不是倉促鍵入的二進制浮點數。以盡可能少的步驟轉換輸入 → 基礎 → 輸出。僅在針對人類進行格式化時進行舍入，並記錄舍入模式。\"],\"ajla6x\":[\"在現代攝氏溫標中，0°C 是水的冰點，100°C 是標準大氣壓力下的沸點——這是有用的錨點，儘管精確計量學現在透過絕對熱力學方法和純物質的固定點來定義尺度。\"],\"alomXo\":[\"Rough intuition: more miles per gallon means fewer litres per 100 km. Exact conversion needs both the mile–kilometre factor and the gallon–litre factor for the correct gallon. Do not invert the number alone (mpg → 1/mpg) and call it L/100 km.\"],\"azzH-3\":[\"您唯一需要的單位轉換器\"],\"b1htTh\":[\"<0>行動裝置友善：</0>針對在任何裝置上使用進行了最佳化。\"],\"b1vl0n\":[\"平方英吋\"],\"b3gZE4\":[\"Why did 10 on the treadmill feel impossibly fast?\"],\"b6nemW\":[\"定點數學將所有內容縮放到最小刻度的整數計數（奈米、微升或千分之一英吋）。整數運算在溢位之前都是精確的。它適用於具有明確測量量的領域。\"],\"b75dby\":[\"我可以像溫度讀數一樣轉換溫度變化嗎？\"],\"b7JOy7\":[\"英尋\"],\"b7j6GI\":[\"Units Converters\"],\"b8oEnC\":[\"You almost always pay on the greater of actual weight and dimensional weight. A box of pillows can be light on the scale and expensive on the invoice because volume weight wins. A small dense part can be heavy and tiny—actual weight wins. Unit conversion mistakes on either side change which number wins.\"],\"b8qt5E\":[\"溫標簡史\"],\"bA8xzL\":[\"Ounce (Avoirdupois)\"],\"bBc2Im\":[\"光年是時間單位嗎？\"],\"bC8VeG\":[\"挑選長度、面積、體積和溫度單位的實用決策指南，使數字可讀、符合標準且不易誤解。\"],\"bEttEG\":[\"Foot per second\"],\"bEu4-i\":[\"提示：為了烘焙準確性，盡可能以克為單位稱量原料，而不是轉換杯子體積。對於水池和水箱，在轉換為公升之前先確認幾何形狀。\"],\"bJliMa\":[\"Why do pilots and sailors prefer knots?\"],\"bQ1on8\":[\"在專案註釋中記錄因素來源（國際英畝、當地法規）。將來你將不記得你輸入了哪個常數。如果客戶提供了舊測量英尺制度中的英畝數，請在任何人根據軟轉換的公頃數設計圍欄之前在同一張註釋中標記這一點。\"],\"bQPqVr\":[\"If your warehouse stores dimensions in millimetres and the carrier wants centimetres, divide each side by 10 before multiplying—or convert after computing mm³ into cm³ carefully. Keep a single spreadsheet column unit and validate with a known sample box.\"],\"bU8uH1\":[\"不直接。公升測量體積。您需要深度或厚度才能將面積轉換為體積，然後將立方公尺轉換為公升 (1 m3 = 1 000 L)。\"],\"bZOK_f\":[\"圓銑刀\"],\"b_5xND\":[\"皮升\"],\"baKgzz\":[\"您的權利\"],\"bb1zDx\":[\"How many km/h is one knot?\"],\"beqMSh\":[\"Dividing by 1.5 is a rough estimate. River currents quoted in ft/s can look slow in mph—0–5 mph still matters for boats. Chronograph “fps” for airsoft vs firearms differ in magnitude; convert the number you actually measured.\"],\"bhMg6o\":[\"英制和美國習慣單位如何運作\"],\"bkkcq9\":[\"換算面積時，將長度係數平方。轉換體積時，將其立方。 1 m = 100 cm 表示 1 m2 = 10 000 cm2，1 m3 = 1 000 000 cm3。在此範例中，將線性因子應用於面積值會欠轉換 ×100。\"],\"blMdOu\":[\"對於運動員和兒童，請定期重新測量，而不是永遠轉換舊值。即使單位系統保持不變，生長和姿勢也會改變真實長度。\"],\"bnEMkn\":[\"轉換器 UI 應分隔數量標籤：長度、面積、體積、溫度。跨數量轉換選項會導致無意義的結果。如果您建置工具，請停用不可能的對。\"],\"bnSOB9\":[\"ISO-8601 durations (PT1H30M) encode units explicitly. When APIs return raw seconds, document that contract. Silent disagreement between “seconds since start” and “minutes since start” is a frequent integration bug.\"],\"bpWxqN\":[\"Dashcams and OBD apps may log SI units internally and display your preference. When exporting a CSV for insurance or coaching, note the unit column. A silent m/s vs km/h swap makes you look ten times too slow or too fast.\"],\"brSuoe\":[\"英畝\"],\"bsT5BU\":[\"科學長度單位：Ångström、奈米、微米等\"],\"bxtojs\":[\"為什麼廚房的體積感覺不一致\"],\"byMUK0\":[\"How is m/s related to km/h?\"],\"c1xWvb\":[\"雙邊公差和單位變化\"],\"c4_Sw-\":[\"暴露單一杯子單元的轉換器應記錄他們實施的杯子。用戶值得這個腳註。如果您發布配方軟體，請在內部以毫升為單位存儲體積並本地化顯示單位 - 不要存儲不明確的杯子計數，就好像它們是通用常量一樣。\"],\"c9aRYL\":[\"Weather, tires, and “feels like” speed\"],\"cAqE9n\":[\"這取決於哪個杯子。現代美國常見的營養標示法定杯子為 240 毫升。公制杯通常為 250 毫升。檢查配方的來源，當準確性很重要時，更喜歡毫升測量。\"],\"cBtQp6\":[\"When in doubt, store seconds as integers (or milliseconds as integers) and format for humans at the edge. Integer bases avoid decimal-hour ambiguity entirely.\"],\"cGKcEV\":[\"連鎖轉換會加劇麻煩。每一步都帶有二進制浮點數的英里→碼→英尺→英寸→毫米→米比具有高精度係數的單英里→米轉換要差。每跳都會重新捨入中間值。\"],\"cI0Ewh\":[\"一微米 (μm) 或微米等於 10⁻⁶ 公尺。生物家用它來測量細胞大小；工程師用它來實現精細的製造公差。\"],\"cI6T12\":[\"數量不同，尺寸不同\"],\"cJ39x1\":[\"Measuring the box before you convert\"],\"cJ6qxU\":[\"Helicopter and ultralight communities sometimes speak mph in certain countries. Check the unit column on every performance table—especially when PDFs were scanned from mixed sources.\"],\"cKU2eT\":[\"華氏度將水的冰點設定為 32 °F，將水的沸點設定為 212 °F，因此這些點與攝氏 100 度之間存在 180 華氏度。 180/100 的比率恰好是 9/5，它出現在每個轉換公式中。\"],\"cMpQRw\":[\"Convert millilitres (named Millimetre in this volume set) to litres for medicine cups, cocktail jiggers, and lab aliquots when labels use mL but dosing math wants litres. Divide millilitres by 1,000. Pharmacies and home brewing share this scale jump.\"],\"cMqnGa\":[\"An avoirdupois pound (lb) equals exactly 0.45359237 kilograms. It is the primary customary mass unit in the United States for body weight and commerce.\"],\"cNSioH\":[\"Flour’s bulk density is not water’s, and it changes with packing. Weigh flour in grams instead of trusting a water-based volume bridge.\"],\"cRdYDc\":[[\"0\"],\"面板\"],\"cSrZwS\":[\"停止將平方米與立方米混合。了解面積和體積之間的尺寸差異以及因混淆它們而產生的轉換錯誤。\"],\"cWk5T0\":[\"Two numbers decide the invoice\"],\"cdkPWA\":[\"If mass is in kilograms, volume should be in cubic metres for SI density (kg/m³), or you may use g and cm³ (numerically equal to kg/L for the same substance). Mixing lb with litres without converting produces a density nobody else can use.\"],\"cg88uL\":[\"溫標描述了物體的熱度或冷度。攝氏溫度和華氏溫度主導著日常生活；開爾文是SI科學標度。使用精確的公式（而不是浮點快捷方式）在它們之間進行轉換，並閱讀每對頁面上的常見問題解答。\"],\"cgJ3FK\":[\"立方米\"],\"cl4XpH\":[\"安全的轉換習慣：盡可能透過SI基本單位進行轉換（米、立方米、平方米），使用精確的法定係數（每英寸25.4毫米），並且僅在末尾舍入以進行顯示。中間舍入是指小錯誤在經過幾個步驟後變得昂貴。\"],\"cvG2i2\":[\"了解 Units Converters 如何收集和使用數據，包括 cookie 和 Google AdSense 廣告。\"],\"cz1upw\":[\"一公頃約 2.471 英畝。一英畝約等於 0.4047 公頃。\"],\"czpqzK\":[\"形狀很重要：矩形、圓形和自由形狀的池需要不同的幾何估計。在您信任幾何體積之後（而不是之前）轉換單位。\"],\"d1Xi-y\":[\"我們不會出售您的個人資訊。我們根據適當的協議與幫助我們運行網站的服務提供者（託管、表單電子郵件傳送、分析以及 Google 等廣告合作夥伴）共享資料。如果法律要求，我們可能會揭露資訊。\"],\"d3ukLV\":[\"我們和我們的合作夥伴使用 cookie 來分析網站流量、個人化內容並提供相關廣告（例如 Google AdSense）。點擊“接受全部”，即表示您同意我們使用 cookie，詳情請參閱我們的<0>隱私權政策</0>。\"],\"d5rA60\":[\"US pounds-only world\"],\"d7-Br2\":[\"波耳半徑 (a₀) 是氫原子基態下原子核與電子之間最可能的距離，約 5.29 × 10-11 公尺。\"],\"dB4b_F\":[\"公升\"],\"dBf9Sn\":[\"Using 100 seconds per minute is a decimal-time fantasy, not civil time. Decimal minutes (1.5 min) are 90 s, not 1 min 5 s. Pace notation 4:30 per km is minutes:seconds, already partly in seconds—parse before converting whole minutes only.\"],\"dEnNWn\":[\"Pilots talk about indicated airspeed (IAS), calibrated airspeed (CAS), true airspeed (TAS), and ground speed (GS). Those labels describe corrections for instrument error, altitude, and wind. Unit conversion (knots vs km/h) is separate: convert only after you know which airspeed type you are quoting.\"],\"dI2cXa\":[\"單位轉換器、公制轉換、英製到公制、長度轉換器、溫度轉換器、面積轉換器、體積轉換器、科學計算器\"],\"dKXfGq\":[\"圓英吋是直徑為一英吋的圓的面積，約為 0.785 平方英吋。電線和管道尺寸歷來使用圓形測量。\"],\"dKdn_s\":[\"Convert days to Julian years when mission elapsed time, fossil age approximations, or simulation ticks in days should become year-scale figures using 365.25 d/yr. Divide days by 365.25. Astrophysics notebooks use this for tidy axes.\"],\"dLJTrx\":[\"Metres per second sometimes appear in research or metric-only instrument logs: 1 kn = 1.852 km/h = 0.514444… m/s. Prefer knots in operational marine/aviation communication unless a local procedure says otherwise.\"],\"dQPsJ-\":[\"國際團隊應在啟動文件中選擇專案單位系統。工程中期的改造費用昂貴。在該決策中包含韌體預設值、CAD 範本和供應商門戶，而不僅僅是報告文字。\"],\"dVSJWu\":[\"If a density table uses g/cm³ and your volume is litres, remember 1 g/cm³ = 1 kg/L numerically for the same density value—still convert volume carefully (1 L = 1,000 cm³).\"],\"dWSM6x\":[\"2 hours of battery life claimed is 7,200 seconds of runtime budget. A 0.25-hour quiz is 900 seconds on an auto-submit timer.\"],\"dZF4X_\":[\"Do not treat weight-on-Earth vs mass distinctions here unless you are in an engineering mechanics context. Kitchen and shipping “weight” numbers plug into the triangle as mass values for practical purposes.\"],\"dcK-nG\":[\"Using ÷2.54 on an area value is wrong—that is a length factor. Skin lesion charts sometimes mix mm² and cm²; convert to one unit before switching to in². Do not confuse cm² with cc (cm³) used for volume.\"],\"de1NrB\":[\"使用攝氏表示天氣、烹飪和大多數國際工程交流。在當地實踐和設備展示需要時使用華氏度。將開爾文用於科學方程式、低溫學以及任何絕對溫度重要的環境。\"],\"df6Djb\":[\"Convert Celsius to Kelvin for science, gas laws, and color-temperature adjacent physics where absolute temperature is required. Chemistry labs and meteorology (potential temperature) use Kelvin. Add 273.15; the degree size matches Celsius.\"],\"dhq85t\":[\"Related length conversion: 1 international nautical mile = 1.852 km ≈ 1.15078 statute miles. If you convert speed but not distance—or the reverse—you invent a fake average speed.\"],\"dqUoQp\":[\"相關 \",[\"tQuantity\"],\" 兌換\"],\"drESMY\":[\"單位換算指南\"],\"dv9Spr\":[\"泳池化學標籤假設您知道水量。如果您的註釋上寫的是加侖，但標籤上寫的是公升——或者您的製造商引用的是立方米——您必須在乘以每體積劑量之前進行轉換。\"],\"dyD1rw\":[\"Convert Julian years to days for astronomy, orbital periods, and light-travel teaching when a Julian year (exactly 365.25 days) is the definition in play. This matches the year length used in the light-year definition. Science writing prefers Julian years over vague “calendar years” for long spans.\"],\"e-mG_L\":[\"SI 前綴解釋：從 Nano 到 Giga 及以上\"],\"e3-eZf\":[\"Convert inches to centimetres when a US tape measure, pipe schedule, or monitor size must match metric drawings, European furniture specs, or metric drill bits. Builders working from mixed plans and anyone ordering parts across regions use this constantly. The international inch is locked at 25.4 mm, so the centimetre result is exact.\"],\"e6-eIU\":[\"加工：毫米或英寸，兩者都不具有權威性。民用土地：公頃或英畝加上佔地面積平方公尺。化學成分：公升和毫升，散裝罐的單位為立方公尺。天文物理學：AU、秒差距、光年，取決於尺度。每個領域都已經解決了可讀性問題——借用這些規範而不是發明一個私有系統。\"],\"e80Hl_\":[\"250 毫升的公制杯相當於四分之一公升。按照慣例烹飪算術，十六個美式湯匙相當於一個美式杯，但在轉換公製配方時要對照毫升進行驗證。如有疑問，請先將所有內容轉換為毫升，然後再轉換回您擁有的器具。\"],\"e8G42j\":[\"120 mL of oil is ½ US cup (240 mL cup). A 15 mL vanilla note is 1 tablespoon, not a full cup—sanity-check small millilitre amounts before calling them cups.\"],\"e9VwqZ\":[\"物料清單長度可能是公制的，而包裝體積是升的，運輸重量是公斤的——仍然保持每個數量的轉換隔離和標記。\"],\"eL51xG\":[\"確定數量。檢查法律和合約要求。選擇一個可讀的幅度單位。確認觀眾認識它。透過具有精確係數的基本單位進行轉換。循環顯示一次。標記每個數字。如果您無法明確地標記圖表軸，則單位選擇尚未完成。\"],\"eLY2Y5\":[\"Large industrial batches may use metric tonnes (1 t = 1,000 kg) and cubic metres. Convert tonne → kg if your density table is in kg/m³.\"],\"eOYIJH\":[\"Boating: SOG, STW, and wind\"],\"eRwJXO\":[\"為什麼要使用我們的轉換器？\"],\"eV62_R\":[[\"tQuantity\"],\" 轉換器中心 | Units Converters\"],\"eXoNed\":[\"一公升為 1 000 毫升，等於 1 000 立方公分。此標識將配方語言與實驗室語言連結：250 毫升的原料等於 250 立方公分。一立方公尺等於 1000 公升——適用於餐飲罐，不適用於蛋糕糊。\"],\"eZRsLU\":[\"測量一個簡單的矩形水池\"],\"eZxOi9\":[\"Metronomes, frame rates, and sample rates link time to counts (beats per minute, frames per second). Convert the time unit first, then compute rates. Swapping BPM math with raw seconds without conversion produces unusable tempos.\"],\"e__Puw\":[\"730.5 days is 2 Julian years. A 10,000-day time series spans about 27.38 Julian years—handy for long climate annotations.\"],\"ea8fHF\":[\"從正確的攝氏 ↔ 華氏度轉換開始，然後根據烤箱的行為進行調整。烤箱溫度計比網站上的第三位有效數字更有價值。\"],\"ebZquV\":[\"A gale at 20 m/s is 72 km/h. A sprinter near 10 m/s peaks around 36 km/h—useful when comparing to traffic speeds.\"],\"eh2HDo\":[\"Convert mph to km/h when US speed limits, bike computers, or sports radar guns must match metric signage and telemetry. Multiply mph by 1.609344. Touring cyclists and fleet managers localize reports this way.\"],\"ejVYRQ\":[\"從\"],\"ekpC3S\":[\"Trip math before economy math\"],\"emKkbf\":[\"Jet lag feelings track circadian clocks, not unit converters. Still, computing elapsed awake time uses duration units: hours since last sleep, minutes of layover.\"],\"enzGAL\":[\"Questions\"],\"eo96cV\":[\"10 stone is 63.5 kg. Someone at 13 st 7 lb is 13.5 stone ≈ 85.7 kg for a metric hospital chart.\"],\"euU_DG\":[\"由於光速在 SI 內是精確的，一旦年份約定確定，光年就會繼承與米的精確關係。轉換器應記錄他們使用的年份定義；儒略年是常見的天文選擇。\"],\"ezuV_5\":[\"Useful pairs to memorize for signs: 30 mph ≈ 48 km/h (urban); 50 mph ≈ 80 km/h; 60 mph ≈ 97 km/h; 70 mph ≈ 113 km/h; 80 mph ≈ 129 km/h. In the other direction: 50 km/h ≈ 31 mph; 80 km/h ≈ 50 mph; 100 km/h ≈ 62 mph; 120 km/h ≈ 75 mph; 130 km/h ≈ 81 mph.\"],\"ezxlLH\":[\"工程師應如何在不破壞公差的情況下轉換單位——有效數字、精確係數、疊加和保持零件配合的文檔習慣。\"],\"f0Z0HY\":[\"Convert mph to m/s for simulations, crash reconstruction inputs, and metric scientific models fed by US speed limits or radar guns. Divide mph by about 2.23694. Automotive research bridging NHTSA and SI tools needs this.\"],\"f0e0UX\":[\"提示：為了烘焙準確性，盡可能以克為單位稱量原料，而不是轉換杯子體積。\"],\"f25ZCJ\":[\"國際英尺正好等於 0.3048 公尺（12 英吋）。廣泛應用於建築、航空高度、美國日常測量等領域。\"],\"f7Spk7\":[\"Fossil and geological “millions of years” are long durations; the difference between Gregorian mean and Julian year is negligible next to dating uncertainty. Still, be consistent inside one paper or dataset.\"],\"fBIotp\":[\"Daylight saving shifts change civil labels by an hour on specific dates. The underlying duration of a movie does not become 59 minutes because DST started—though a civil midnight-to-midnight “day” can be 23 or 25 hours on transition dates.\"],\"fBeKh6\":[\"玻爾半徑和相關原子單位出現在量子化學中。與 SI 友善表中的實驗鍵長進行比較時，轉換為米或皮米。如果您需要精確的再現性，請記錄您的軟體包假定的 CODATA 或軟體預設玻爾半徑。\"],\"fCtyuo\":[\"一十公尺（水壩）等於 10 公尺。它是一個 SI 倍數，偶爾用於測量和田徑距離。\"],\"fD7PDR\":[\"溫度添加偏移量：攝氏度 ↔ 開爾文使用 273.15。此常數也是二進制浮點數的近似十進制值。仿射轉換特別敏感，因為添加不精確的偏移量會改變每個結果。\"],\"fOjnj0\":[\"Convert weeks to days for training plans, rental periods, and sprint schedules when coaches or leases say weeks but calendars show days. Multiply weeks by 7. Habit trackers and agile boards use this constantly.\"],\"fP8lzd\":[\"A 100 km/h highway limit is about 62 mph. A city 50 km/h zone is roughly 31 mph—close to many US 30 mph neighborhood limits.\"],\"fULs1C\":[\"健全性檢查的規範：一塊 0.2 英畝的郊區住宅地塊是數百平方米，而不是數百公頃。列出的國家公園面積為 2,000 公頃，相當於數十平方公里——如果您的電子表格顯示為 2,000 平方公里，那麼您的數字就減少​​了一百。\"],\"fZ8nJ9\":[\"A minute equals 60 seconds. Everyday schedules, cooking, and sports use minutes as a convenient subdivision of the hour.\"],\"fdBctX\":[\"實用清單\"],\"fdf92S\":[\"每次轉換都會透過使用Decimal.js算術精心定義的基本單位，因此作業、食譜、實驗筆記和工程估計保持穩定，而不是因二元浮點數學而漂移。選擇一個類別，選擇兩個單位，然後閱讀每頁的公式、表格和常見問題。\"],\"fizNPv\":[\"A reliable conversion workflow\"],\"fl0tsC\":[\"Mental anchors help day to day: 1 kg ≈ 2.2 lb; 5 kg ≈ 11 lb; 10 kg ≈ 22 lb; 20 kg ≈ 44 lb; 100 g ≈ 3.5 oz. Use anchors for sanity checks, then confirm important values with an exact conversion.\"],\"fpVPOq\":[\"一個杯子有多少毫升？\"],\"fpxm8o\":[\"英制加侖比美製加侖大多少？\"],\"fqw_2W\":[\"Rounding and reporting\"],\"frDzBE\":[\"一光日是光一天傳播的距離，大約26兆公尺。它連接著太陽系和附近的星際尺度。\"],\"g3AHNj\":[\"瀏覽化學、物理和材料科學中使用的埃姆、奈米、微米、皮米和相關科學長度單位。\"],\"g4ayGx\":[\"道路距離比物理更能說明民族習慣。大多數國家以公里為單位；美國發布里程。跑步和騎行訓練計劃通常將 5K（公製品牌）與英里配速混合在一起。在比較鍛鍊或 GPS 匯出時有意進行轉換。\"],\"g5VCEs\":[\"皮升 (pL) 等於 10⁻12 公升。微流體和噴墨列印可處理這種規模的體積。\"],\"g7fX22\":[\"您將遇到的土地面積單位\"],\"g7fndJ\":[\"Print or note dual totals for shared family recipes: “butter 113 g (4 oz).” Dual labels prevent weekend arguments and burnt cookies.\"],\"gBWzjf\":[\"Measure rooms, convert square metres and square feet, add waste, and order carpet or flooring without mixing length and area units.\"],\"gHnfdT\":[\"Water and many thin liquids have density near 1 g/mL, so millilitres and grams are roughly interchangeable for rough work. Oils, honey, and packed brown sugar are not. When accuracy matters, weigh.\"],\"gKEKVa\":[\"A 5-yard pass play covers 15 feet of field. Buying 4 yards of landscape fabric means 12 feet of linear run along a bed edge.\"],\"gQtgDe\":[\"熱門 \",[\"tQuantity\"],\" 換算\"],\"gSCAaI\":[\"查看全部指南\"],\"gdLQsW\":[\"Stone appears in UK everyday speech (for example, 11 st 4 lb). If a form wants kilograms, convert the full stone-and-pounds value to pounds first, then to kilograms—or use a stone↔kilogram converter and add the leftover pounds carefully. Never paste “11.4” into a kilogram field when you meant 11 stone 4 pounds.\"],\"ggFmaC\":[\"Example: 2.5 L of a liquid with density 0.92 kg/L → mass = 2.5 × 0.92 = 2.3 kg. Convert to pounds only after: ≈ 5.07 lb.\"],\"gh-m_2\":[\"Density links mass and volume: density = mass / volume, mass = density × volume, volume = mass / density. Unit converters do not invent density for you—they make the mass and volume numbers consistent so the triangle arithmetic works.\"],\"giAfa6\":[\"Groceries, parcels, and kitchen intuition\"],\"glPh7x\":[\"Should I bake in grams or ounces?\"],\"gmK2O-\":[\"如何將房間的平方公尺換算為平方英尺？\"],\"gq0a46\":[\"將光年與年混淆會導致錯誤的年齡與距離的心理模型。 1億光年外的星係不一定有1億年的歷史；我們看到的就是光線離開時的樣子，這是一個不同的說法。\"],\"gs16X8\":[\"用清晰的上標或純文本的 ASCII m^2 和 m^3 書寫 m² 和 m³。數字旁邊的 m 表示立方米，稍後會被誤讀。\"],\"gvQcOB\":[\"關於公制與英制、溫標、SI前綴、烹飪轉換等的原創詮釋。\"],\"gvz5ri\":[\"Example: 11 st 4 lb → (11 × 14) + 4 = 158 lb → about 71.67 kg. Round for the form’s rules (often whole kilograms in casual contexts, one decimal in clinics).\"],\"gw4hS2\":[\"攝氏度\"],\"gwLbLK\":[\"一立方分米 (dm³) 恰好等於一公升。當強調體積為長度的立方時，國際單位製文本通常更喜歡這個名稱。\"],\"h-EBW5\":[\"Is a Julian year the same as a leap year?\"],\"h0OSCv\":[\"Convert Celsius to Fahrenheit for cooking, weather apps, and HVAC setpoints when a recipe or forecast is metric but your oven or thermostat shows °F. Travelers and home bakers cross this daily. Use °F = °C × 9/5 + 32, not a simple scale factor.\"],\"h3fxEC\":[\"秒差距\"],\"h77AWn\":[\"兩個系統，一個物理世界\"],\"h8z3Rj\":[\"哈伯長度\"],\"hBe0Mj\":[\"無錯誤前綴轉換的習慣\"],\"hCu72k\":[\"此對使用相對於 \",[\"tQuantity\"],\" 基本單位的固定比例因子。計算器將這些因素與 Decimal.js 一起應用，因此鍊式轉換保持穩定。\"],\"hCvW19\":[\"國家盃的定義也不同。在現代營養標示背景下，美國常見的習慣杯為 240 毫升（歷史上通常將 8 盎司液體視為 236.588 毫升）。有些國家的公制杯為 250 毫升。使用錯誤的杯子會改變水合作用和質地。\"],\"hD0xms\":[\"音量比較混亂。美式盃、品脫和加侖與歷史上英國帝國單位不同。一美製液體加侖約為 3.785 L；一英制加侖約為 4.546 公升。食譜中只說杯子而未指定國家/地區，可以默默地改變麵糊的水合作用和蛋糕結構。\"],\"hGX3gp\":[\"這種取消就是量綱分析：以追蹤代數變數的方式追蹤單位。如果英吋沒有抵消，那麼這個因素就顛倒了。將轉換視為查找數字並希望錯過此檢查的學生 - 該檢查可以捕獲大多數家庭作業和電子表格錯誤。\"],\"hGctJQ\":[\"Create a line per room: raw L, raw W, unit, net area, waste %, order area, seller unit. Sum order areas. Compare to the installer’s takeoff. Differences larger than a few percent deserve a phone call before payment.\"],\"hKH6A_\":[\"Travel examples\"],\"hKSyqj\":[\"轉換係數是等於 1 的比率，它改變單位標籤而不改變物理量。書寫 1 in = 2.54 cm 表示分數 (2.54 cm)/(1 in) 等於 1。將測量值乘以該分數，英吋就會被抵消，剩下公分。\"],\"hKrxe3\":[\"我總是乘法，還是有時除法？\"],\"hLExwt\":[\"練習將相同的長度轉換為 nm、μm、mm 和 m，直到小數點移位感到無聊為止。無聊在這裡就是能力。\"],\"hMv49D\":[\"Convert mph to feet per second for ballistics, amusement-ride specs, and US engineering notes that keep length in feet. Multiply mph by 1.46667 (since 88 ft/s = 60 mph). Sports biomechanics in customary units use this.\"],\"hOIH5p\":[\"Convert hectares to acres when metric land registries, vineyard sizes, or park plans must be explained to an audience that uses acres. Multiply hectares by about 2.47105. Forestry and agronomy papers often need this for US readers.\"],\"hP8AC9\":[\"百升\"],\"hQbTDO\":[\"Rental cars may display the other unit, or both. Learn how to switch the cluster before you leave the airport road. Navigation apps usually localize speed limits, but a paper map or temporary work-zone sign might not match your mental default.\"],\"hRyrHm\":[\"Dividing by 2,000 gives short tons, not metric tonnes. Mixing net and gross pounds before converting still yields the wrong tonne figure for duties. Very small pound amounts become awkward tonne decimals—prefer kilograms under about 100 lb.\"],\"hTrZPu\":[\"Google AdSense and other advertising\"],\"hWhfUF\":[\"廢物因子應該在轉換之前還是之後添加？\"],\"hWwfWE\":[\"英畝和公頃測量土地面積。英畝英尺測量一英畝一英尺深的水量——灌溉和水庫單位。共享詞「acre」會欺騙新手，讓他們將它們視為可互換的。\"],\"hYTkFF\":[\"基本單位及其重要性\"],\"hZIEfv\":[\"是的——兩者都是面積單位。一平方公里等於 100 公頃，約 247.1 英畝。透過平方公尺或公頃換算可以使算術清晰。\"],\"hZeuel\":[\"Convert square metres to square feet for apartments, offices, and flooring quotes when the listing is metric but US buyers think in sq ft. Real-estate portals and rug shops use this constantly. Multiply m² by about 10.7639.\"],\"h_RCCg\":[\"不要在沒有明確切換數量的情況下將光年轉換為秒並稱之為時間。長度轉換器應將結果標記為距離。如果您需要光行時間，請在距離除以光速後以年、日或秒為單位明確說明時間。\"],\"hcPFJ8\":[\"A time zone changes how we label the same instant (“15:00 UTC” vs “11:00 EDT”). A duration unit measures how much time elapses between two instants (3 hours, 180 minutes). Converting 3 hours to minutes never requires a time zone. Scheduling a call across zones never changes how long 3 hours lasts.\"],\"hdfyXd\":[\"Convert using Year (Julian) ↔ Day when you need transparent second-based duration. Document the choice in your notebook: “years mean Julian years (365.25 d).”\"],\"hgiis4\":[\"值得記住的確切關係\"],\"hi0pyt\":[\"不同的結構具有不同的尺度。細胞可以以微米為單位討論，而膜、孔或波長可以以奈米為單位討論。它們之間以 1 000 為因數進行轉換。\"],\"hjFCpL\":[\"美國習慣的泳池計算器可能會輸出加侖。僅使用體積轉換器將加侖轉換為公升；不要將加侖視為公升。\"],\"hlNybv\":[\"平方米和平方英尺透過米英尺係數的平方相關。這就是為什麼同一房間的面積換算感覺比長度換算「更大」。\"],\"hn2nYh\":[\"Confusing mass with force in technical settings (lbf vs lb mass). Everyday baggage and body weight ignore that distinction; engineering specs may not. Read the symbol on the datasheet.\"],\"hpDhtW\":[\"面積與體積：常見錯誤以及如何避免它們\"],\"hr3apB\":[\"這個 \",[\"tFrom\"],\" 到 \",[\"tTo\"],\" 轉換器免費嗎？\"],\"hsK0za\":[\"A light-year is distance, not time—do not treat “4 years” as the converted value. Parsecs and astronomical units are different; convert ly→km, do not mix AU factors casually. Rounding to “9.5 trillion km” is fine for talk, not for precise ephemerides.\"],\"htIPPL\":[\"Adding leftover inches twice—once inside the feet field and again after converting—double-counts. Decimal feet (6.5 ft) become 78 inches, not 6 ft 5 in (which is 77 inches). Confirm whether the source already mixed feet and inches in one string.\"],\"htp0ic\":[\"織物和運動場歷史上都使用碼。依國際定義，一碼為 0.9144 m。當您使用國際單位時，這種精確性使得轉換值得信賴。\"],\"huPTBE\":[\"在攝氏度和華氏度之間轉換烤箱設置，了解風扇輔助調整，並保持食譜在各個地區的可靠性。\"],\"huSEaq\":[\"我什麼時候應該更喜歡 \",[\"tFrom\"],\" 而不是 \",[\"tTo\"],\"？\"],\"hv1-eY\":[\"Treating litres and m³ as interchangeable off-by-1000 errors. Rainfall in mm over an area yields litres or m³ only after multiplying by surface area—do not convert mm rain as if it were litres. Keep oil barrels and US gallons out of this SI-only path unless converted first.\"],\"hw26PX\":[\"美國將國際英尺與地理空間背景下的測量英尺區分開來。在大地塊上，每英尺的微小差異都是可以測量的。現代實踐正在向國際足部靠攏，但舊的平台可能嵌入了測量足部的幾何形狀。\"],\"hxO7c9\":[\"Our mile ↔ kilometre guides cover distance; this guide focuses on the speed pair. You will often need both pages open when building an itinerary across borders.\"],\"i0qMbr\":[\"首頁\"],\"i2oK0q\":[\"A 10 ha orchard is about 24.7 acres. A city park of 2.5 ha is roughly 6.2 acres—useful on bilingual trail signs.\"],\"i9kg_n\":[\"Last updated: 21 July 2026\"],\"iBcaae\":[\"Planning ETA when distance units also flip\"],\"iDGO1l\":[\"Disclaimer\"],\"iEnWPy\":[\"Kilograms and pounds both describe mass (weight under ordinary gravity). A suitcase that tips a scale at 23 kg is the same object whether a US tag says about 50.7 lb. The physics does not change; the number and the unit do. Confusion starts when people treat the numbers as interchangeable, round too early, or mix stone, pounds, and kilograms on one form.\"],\"iUyBUX\":[\"Dividing by 10 instead of 12 is a common mental slip. Leaving a remainder as a decimal foot (5.5 ft) is fine for calculation, but suppliers often want 5 ft 6 in—do not call 0.5 ft “5 inches.” Also, US survey feet differ slightly from the international foot; this converter uses the international definition.\"],\"iVMakV\":[\"以每加侖英里數為單位的燃油經濟性數字取決於您所指的加侖數。將美國 mpg 標籤與英國 mpg 數據進行比較（不換算加侖）會產生約 20% 的誤導。跨境比較時首選 L/100 公里，然後僅在本地講故事時轉換。\"],\"i_EFha\":[\"Spreadsheets store datetimes as serial numbers in a timezone-agnostic cell unless you add conventions. Duration cells formatted as time may wrap at 24 hours. Prefer an integer “total minutes” column for long spans.\"],\"icHr4X\":[\"Cubic metres appear in industrial fuel gas, not petrol stations (1 m³ = 1,000 L). Convert bulk deliveries carefully before computing fleet economy.\"],\"ii0wT3\":[\"How do I convert min/km to km/h?\"],\"im\":[\"im\"],\"imSxXi\":[\"最後，將紙上的真實實驗室值轉換為儀器顯示的單位。這種端到端的習慣正是專業工作所需要的。如果轉換後的值低於儀器的分辨率，請更改測量計劃 - 不要假裝轉換創建了可觀察性。\"],\"irbsSh\":[\"Confusing this volume unit with length millimetres will derail DIY projects—here “Millimetre” means millilitre (mL). Dropping or adding three zeros is the usual arithmetic bug. Do not equate mL with grams unless density is 1 g/mL (true for water near room temperature, not for syrups or oils).\"],\"itztKm\":[\"許多計算器使用二進制浮點數，無法準確表示每個小數。我們的轉換器使用任意精確度的小數，因此長轉換鏈保持穩定。微小的差異通常來自舍入顯示，而不是來自不同的物理因素。\"],\"j22KL0\":[\"因為公斤前綴將基礎長度乘以 1 000，而面積則乘以該因子的平方：1 000 × 1 000 = 1 000 000。面積和體積始終使用平方或立方前綴因子。\"],\"j4YCMy\":[\"食譜旅行；烤箱刻度盤不\"],\"j5HJId\":[\"糖果、肉類和探針溫度\"],\"j7LB4c\":[\"殘留烹調意味著食物在取出後溫度會升高。單位轉換不會改變物理原理；時間和休息仍然很重要。\"],\"j7Qadg\":[\"隱私權政策 | Units Converters\"],\"jCnKcR\":[\"我們的平台已完全翻譯為英語、西班牙語、葡萄牙語、法語、德語、日語、中文、繁體中文、韓語、俄語、義大利語、印尼語、阿拉伯語、波蘭語、荷蘭語、土耳其語和印地語，為全球用戶提供服務。\"],\"jD3OhI\":[\"They are not a substitute for certified metrology, calibrated instruments, or professional engineering sign-off. Always verify critical values against an authoritative standard for your industry before manufacturing, dosing, filing, or shipping decisions.\"],\"jDCGUq\":[\"平方分米\"],\"jFas-2\":[\"A 6 ft 1 in doorway rough opening is 185.4 cm—compare that to a 200 cm metric door slab with trim. A 5-foot Christmas tree is 152.4 cm for European height labels.\"],\"jFmHCW\":[\"安德斯·攝氏度提出了水的冰點和沸點之間的一百度範圍。現代方向（0 表示凍結，100 表示沸騰）成為日常的公制溫標。\"],\"jG0gYt\":[\"Some civil documents and metric-country outreach use km/h. Convert knots → km/h by multiplying by 1.852. Example: 90 kt ≈ 166.7 km/h. For mph, multiply knots by about 1.15078.\"],\"jIT08R\":[\"報告比儀器分辨率更精細的轉換值是虛假精度。轉換不應發明測量從未提供的數字。\"],\"jKwuBE\":[\"身高換算：英尺、英吋和厘米\"],\"jLnoAK\":[\"A 2 t palletized load is about 4,409 lb—check a forklift rated in pounds. A 0.5 t delivery is roughly 1,102 lb for a US pickup payload chart.\"],\"jMCjxK\":[\"遵循表格。如果兩者都允許，則整數公分通常比十進位米更不容易出錯。\"],\"jN574V\":[\"數量選項卡\"],\"jPGJ22\":[\"Confusing metric tonnes with US short tons (2,000 lb) or UK long tons (2,240 lb). A “ton” in casual US speech is usually the short ton, ~9% lighter than a tonne. Crane limits may be in tons-force—confirm mass vs force.\"],\"jQG1ak\":[\"我們可能會使用 PostHog 收集匿名或假名的使用分析（例如查看的頁面和基本設備資訊），以便我們改進 Units Converters。分析 cookie 和相關處理僅在您接受非必要 cookie 後執行。詳情請參閱我們的隱私權政策。您可以隨時透過頁腳中的 Cookie 設定拒絕 Cookie。\"],\"jRla6K\":[\"室內米和英尺\"],\"jXStA4\":[\"使用準確的定義：1 英吋 = 25.4 毫米。以完全精度進行轉換，然後舍入一次以進行繪圖。多步驟電子表格中的中間舍入是供應商之間神秘的 0.01 毫米分歧的常見根源。如果可能，將轉換儲存格鎖定為公式，而不是貼上的值。\"],\"jY7wnv\":[\"Convert feet to centimetres for height charts, ski length, and doorway clearances when the measurement started on a US tape in feet and inches. Medical growth charts outside the US and online clothing filters often want centimetres. Multiply feet by 30.48.\"],\"jYRIYX\":[\"當部件在單元變更後未通過檢查時，請在審核操作員之前審核轉換。許多逃避都是計量性的，而不是動機性的。每當圖面更改單位系統時，請在首件檢查時保留簡短的轉換驗證優惠券。\"],\"jbG0D6\":[\"Actual weight: kilograms and pounds\"],\"jbq7j2\":[\"拒絕\"],\"jcIkoh\":[\"為什麼來回轉換會改變我的號碼？\"],\"jcuMyh\":[\"One international avoirdupois pound equals exactly 0.45359237 kg by definition. That means 1 kg is about 2.2046226218 lb. For luggage and gym work, two or three decimal places on the conversion factor are enough; for legal trade and shipping manifests, use the exact factor and round only at the end.\"],\"jf9uJ_\":[\"我應該將英吋的毫米當量四捨五入到毫米嗎？\"],\"jfC_xh\":[\"接觸\"],\"jgY-wY\":[\"您所做的幾乎每次測量都描述相同的物理量（距離、容量或表面），但標籤因國家和行業而異。公制（SI 及其日常表親）以 10 的冪為單位建構單位。帝國和美國的習慣制度源自於貿易、手工藝和土地實踐，因此它們的比率是歷史的而不是小數的。\"],\"jkLcBQ\":[\"Partial fill-ups and forgotten top-ups ruin the dataset faster than unit mistakes. Start economy tests from full-to-full when you can.\"],\"jlWgCH\":[\"回覆聯繫和回饋訊息\"],\"jp75Pk\":[\"Average speed = distance / time. Convert distance and speed into one system before judging whether a tank was “mostly highway.” A 70 mph cruise is about 113 km/h—not a European “70” zone.\"],\"jqxx6s\":[\"一眼望去九個數量級\"],\"js24hj\":[\"以聲明的精確度進行比較，使用十進位字串相等，或斷言絕對和相對容差。避免在幾個算術步驟之後期望精確的二進制相等。\"],\"jt6Jb2\":[\"避免在沒有標籤的情況下將埃姆和奈米混合在同一列中。無聲的單位變化是繪圖錯誤的常見來源。\"],\"jtUEtX\":[\"日常長度：米、英尺和英里\"],\"jtoIN9\":[\"Year (Julian)\"],\"juCzXY\":[\"Convert avoirdupois ounces to grams for metric baking, lab sample limits, and nutrition labels when the US package speaks in ounces. Multiply oz by 28.349523125. Letter mail and spice jars often need grams for customs forms.\"],\"jwjswb\":[\"皮米和飛米出現在核和精密原子環境中。在它們之間進行選擇是為了可讀性和社區慣例，而不是不同的物理原則。\"],\"jzLhZN\":[\"Ångström\"],\"k03yoY\":[\"A number on a white sign means nothing until you know whether it is mph or km/h. Driving 100 in a 100 km/h zone is not the same as driving 100 in a 100 mph zone—the second case is roughly 161 km/h. Tourists who “just match the number” cause genuine danger.\"],\"k4oq1n\":[\"不。一英畝英尺是一個體積：覆蓋一英畝至一英尺深的水體積。英畝僅測量面積。\"],\"k521Wm\":[\"Applying only the Celsius↔Fahrenheit transform to a Kelvin number without the absolute offset fails. Absolute zero is 0 K (−459.67 °F), not −273 °F. Keep significant figures: converting 300 K to 80.33 °F is more honest than “80 °F” for lab work.\"],\"k6pR01\":[\"精確性、不確定性和誠實性\"],\"k9wF1o\":[\"Software and spreadsheet pitfalls\"],\"kGqN6S\":[\"在公里和英里之間轉換道路和步道距離，閱讀不同國家的地圖，並在沒有單位混亂的情況下確定旅行的節奏。\"],\"kK4fmb\":[\"Use square feet to square metres for EU building permits, metric tile boxes, and international property comparisons when the plan started in US customary units. Architects exporting CAD from imperial templates need m². Divide sq ft by 10.7639, or multiply by 0.092903.\"],\"kKLZaC\":[\"在轉換器中輸入一個值。我們透過\",[\"tQuantity\"],\"基本單位與Decimal.js算術轉換，然後將結果顯示在\",[\"tTo\"],\"中。\"],\"kKadcT\":[\"混凝土板需要體積，而不僅僅是建築面積。一塊 0.1 m 厚的 10 m² 板相當於 1 m³ 混凝土（扣除浪費因素）。因為地板面積為 10 平方米而訂購 10 立方米是一種昂貴的符號混淆。\"],\"kKqcNS\":[\"Density, Mass, and Volume: The Triangle\"],\"kLRjW4\":[\"Knot\"],\"kLY6ug\":[\"Common mistakes to avoid\"],\"kN2EC5\":[\"您可能乘以 0.3048 一次，而不是 0.3048 的平方（大約 0.0929）。面積換算必須乘以長度係數。\"],\"kNn4oH\":[\"變更轉換器中的輸入以檢查作業、食譜、工程估價或實驗筆記。結果會在您鍵入時更新，並保持完整的十進制精度，而不是二進制浮點漂移。\"],\"kS4T08\":[\"是的。一微米等於 1000 奈米。兩者分別等於 10⁻⁶ m 和 10⁻⁹ m × 1 000。\"],\"kVZkMb\":[\"埃姆有多少奈米？\"],\"kW9R7H\":[\"Idle time burns fuel with zero distance, wrecking L/100 km. Duration units (hours of idle) explain the hit; speed converters do not erase it.\"],\"kYatTD\":[\"規劃清單\"],\"kZNgFa\":[\"如何快速將\",[\"tFrom\"],\"轉換為\",[\"tTo\"],\"？\"],\"k_M3_l\":[\"Practical guidance\"],\"kaDoU6\":[\"Calling 25 mm “one inch” is off by 1.6%—enough to mis-drill a clearance hole. Do not mix calliper readings in mm with nominal inch pipe sizes (½″ pipe is not 12.7 mm inside diameter). Leading zeros on drawings (0.5 mm vs 0.5 in) are easy to swap when copying values.\"],\"kb02-X\":[\"Réaumur、Rankine、Delisle 和其他人也在檔案和專業工程領域留下了痕跡（Rankine 仍然以絕對華氏大小的比例出現在一些美國熱力學教學中）。\"],\"kcla1l\":[\"Convert km/h to mph for road speed limits, car dashboards, and running pace talk when traveling between metric and US/UK customary roads. Divide km/h by 1.609344. Rental cars and GPS unit settings drive this daily.\"],\"kf6wCX\":[\"Kilometre per hour\"],\"kh62N-\":[\"醫療和工業警報必須使用正確的刻度以及正確的差異與絕對讀數概念。恆溫器設定錯誤 5 °F 與 5 °C 的安全裕度截然不同。\"],\"kkV0vn\":[\"一平方奈米 (nm2) 等於 10⁻18 平方公尺。它測量奈米技術和材料科學中的超小表面積。\"],\"ku__5b\":[\"Second\"],\"kv_z5g\":[\"Converting Julian years to days and hours\"],\"kyFZfG\":[\"Browse related tools on Amazon\"],\"l-mD0s\":[\"We aim to reply within 2 business days.\"],\"l4SV8N\":[\"平方毫米\"],\"l8CY95\":[\"Convert metric tablespoons to teaspoons when scaling dressings, baking powder, and medicine-style kitchen doses. In the metric set used here, 1 tablespoon = 3 teaspoons (15 mL vs 5 mL). Recipe scaling and substitution both need this.\"],\"l8lOET\":[\"Avoirdupois ounces are the everyday food ounce: 1 oz = 28.349523125 g exactly by the international pound definition. Troy ounces are for precious metals—ignore them in the kitchen.\"],\"l9wI00\":[\"Speed\"],\"lEpJBm\":[\"Airspeed Units Explained\"],\"lGyviH\":[\"L/100 km ≈ (litres used × 100) / kilometres driven. km/L ≈ kilometres / litres. Those formulas only work after unit cleanup.\"],\"lHqUuu\":[\"Workflow for a border-crossing day\"],\"lN0rk8\":[\"澤米特\"],\"lO2fPP\":[\"Writing “mL” on a value still in litres by habit (1 L ≠ 1 mL). Baby formula and concentrate ratios break if you convert volume but keep the powder mass wrong. Carbonated beverage “litres” on bottles are liquid volume, not dissolved-gas volume.\"],\"lO46mR\":[\"A 42.195 km marathon is 26.219 miles—the classic race distance. A 120 km drive is about 74.6 miles; at 8 L/100 km that trip burns roughly the same fuel as about 29.4 mpg over those miles.\"],\"lOb2gC\":[\"單位換算的工作原理：因子、基礎和量綱分析\"],\"lPcBzK\":[\"有理算術將因子儲存為整數的分數。如果 1 英吋 = 127/5000 公尺（因為 25.4 毫米 = 127/5000 公尺），乘法可以完全抵消。有理數對於純尺度轉換來說是理想的；偏移仍然需要仔細處理溫度。\"],\"lQHX85\":[\"正好 1,000 公升。立方米和昇在日常公制體積中通過十的冪聯繫起來。\"],\"lR7zqG\":[\"在每個草圖尺寸上寫下單位。單純的「12 × 15」在邊界上是模糊的。首選“12 ft × 15 ft”或“3.66 m × 4.57 m”。\"],\"lS-JWL\":[\"找不到分類\"],\"lSDK4y\":[\"一光小時是光一小時傳播的距離，約10.79億公里。它的跨越距離與外行星軌道相當。\"],\"lSqMra\":[\"Convert litres to millilitres when a metric recipe, IV bag scale, or fuel additive dose starts in litres but syringes and measuring cups read mL. Multiply litres by 1,000. Clinical and culinary workflows both need this.\"],\"lXNujI\":[\"房間地板面積：平方公尺和平方英尺\"],\"lYWHq0\":[\"Units Converters is developed and maintained by <0>Voyager Tecnologias LTDA</0>, a Brazilian technology company. We are a small team passionate about building high-quality digital utilities that solve everyday problems with technical excellence.\"],\"lb2_mR\":[\"蜂蜜、糖漿和糖蜜都是黏稠的。它們緊貼在量杯上，因此重量或柔性矽膠杯可以提高準確性。在湯匙上輕輕塗油可以幫助黏性轉移，而不會改變體積。\"],\"lbPAS2\":[\"How do I convert room m² to ft² for carpet?\"],\"ldSUNW\":[\"英畝英尺是面積單位嗎\"],\"lft-xy\":[\"總部設在巴西\"],\"lmGjUl\":[\"Can I order carpet from length × width in mixed units?\"],\"lnd6lS\":[\"從頭開始重試\"],\"lqwHxU\":[\"運動場和球場都有標準化的尺寸——國際上通常以米為單位發布，即使球迷仍然以碼或英尺為單位。檢查管理機構的規則集以了解確切的數字。\"],\"lstGkS\":[\"Gregorian mean year vs Julian year\"],\"luqVOM\":[\"Stone Weight: UK Speech vs US Scales\"],\"lv-5mm\":[\"綜合類別\"],\"lzhCyk\":[\"No. Ground speed includes wind. You can convert either into km/h or mph, but they remain different physical quantities.\"],\"lzhjeI\":[\"在寫作中，介紹一個不熟悉的小單位，進行一次SI比較：80 nm（0.08 µm）孔徑。讀者比裸露的奈米數字更好地記住了這種比較。重複圖片標題中的比較，讀者在時間壓力下通常會先查看圖片標題。\"],\"m1gvGN\":[\"Use kilogram/gram and litre/cubic metre converters to sanitize inputs; look up density from a material datasheet, not from wishful arithmetic.\"],\"m7z962\":[\"經典的DIY和園藝錯誤\"],\"m9jwyN\":[\"清晰的公式、定點和實用建議，用於在攝氏度、華氏度和開爾文之間進行轉換，而無需混合偏移和比例因子。\"],\"mB2h1B\":[\"一吉米 (Gm) 等於十億公尺。天文學家有時會用它來測量太陽系內部的距離。\"],\"mB4cv6\":[\"To km/h: multiply knots by 1.852. To mph: multiply knots by 1.150779448 (approximately). Reverse: divide km/h by 1.852 to get knots. Use a converter when filing plans or writing procedures; use 1.85 as a glance factor only for casual talk.\"],\"mCPa7u\":[\"News may say “gusts of 80 mph” while METARs use knots. Re-convert from the authoritative METAR when briefing. Dual-unit sticky notes help in mixed classrooms.\"],\"mD6REY\":[\"請提供盡可能詳細的資訊...\"],\"mGW1fQ\":[\"立方毫米\"],\"mJN-IA\":[\"Before you convert anything, write down three facts: outer length, width, and height (with units), scale weight (with units), and the carrier’s dimensional divisor and rounding rules from the rate card you are using today—not a blog post from five years ago.\"],\"mM9lqj\":[\"Litres dominate most of the world. US pumps use US gallons (≈ 3.785 L). Confusing imperial gallons (≈ 4.546 L) with US gallons skews mpg badly.\"],\"mSSp5m\":[\"選擇任何單位以開啟轉換器。您可以在下一個畫面上變更目標單位。\"],\"mV4g_E\":[\"降雨量通常以集水區的深度（毫米）來討論。雨量等於面積×深度。洪水規劃依賴這種關係；單位換算只是水文學中的一個步驟。\"],\"mWuBvQ\":[\"開爾文很少出現在消費者食譜上，但出現在烹飪科學文本中。了解 1 °C 變化等於 1 K 變化有助於閱讀這些圖表。\"],\"maGuXr\":[\"Write units on the sketch: “3.20 m × 4.10 m” or “10 ft 6 in × 13 ft 5 in.” Bare numbers cause expensive callbacks.\"],\"maasmB\":[\"Treating metres and yards as equal is a ~9% error—enough to short a fabric order. Do not confuse square metres with square yards when buying sod or carpet; convert area separately. Survey “yards” in older deeds may not match the international yard.\"],\"mfGHa3\":[\"一十公升 (daL) 等於 10 公升。飲料和農業散裝液體有時會使用十公升。\"],\"mhNQVa\":[\"當二進制浮點仍然沒問題時\"],\"miLeGg\":[\"350 °F 轉換為約 177 °C，在家庭食譜中通常會四捨五入為 180 °C。確認您的烤箱和食譜風格。\"],\"mj_Y0E\":[\"An avoirdupois ounce (oz) equals exactly 0.028349523125 kilograms, or one-sixteenth of a pound. Food packaging and postal scales commonly use ounces.\"],\"mm6uBX\":[\"明智地使用轉換器\"],\"mmn5SI\":[\"Shipping Weight vs Volume Weight\"],\"mn1m80\":[\"比較光年、天文單位和秒差距\"],\"mnB7hj\":[\"日常技術工作中常見的前綴包括毫 (10⁻3)、厘 (10⁻2)、德西 (10⁻1)、德卡 (101)、百 (102) 和千 (103)。科學與工程添加了微米 (10⁻⁶)、奈米 (10⁻⁹)、皮 (10⁻12)、兆 (10⁶)、千兆 (10⁹) 等。\"],\"mnkrjr\":[\"約克托米特\"],\"mqI7zL\":[\"Almost never in everyday US forms or scales. Convert stone to pounds or kilograms when talking to US audiences or software.\"],\"mugzPe\":[\"將攝氏度乘以 1.8 而不加 32 將產生錯誤的華氏度讀數。添加 273 而不是 273.15 會引入 0.15 K 偏差——對於天氣影響可以忽略不計，對於仔細的實驗室工作來說是不可接受的。\"],\"mwQa3n\":[\"Units Converters\",[\"0\"]],\"mzr5MT\":[\"一公頃有多少英畝？\"],\"n0xVX9\":[\"在國際上共享高度時，更喜歡厘米加上可選的英尺和英寸光澤。雙重標籤可防止電子郵件和聊天中的無聲單位假設。\"],\"n4OVTp\":[\"開爾文是用度數符號寫的嗎？\"],\"n4_i-l\":[\"Are fluid ounces the same as ounces on a scale?\"],\"n5xKCi\":[\"Operational aviation prefers knots worldwide for airspeeds and winds. Popular articles may convert to mph or km/h for readers. Meteorology sometimes uses metres per second for wind. Know your audience before you change the number.\"],\"n6b2Ae\":[\"現代華氏度是透過精確轉換為攝氏度/開爾文來定義的，而不是透過華氏度最初的參考實驗來定義的——計量學繼續發展，但名稱保留了下來。當你今天轉換時，你使用的是現代定義，而不是重建十八世紀的鹽水實驗。\"],\"nA8gP-\":[\"平方微米\"],\"nAMgRH\":[\"One avoirdupois ounce is exactly 28.349523125 grams. For cooking estimates, many people use 28 g ≈ 1 oz.\"],\"nCUa6i\":[\"Conversion accuracy\"],\"nFYWRe\":[\"在製造中，混合圖紙是一種典型的故障模式：以毫米為單位設計的零件，以英寸為單位切割的夾具，以及悄悄超出預算的公差堆疊。為專案文件選擇一個系統並僅在邊界處進行轉換。\"],\"nH0ra2\":[\"Convert milligrams to grams for medicine, caffeine content, and analytical chemistry when labels use mg but balances or protocols use grams. Divide mg by 1,000. Pharmacy math depends on this shift.\"],\"nImEQv\":[\"Grain\"],\"nKTa7y\":[\"我們找不到那些特定的單位。嘗試我們的預設轉換器。\"],\"nO5M1g\":[\"Our platform is fully translated into English, Spanish, and Portuguese to serve users worldwide.\"],\"nS4cHi\":[\"習慣高度：英尺和英寸\"],\"nSyIq6\":[\"Workflow worth repeating\"],\"nTCHv2\":[\"Writing 90 minutes as 1.90 hours is wrong—90/60 = 1.5 h. Movie runtimes in minutes convert cleanly; including trailers is a content choice, not a unit issue. Keep overtime rules (e.g. round to next 15 min) separate from pure conversion.\"],\"nWNuiZ\":[\"公制高度：公分與米\"],\"nkGGs4\":[\"以公升或立方公尺為單位估算游泳池體積，在單位之間進行轉換，並根據與體積單位不一致的標籤來添加化學品。\"],\"nn2wRS\":[\"A millisecond (ms) equals one thousandth of a second. Computing latency, photography shutter speeds, and sports timing often use milliseconds.\"],\"nnO6cY\":[\"高精度轉換\"],\"nqMrU_\":[\"One kilogram equals about 2.2046226218 avoirdupois pounds. For quick estimates, use 2.2 lb per kg, then refine with an exact converter when limits are tight.\"],\"nr1Gem\":[\"By the Units Converters editorial team · \",[\"0\"]],\"nrZeXM\":[\"Medical and passport-adjacent forms\"],\"ntGXPK\":[\"提示：不要將地板平方米與油漆升數混淆－面積和體積是不同的數量類型。僅在單一系統中的長×寬後轉換面積。\"],\"nu-obh\":[\"Speed through water (STW) and speed over ground (SOG) can differ because of current. Instruments may show knots for both. When you convert to km/h for a guest display, label which speed you converted—current-adjusted SOG is what gets you to the marina on time.\"],\"nuviZq\":[\"我應該以同樣的方式轉換速度限制嗎？\"],\"nvyMN9\":[\"大麥粒是一種古老的英國長度單位，等於三分之一英吋。它在歷史上支撐了鞋子尺寸系統。\"],\"nwtY4N\":[\"出了點問題\"],\"nzwr2B\":[\"立方英尋\"],\"o-B_nB\":[\"Pages may show third-party advertisements (such as Google AdSense) or affiliate links after you consent to cookies where required. We do not control advertiser content. Affiliate relationships — if any — do not change our editorial duty to describe units and conversions accurately.\"],\"o-zndZ\":[\"Car stickers from different markets may already be converted—or may use different test cycles entirely. Unit conversion cannot fix a cycle mismatch (WLTP vs older cycles).\"],\"o0eWtS\":[\"Speed limits are unit limits\"],\"o3MK4I\":[\"Month (Average)\"],\"o8L3mE\":[\"對於公共通信，選擇一個前綴，使前導數字保持在大約 0.1 到 999 之間。說 0.003 公里是合法的，但不友善；說 0.003 公里是合法的，但不友善； 3m更清晰。\"],\"o9BMZQ\":[\"Tile and plank sold in boxes list coverage area per box. Divide required area (with waste) by coverage per box in the same unit, then round up whole boxes.\"],\"oDIaEX\":[\"Carat\"],\"oDacDe\":[\"0.25 g of caffeine powder is 250 mg—matching many anhydrous caffeine capsule labels. A 1.5 g electrolyte packet is 1,500 mg of total salts before splitting components.\"],\"oE-H8K\":[\"溫度\"],\"oGQWbj\":[\"Decimal hours vs hours and minutes\"],\"oGSy2V\":[\"Using ×2.2 is rough. Mixing m/s wind with mph storm reports without conversion makes Category talk inconsistent. Vertical speed in m/s (sink rate) is not the same conversation as horizontal mph.\"],\"oHNOBu\":[\"Convert nanometres to metres in optics, semiconductor process notes, and wavelength tables where light or film thickness is given in nm but equations expect metres (SI base). Physics homework and thin-film coating specs use this constantly. One nanometre is 10⁻⁹ m.\"],\"oIk5BZ\":[\"我應該以體積還是重量換算麵粉？\"],\"oLt41p\":[\"如果您只記得一個習慣，請記住這一點：使用完整的仿射公式轉換讀數；單獨使用比例因子轉換差異。在任何顯示與協議文件不同比例的實驗室烤箱或環境室附近列印該句子。\"],\"oM9mkO\":[\"For public schedules, whole minutes are usually enough. For lab notebooks, keep enough digits to match instrument resolution. Matching precision to purpose beats always showing six decimals.\"],\"oOMfxN\":[\"Flight-planning tools can switch display units. Before a cross-country lesson or sim session, verify the unit field. A silent switch from knots to mph changes every performance number you memorized.\"],\"oOvcbq\":[\"軟體、PLM 和雙重尺寸標註\"],\"oP7_xG\":[\"數量的平方和立方會使錯誤變得更嚴重。面積和體積會乘以長度比例，因此當您展開 (1+ε)ⁿ 時，長度上的微小相對誤差相對於面積或體積而言會變得大兩倍或三倍。\"],\"oPY_HN\":[\"平方米 (m²) 是 SI 導出的面積單位。全世界的財產清單、科學和工程都使用它作為基礎面積單位。\"],\"oTk8W2\":[\"Shipping and cooking crossovers\"],\"oV7zz2\":[\"秒差距和光年哪個較大？\"],\"oXH11m\":[\"Group classes calling “level 8.0” without units are ambiguous across equipment. Ask “km/h or mph?” once and save the workout.\"],\"oYbVXt\":[\"始終遵循產品標籤和當地法規。線上轉換器幫助單位；它們不能取代商業泳池的水質測試或專業建議。\"],\"o_CECW\":[\"一光年是光在真空中在儒略年中傳播的距離。儘管有“年”這個詞，但它是一個長度單位，而不是時間單位。說一顆恆星距離我們 4 光年意味著它的光大約需要四年才能到達我們——而路徑長度就是那麼多光年。\"],\"o_Q5cU\":[[\"tQuantity\"],\"轉換器\"],\"oaBQIn\":[\"比例模型會有所幫助：如果地球與太陽的距離為 1 厘米，那麼一光年就變成了一個尷尬的大教室長度——這本身就說明了為什麼天文學家需要大單位。\"],\"obIRob\":[\"When two people share numbers (coach and athlete, shipper and warehouse), agree on one unit for the shared log. Publish a dual label only at the interface (airport sign, product page), not inside every intermediate calculation.\"],\"ocU2yl\":[\"節省退貨的欄位提示\"],\"oe296U\":[\"Pilots quote indicated, calibrated, true, and ground speed—often in knots. Those types already differ by instrument and atmosphere effects; unit conversion is a separate step. Convert only when talking to audiences that expect km/h or mph, and name which airspeed type you mean.\"],\"oeEKDx\":[\"Use our second ↔ minute ↔ hour tools for clean steps, and keep a notepad line with units on every intermediate value when the calculation feeds payroll, dosing intervals, or race results.\"],\"oeiUr5\":[\"Tip: convert through kilograms when mixing metric and customary weight. Stone is 14 pounds—do not paste decimal stone into a kilogram form. Kitchen ounces are avoirdupois, not troy.\"],\"ofhKFN\":[\"Sanity-check with a dual display: show chargeable kilograms and pounds on the packing slip. Dual labels catch unit bugs when US and EU sites share one catalogue.\"],\"ofldSs\":[\"面積\"],\"ohh-Ad\":[\"SI 是正式的國際單位制。日常公制語言包括 SI 單位以及可與 SI 一起使用的方便單位，例如公升和公頃。對於技術工作，首選 SI 基本單位和派生單位，並明確說明任何非 SI 公制單位。\"],\"ojeWyk\":[\"An M6 bolt shank is 6 mm across, about 0.236 inches—too large for a ¼″ (0.250 in) clearance if you need a snug fit, but fine for a ¼″ clearance hole with a little play. A 35 mm camera lens is roughly 1.38 inches in focal length naming conversations.\"],\"omr0Cf\":[\"使用我們的高精度 \",[\"tQuantity\"],\" 轉換器輕鬆將 \",[\"tFrom\"],\" 轉換為 \",[\"tTo\"],\"。為學生和工程師提供的免費線上工具。\"],\"oms5-c\":[\"一平方英尺約等於 0.0929 平方公尺。美國的房地產、地板和建築通常使用平方英尺。\"],\"onzwZs\":[\"單元測試應明確包括面積和體積情況。僅靠線性測試無法發現缺失的功率。\"],\"oobEHZ\":[\"如果您跨境工作，或遵循來自不同國家的配方、建築計劃和產品規格，您需要流暢的轉換，而不是對某一系統的忠誠度。本指南的其餘部分展示了每個系統的優點以及可以防止代價高昂的錯誤的轉換習慣。\"],\"ovOn83\":[\"A brewery making 50 hL per batch produces 5,000 L—about 88 half-hectolitre kegs depending on keg size. A 2 hL fermenter is a 200 L vessel.\"],\"ozAMmJ\":[\"靶恩\"],\"p-HG8s\":[\"在平方公尺和平方英尺之間轉換房間面積，以正確的方式添加浪費係數，並避免經典的長度×寬度單位混淆。\"],\"p0HoY9\":[\"A 8.5-foot counter run is 102 inches for a continuous laminate order. Someone 5.75 feet tall is 69 inches on a medical form that only accepts inches.\"],\"p1Dbpo\":[\"30 mph is about 13.4 m/s for a urban crash energy sketch. A 100 mph pitch (extreme) would be ~44.7 m/s—far above normal baseball, showing why unit checks matter.\"],\"p2DkbT\":[\"Treating acres and hectares as equal roughly doubles or halves land area in conversation. Survey acres (especially older deeds) can differ slightly from the international acre—confirm the jurisdiction. Do not convert acre-feet (volume of irrigation water) with an area converter.\"],\"p4X7mC\":[\"People often round 2.54 cm to “2.5 cm per inch,” which drifts by about 1.6% and shows up on long measurements. Another trap is mixing display inches (TV diagonals) with ruler inches without checking which system the seller used. Do not confuse centimetres with millimetres: 25.4 mm is one inch, not 25.4 cm.\"],\"p5SI6W\":[\"Many international economy limits sit at 23 kg (often marketed as 50 lb). That marketing round is slightly generous: 23 × 2.2046226218 ≈ 50.71 lb. If your home scale only shows pounds, do not pack to a flat 50 lb and assume you are safe—you may already be over. Convert the airline’s kilogram limit into pounds with a proper converter, then leave a buffer for scale disagreement between home and the check-in desk.\"],\"p9xoMn\":[\"Units Converters 由 <0>Voyager Tecnologias LTDA</0> 經營，總部位於巴西。我們很樂意聽取您的意見。\"],\"pAQa1o\":[\"烤箱溫度不是體積，但它們隨著食譜的變化而變化\"],\"pDt01V\":[\"國際吋定義如今已經標準化；日常身高換算可以將國際吋視為精確值。儘管如此，還是要給單位貼上標籤，這樣軟體進口商就不會猜測。\"],\"pFzToT\":[\"當報價在“單位說明”之後跳轉時，詢問以 m² 和 ft² 為單位的面積。透明的雙重總計可以捕捉無聲的轉換錯誤。\"],\"pGgN6u\":[\"Incline changes effort at the same belt speed. Converting km/h to mph does not adjust for grade. Keep incline notes beside speed/pace notes.\"],\"pH23TV\":[\"Multiplying by 2.5 instead of 2.54 understates every length. Surveyors and woodworkers also confuse decimal inches (3.25 in) with fractional inches (3¼ in) before converting—convert the decimal first. Screen “inches” are diagonal; do not treat them as width when comparing to a centimetre shelf opening.\"],\"pI6CGe\":[\"A 2,500 m² community garden is 0.25 ha. A 40,000 m² warehouse yard is 4 ha—handy for logistics land-use filings.\"],\"pInhXT\":[\"Runners quote pace as time per distance—minutes per kilometre or minutes per mile. Treadmills usually show speed in km/h or mph. They describe the same motion differently: pace = time / distance; speed = distance / time. Converting requires reciprocals, not a single multiply of the displayed number.\"],\"pLB71t\":[\"將高度視為長度轉換問題，具有明確的目標格式。確定目的地是否需要單一公制值（公分或公尺）或雙慣用值對（英尺 + 吋）。轉換一次，然後格式化以供顯示。\"],\"pYNZJY\":[\"毫米\"],\"pa79C2\":[\"連結轉換而不丟失情節\"],\"paJWEM\":[\"Cookie 和類似技術\"],\"paWTJa\":[\"Using the statute-mile factor 1.609 instead of 1.852 understates maritime speed. Airspeed indicated in knots is not ground speed—wind correction is separate. Do not treat knot as a land mph synonym.\"],\"pa__Bp\":[\"一平方微米 (μm²) 等於 10^2 平方公尺。顯微鏡和微加工經常報告該單元中的區域。\"],\"pe2SHa\":[\"在常見的科學和工程用法中，是的：微米是微米 (10⁻⁶ m) 的非正式語言。在正式写作中更喜欢使用微米。\"],\"pe9kiJ\":[\"瀏覽所有\",[\"tQuantity\"],\"單位\"],\"peYsNy\":[\"廢棄物因素和包裝\"],\"pgqDUB\":[\"For privacy requests, conversion feedback, or partnership inquiries, email is the fastest channel. Include the page URL and locale if you are reporting a content issue.\"],\"phsQ55\":[\"未找到您要尋找的頁面，建議您返回首頁。\"],\"pkDS7o\":[\"氣炸鍋和烤箱具有不同的熱質。將他們的圖表視為單獨的；當食譜只列出一種比例時，仍然要小心地轉換單位。\"],\"plPmpw\":[\"Treating 1.5 hours as 1 hour 50 minutes (decimal 0.5 ≠ 50). Flight “hours” in block time still convert with 60; time-zone offsets are a separate problem. Do not mix sexagesimal HMS strings without parsing each field.\"],\"pq--_D\":[\"Climb and descent rates use feet per minute—a vertical speed unit, not a horizontal airspeed unit. Do not convert fpm with knot converters.\"],\"ps03Ku\":[\"Tip: 1.30 hours is not 1 hour 30 minutes. Convert mixed h:mm:ss through total seconds, then format once. Julian years (365.25 days) are not calendar birthday years.\"],\"ps35j8\":[\"首先轉換列印的溫度，然後套用烤箱建議的風扇減少量。轉換和風扇調整是單獨的步驟。\"],\"ps9xJC\":[\"Practical rule of thumb\"],\"psJP6O\":[\"一公制湯匙等於 15 毫升。烹飪說明將其用於介質液體和調味品的測量。\"],\"puCv9T\":[\"90 km/h traffic is 25 m/s—handy for estimating stopping-distance thought experiments. A 18 km/h bike speed is 5 m/s.\"],\"q0xzNh\":[\"A 180 lb adult is about 81.6 kg on a metric chart. A 40 lb bag of dog food is roughly 18.1 kg for shelves labeled only in kilograms.\"],\"q1FqwM\":[\"輕旅行單位和天文單位位於日常前綴之外，但仍轉換為公尺。前綴流暢度可協助您合理檢查以公里為單位的結果是否意外地以公尺為單位。\"],\"q4hj75\":[\"Is ground speed the same as airspeed?\"],\"q4rV31\":[\"Software libraries sometimes offer Julian century (36,525 days) for older astronomical formulas. That is 100 Julian years. Convert through days if your tool only exposes years and days.\"],\"q5GJGY\":[\"免費轉換器免責聲明\"],\"q5OjzF\":[\"將公里/小時與英里/小時混淆是一個安全問題，而不僅僅是一個數學問題。轉換距離時，也要檢查速度限制是否已轉換。\"],\"q7xpqy\":[\"文化和基礎設施慣性。一些國家的天氣服務、恆溫器和公眾期望仍然以華氏度為基礎。科學和大多數國家使用攝氏或開爾文。\"],\"qAprmL\":[\"SI 前綴附加到單位名稱上以乘以或除以 10 的冪。一公里是10立方公尺；一毫米等於 10⁻³ 公尺；一奈米等於 10⁻⁹ 公尺。學習前綴表後就可以解鎖長度、質量和許多派生單位。\"],\"qIwLar\":[\"一公尺 (Ym) 等於 10²⁴ 公尺。它是最大的命名 SI 長度倍數之一。\"],\"qJb6G2\":[\"再試一次\"],\"qOTu7A\":[\"Knots Explained for Boats and Planes\"],\"qOfG9B\":[\"花園土壤、油漆和混凝土以體積或覆蓋面積出售。將平方公尺的牆壁與公升的油漆混淆，或將英畝的田地與立方公尺的覆蓋物混淆，是面積與體積的錯誤，而不是公制與英制的錯誤。在轉換單位之前，請先明確數量類型。\"],\"q_108C\":[\"A 500 mg pain tablet is 0.5 g of drug substance labeled strength. Caffeine at 80 mg in espresso is 0.08 g—useful when a lab protocol wants grams.\"],\"qgGxSI\":[\"英畝可以直接換算成平方公里嗎？\"],\"qh4Woa\":[\"Convert cups to millilitres when baking and cooking across US/metric recipes. Cup sizes vary by country; this tool’s Cup unit maps to its configured cup definition—check which cup your recipe assumes (US legal cup is 240 mL; many metric recipes use 250 mL).\"],\"qm_29X\":[\"A 3-day courier promise is 72 hours if counted continuously. A 10-day medication course is 240 hours of coverage at face value.\"],\"qmv6Mo\":[\"Fuel economy answers “how much fuel per distance” (L/100 km) or “how much distance per fuel” (mpg). Those are inverse styles: lower L/100 km is better; higher mpg is better. You cannot convert them by treating the number like a simple length.\"],\"qrq8Wr\":[\"一公頃有多少平方公尺？\"],\"qsYV2G\":[\"電纜長度（國際）\"],\"qt41aL\":[\"這場歷史競爭解釋了為什麼轉換器仍然列出大多數人日常從未使用過的尺度：它們是科學文獻記錄的一部分，偶爾出現在較舊的文本中。當您知道檔案中的陌生比例通常只是到開爾文的另一個仿射映射時，您就不會那麼害怕了。\"],\"qwFZi1\":[\"Convert grams to avoirdupois ounces for coffee beans, mailers, and recipe scaling when kitchen scales show grams but US packaging lists ounces. One ounce is exactly 28.349523125 g. Portion control and postage brackets use this scale.\"],\"qzgYgD\":[\"最近的恆星例子（比鄰星，大約 4.25 光年）為米和公里轉換練習提供了很好的解決問題。請學生使用科學記數法計算相同的距離（以 AU 為單位）和以公尺為單位（以公尺為單位），然後解釋為什麼這兩個答案都描述了一個物理距離。\"],\"r-bKrE\":[\"名稱相同，卷數不同\"],\"r38boF\":[\"Convert British stone and pounds to kilograms and pounds, read UK body-weight phrases correctly, and avoid decimal-stone mistakes on forms.\"],\"r52K3T\":[\"Multiplying by 2 and adding 30 is a rough estimate only—off by several degrees for candy and meat temps. Forgetting the +32 offset after scaling is the most common algebra slip. Do not treat a 10 °C change as a 10 °F change; the degree sizes differ.\"],\"r8tcPz\":[\"品脫遵循加侖數：在兩個系統中，八品脫對應一加侖，因此品脫的比例相同。旅行時點一品脫啤酒可以比教科書更快地教授計量知識。無論廚師是否注意到，酒吧玻璃器皿法規和標籤法都對這些差異進行了編碼。\"],\"rAEfTa\":[\"Affiliate disclosure: see our <0>Disclaimer</0>.\"],\"rBSwgf\":[\"如果罐頭配方來自另一個國家，請仔細轉換體積，並更喜歡在罐子系統中測試的更新配方——食品安全不僅僅取決於單位數學。\"],\"rBqDvA\":[\"Measure twice. Wall-to-wall carpet needs the clear floor span, not the exterior building footprint. Baseboards and undercut doors affect fitting but not the geometric area you start from.\"],\"rC2nQD\":[\"Converting only the whole feet and dropping leftover inches loses several centimetres. “Five foot two” must include the two inches (157.5 cm total), not 5 × 30.48 alone. Flooring sold per square foot still needs linear cm for cut lengths—do not mix area and length units.\"],\"rE-5lQ\":[\"服裝和身體尺寸在國際上通常使用厘米，在美國通常使用英寸。圖案起草可以將兩者結合起來；仔細轉換縫份，以便輕鬆計算保持一致。\"],\"rFVEj-\":[\"Convert metric tonnes to avoirdupois pounds for freight, scrap metal, and agricultural loads when SI shipping weight must meet US scale tickets. One tonne is 1,000 kg ≈ 2,204.62 lb. Logistics brokers quote both constantly.\"],\"rG5Q9u\":[\"Liquid nitrogen’s boiling point near 77 K is about −196 °C. A sensor rated to 233 K survives down to −40 °C, a common automotive electronics floor.\"],\"rIwk73\":[\"Common highway anchors\"],\"rMpfsQ\":[\"開爾文將絕對零錨定在 0 K。水的三相點和其他定義的固定點將開爾文與實驗室實踐聯繫起來。科學家們更喜歡用開爾文來表示狀態方程式、低溫學和色溫，因為比率和絕對值表現得很乾淨。\"],\"rMtVac\":[\"US recipes may list 8 oz of chocolate or 1 lb of butter. Remember 16 oz = 1 lb. Convert pounds to grams via ounces or use a kilogram ↔ pound converter for large amounts: 1 lb ≈ 453.592 g.\"],\"rRKjY3\":[\"Exactly 3,600 seconds: 60 seconds per minute times 60 minutes per hour.\"],\"r_FQ7i\":[\"Is a knot the same as a mph?\"],\"r_p7hp\":[\"A 2×4 stud is nominally 1.5 inches thick, which is 3.81 cm—useful when a metric drywall screw pack lists max material thickness in centimetres. A 55-inch TV diagonal is 139.7 cm for checking elevator and doorway clearance.\"],\"rbD1fJ\":[\"Measure outer L, W, H in one unit. Weigh on a trusted scale. Convert weight into the carrier’s billing unit. Compute dimensional weight with the correct divisor. Take the maximum. Add any oversize fees that ignore weight entirely.\"],\"rcBXzk\":[\"Units Converters |精密轉換工具\"],\"rf4up8\":[\"標籤、符號和 ​​UI 陷阱\"],\"rjRk1f\":[\"Elapsed duration is not a clock time\"],\"rlJbvb\":[\"光秒\"],\"rm9u3o\":[\"一英畝英尺是指覆蓋一英畝、深度一英尺的體積，約 1,233 立方公尺。水資源管理將其用於水庫。\"],\"roUnmF\":[\"Incline, effort, and why units still matter\"],\"rrEWCV\":[\"70 mph on an interstate is about 113 km/h. A 6 mph walking pace is roughly 9.7 km/h for metric fitness watches.\"],\"rtSw51\":[\"英制體積：美國與英國測量值\"],\"ruvZmH\":[\"Convert miles per hour and kilometres per hour for foreign road signs, rental cars, and trip planning—plus the distance and time links that keep ETA math honest.\"],\"rxHnrf\":[\"將 \",[\"fromLabel\"],\" 轉換為 \",[\"toLabel\"]],\"ryPNqA\":[\"平方公里適合地區和公園；公頃適合農場和森林；英畝適合美國地塊；平方公尺適合建築佔地面積和小地塊。選擇使數字可讀以供當前決策使用的單位，然後進行轉換以進行比較，而不是相反。\"],\"rzZZTA\":[\"Those printed times are local. Zones and date changes hide the true duration. Use the airline’s block time or convert both instants to UTC before subtracting.\"],\"rzcesg\":[\"Adaptive cruise control and speed-limit assist features depend on map data units. If the car was configured for another market, verify the shown limit against roadside signs once, especially after firmware or language changes.\"],\"s-lIOg\":[\"確切因素和有效數字\"],\"s4NIvn\":[\"Use our knot ↔ km/h and knot ↔ mph pages for exact tables, and the nautical mile ↔ kilometre page when converting chart distances for mixed crews.\"],\"s73T7S\":[\"在軟體和電子表格中，將列命名為 us_cup_mL 或 Imperial_pint_mL，而不是 cup 或 pint。不明確的列標題是等待發生的資料錯誤。\"],\"sAPueQ\":[\"分米\"],\"sBVCFu\":[\"許多計算器使用二進制浮點數。我們的轉換器使用任意精確度的小數，因此長轉換鏈保持穩定。\"],\"sBywU8\":[\"對於普通通信，首選將值保持在 0.1 到 999 之間的單位。優選 12.5 km 而非 12 500 m 的道路距離；對於房間長度，首選 12.5 m 而非 0.0125 km。可讀的幅度是錯誤預防的一部分。\"],\"sDgNP3\":[\"對於溫差，偏移會取消。升高 10 °C 意味著升高 10 K 和升高 18 °F。人們經常混淆轉換讀數和轉換變化——室溫 20 °C 是 68 °F，但升高 20 °C 是 36 °F，而不是 68 °F。\"],\"sFhneI\":[\"常見轉換\"],\"sO4Syn\":[\"How many pounds are in a stone?\"],\"sOZcYX\":[\"ångström (Å) 等於 10⁻10 米，或 0.1 奈米。它廣泛用於光譜學和晶體學中來表達原子尺度的長度。\"],\"sSrFJe\":[\"秒差距 (pc) 大約等於 3.26 光年。天文學家更喜歡它，因為它與恆星視差測量直接相關。\"],\"sThfcP\":[\"Exact kitchen factor: grams = ounces × 28.349523125. Ounces = grams ÷ 28.349523125. For mental checks, 30 g ≈ 1 oz is rough; 28 g ≈ 1 oz is better.\"],\"sW71Vp\":[\"符號μ（mu）表示微（10-6）。當用作前綴時，符號 m 表示毫 (10^3)​​。它們相差一千倍。\"],\"s_fkOd\":[\"早期的測溫儀顯示空氣或液體受熱膨脹，但缺乏共享的數字刻度。如果城市之間沒有達成一致的固定點，閱讀就無法透過信件或科學論文傳播。再現性（而非便利性）推動儀器製造商走向共享參考點。\"],\"s_fxqz\":[\"70 kg is about 11 stone 0 lb (11.02 st). A fighter listed at 12 stone is 76.2 kg—useful when comparing to metric weight classes.\"],\"sev0AD\":[\"Time duration units run from seconds and minutes to hours, days, weeks, and Julian years. Use them for elapsed spans—not time-zone clock labels—and avoid decimal-hour mix-ups with hours-and-minutes notation.\"],\"sfgH-a\":[\"一國際海浬剛好等於 1,852 公尺。航空和海上導航使用它是因為它與地球緯度密切相關。\"],\"sj_xiq\":[\"Airline baggage is kilograms or pounds—not stone. Never put stone on a shipping label.\"],\"sjd0YY\":[\"Adding 273.15 directly to Fahrenheit skips the scale change and produces nonsense. Rankine (°R) is the Fahrenheit-sized absolute scale; do not label Rankine values as Kelvin. Oven setpoints in °F are not absolute temperatures for gas-law homework.\"],\"skqyeX\":[\"Integer weeks that discard remainder days hide partial weeks (10 days ≠ 1 week). ISO week numbers are a calendar system, not a pure duration conversion. Inclusive counting (“Monday to Friday”) can add an extra day if mishandled.\"],\"sltboY\":[\"A 4,400 lb machine is about 2.00 t for a metric bill of lading. A 500 lb crate is roughly 0.227 t (227 kg)—often better written in kilograms on the same form.\"],\"smJqvk\":[\"Imported goods may show only metric net weight. US cooks can convert g → oz for intuition, but baking is usually easier if you stay in grams once you own a metric scale.\"],\"snhup9\":[\"For passage planning: distance in nautical miles ÷ speed in knots = hours. That simple formula is why the unit exists. Change either unit without the other and the formula collapses.\"],\"sqjdpH\":[\"mph, km/h, and metres per second\"],\"sr0UJD\":[\"返回\"],\"sseGJ5\":[\"專案中期的混合系統是常見的錯誤來源。在清晰的邊界處轉換一次，在每個數字上標記單位，並儘可能將其餘工作流程保留在單一系統中。\"],\"t-na-z\":[\"在計算的每一行寫上單位。前綴錯誤隱藏在裸露的數字中。當前綴被視為單位標記的一部分時，維度分析仍然有效。\"],\"t1XjtI\":[\"您需要三個長度測量（或等效的幾何形狀）來獲得體積，然後將該體積轉換為化學圖表的單位。\"],\"t8dlih\":[\"Trip time is distance divided by average speed—only when both use consistent length units. Mixing a 120 km leg with a 60 mph average without converting yields nonsense. Convert either all distances to miles and speeds to mph, or all to kilometres and km/h.\"],\"tC-cop\":[\"Foot per second appears in some US engineering contexts. For road trips you rarely need it; stick to mph and km/h unless a technical report forces the issue.\"],\"tCSlOi\":[\"Convert hours to minutes for parking tickets, roasting schedules, and billing increments when the quote is in hours but the clock works in minutes. Multiply hours by 60. Salons, ovens, and consultants use this constantly.\"],\"tG0Mm1\":[\"一微升 (µL) 等於百萬分之一公升。生物學和化學中的移液器通常分配微升體積。\"],\"tGMZ40\":[\"Can a day have other than 24 hours?\"],\"tMpml2\":[\"為什麼我的計算器可能略有不同？\"],\"tPrmjP\":[\"Address:\"],\"tT9-B4\":[\"液體油、水、牛奶和湯料可以按體積乾淨地轉換，因為它們可以填滿杯子而不會產生空隙。乾粉則不然。這就是麵包烘焙師靠重量生存的原因。\"],\"tXV7b7\":[\"體積常被低估，或加侖被視為公升。重新計算體積，仔細轉換單位，重新測試水。\"],\"tYuwiV\":[\"Convert metres to yards for American football field talk, fabric bolts, and gardening beds when the plan is metric but the store sells by the yard. Landscapers and sports fans cross this pair often. One metre is about 1.09361 international yards.\"],\"ta6_8E\":[\"旅行距離：公里和英里\"],\"tgGVmf\":[\"No warranty\"],\"tgMdom\":[\"Volumetric litres and cubic metres help warehouse planning (1 m³ = 1,000 L) but do not replace the carrier’s dimensional-weight formula. Use volume converters for storage and cube utilization; use the tariff formula for billing weight.\"],\"thkrj0\":[\"不規則房間：分成長方形，計算每個面積，然後求和。將總和轉換一次。每個矩形的零散圓角可能會讓你很短。\"],\"tmtrBa\":[\"Does the US use stone for body weight?\"],\"tnBPYh\":[\"使用者回饋和行為\"],\"tnIuqS\":[\"在為公眾寫作時，請將光年與米或公里的科學記數法值配對一次，以便讀者可以交叉檢查星等。\"],\"trBkWx\":[\"有關本服務條款的問題可寄至 <0>Voyager Tecnologias LTDA</0>，網址為 <1>voyagertecnologias@gmail.com</1>。\"],\"ttaqO2\":[\"為什麼科學需要微小的長度單位\"],\"tthY0q\":[\"在縮放之前以原始產量測試關鍵配方。轉換誤差和縮放誤差在塌陷的蛋糕中看起來是一樣的——受控測試將它們分開。保留烘焙研發的換算日誌：原始單位、假設的杯子標準、毫升值以及麵粉和糖的稱重確認。\"],\"tweYUH\":[\"Time Zones vs Duration Units\"],\"ty85rR\":[\"在上面的轉換器中輸入一個值。我們透過\",[\"tQuantity\"],\"基本單位與Decimal.js算術轉換，然後將結果顯示在\",[\"tTo\"],\"中。作為參考，1 \",[\"0\"],\" = \",[\"oneToOne\"],\" \",[\"1\"],\"。\"],\"tzmAt_\":[\"開爾文出現在物理、化學、天文學和照明領域。接近 2.7 K 的深空背景、接近 77 K 的液態氮以及數千開爾文的煉鋼溫度在沒有負值的情況下更容易推理。\"],\"u0I2ka\":[\"From m/s and race mathematics\"],\"u47PU6\":[\"Convert Kelvin to Fahrenheit for US engineering reviews when research papers quote absolute temperature but shop-floor instruments read °F. Aerospace and HVAC commissioning sometimes need this bridge. Use °F = K × 9/5 − 459.67.\"],\"uCFNKs\":[\"Everyday liquids often quote g/mL or kg/L. Water is about 1 g/mL near room temperature—handy, not magical. Oils and syrups differ; always use the density for the material and temperature you care about.\"],\"uCPKzy\":[\"對於統計製程控制，在資料庫中保留一種內部單位系統並僅在表示邊界處進行轉換。反覆轉換儲存的歷史記錄會降低資料品質並使跨工廠的能力研究變得複雜。\"],\"uD7uRR\":[\"只有在按照配方制定的情況下，少量的泡打粉、酵母和鹽通常按勺量使用更安全，或者在嚴格烘焙時按 0.1 克刻度使用克數。微小的絕對誤差是一茶匙內的大相對誤差。\"],\"uLuey4\":[\"光年\"],\"uMnipN\":[\"儀器和分辨率\"],\"uOlg5g\":[\"我們收集的資訊\"],\"uR6kEy\":[\"如果問題陳述混合了覆蓋範圍、深度和容量，請畫一個小圖表。一旦幾何圖形可見，許多作業和現場錯誤就會消失。\"],\"uUs1L4\":[\"Use millimetres to inches for precision hardware: bolt diameters, PCB hole spacing, camera sensor sizes, and machining tolerances. Engineering drawings in ISO countries list mm; US tooling and drill charts are often in inches. At this scale, the exact 25.4 mm per inch factor matters more than casual rounding.\"],\"u_xCOm\":[\"我應該轉換我看到的每個測量值嗎？\"],\"ubpaES\":[\"攝氏到開爾文：K = °C + 273.15。開爾文到攝氏：°C = K − 273.15。華氏度到開爾文的兩步轉換是最安全的：華氏度 → 攝氏度 → 開爾文，除非您仔細應用組合公式。\"],\"ueo-Bi\":[\"身高看起來很簡單，直到表格要求填寫英尺和英寸，而護照上列出的是厘米。人們很早就四捨五入，忘記了剩餘的英寸，或者將小數英尺值貼到英寸字段中。這些錯誤會出現在服裝訂單、醫療圖表和運動資格檢查中。\"],\"ufpUZ8\":[\"正確的單位是您的受眾已經使用的單位，以及您的監管機構、期刊或客戶合約所要求的單位。工作現場沒有人可以讀取的完美 SI 選擇仍然會導致錯誤。對於人類來說清晰性和對於審計員來說合規性都算是正確性。\"],\"uktD0z\":[\"Convert cubic metres to litres for bottled-water equivalents, fish stocking guides, and pump capacity when the engineering drawing uses m³. Multiply m³ by 1,000. Municipal water reports often flip between these for public communication.\"],\"ulGYbo\":[\"在法律允許的最大範圍內，Voyager Tecnologias LTDA 及其業者不對因您使用（或無法使用）Units Converters（包括依賴任何轉換結果）而導致的任何間接、偶然、特殊、後果性或懲罰性損害，或任何資料、利潤或業務損失承擔責任。\"],\"upcWll\":[\"從納米到米：了解尺度\"],\"upoTTm\":[\"阿托米特\"],\"urDKtY\":[\"科學轉換的最佳實踐\"],\"urQMcz\":[\"Convert km/h to knots when metric weather apps must match nautical instruments, sailing polars, or aviation METAR-style expectations. Divide km/h by 1.852. Harbor masters and student pilots do this when switching unit systems.\"],\"usyz3l\":[\"一光年有多少公里？\"],\"ut90L2\":[\"一吋有多少毫米？\"],\"utb5FI\":[\"Should I convert days using 24 hours?\"],\"uugzJT\":[\"化學和晶體學中的 ångström\"],\"uvlVzR\":[\"Worked patterns\"],\"uyJsf6\":[\"關於\"],\"uz_-15\":[\"此處，公制杯的標準化容量為 250 毫升。烹飪食譜使用杯子來盛裝日常液體和乾燥物品。\"],\"v1Qdq2\":[\"如果您接受 cookie，我們可能會使用 PostHog 來了解人們如何使用 Units Converters（例如，哪些頁面受歡迎）。當您拒絕 cookie 時，分析功能將會停用。\"],\"v7Ohh6\":[\"Convert feet to inches when cut lists, sewing patterns, or height forms ask for a single inch total instead of feet-and-inches. Cabinetry screws, pipe runs, and printer paper clearance checks often need one number. Multiply feet by 12.\"],\"v7dGUo\":[\"茶匙（公制）\"],\"vCZf8l\":[\"Kilogram\"],\"vFTcJf\":[\"契約列出的英畝數可能精確到小數點後兩位，而底層的邊界幾何形狀則更精確或更精確。轉換不能增加調查從未測量過的準確性。\"],\"vG79Hs\":[\"Plans written in min/km need min/mile for US races (or the reverse). Convert distance first (1 mile = 1.609344 km), then scale the pace time: min/mile ≈ min/km × 1.609344. Example: 5:00 /km ≈ 8:03 /mile.\"],\"vIvqTY\":[\"分區文檔有時會在部分之間切換單位。為項目建立一頁單位鍵，並將每個引用的數字轉換為單一工作單位。\"],\"vK3Q2x\":[\"一厘升 (cL) 等於 10 毫升。歐洲的飲料包裝通常以厘升為單位標註體積。\"],\"vKE6JE\":[\"指定為 10.00 ± 0.02 mm 的軸與在電話轉換後四捨五入到小數點後三位後隨意寫入 0.394 不同。軟轉換可以在機器啟動之前吃掉公差預算。廢料箱裡裝滿了隨意改裝的零件，而不是加工不良的零件。\"],\"vLc8Kh\":[\"Dividing by 1,000 gives cubic metres, not hectolitres (though 1 m³ = 10 hL). Small-batch homebrew in litres rarely needs hL—avoid forcing tiny numbers like 0.02 hL unless the form requires it. Keep temperature correction for beer volume separate from unit conversion.\"],\"vLwhXs\":[\"When scientists choose Julian years\"],\"vODdcK\":[\"一光秒是光在真空中一秒傳播的距離，正好是 299,792,458 公尺。它有助於表達近地空間距離。\"],\"vOpNzS\":[\"Understand the knot as a speed unit tied to the nautical mile, convert knots to km/h and mph, and avoid mixing statute miles with nautical miles in navigation.\"],\"vPUFsW\":[\"在軟體中，精確因子應盡可能儲存為精確小數或有理數。 0.001 或 25.4 的二進位浮點近似值可能會產生微小的殘差，當您來回轉換時，這些殘差看起來就像錯誤。\"],\"vQEfYA\":[\"Multiply metres per second by 3.6 to get kilometres per hour. Divide km/h by 3.6 to get m/s.\"],\"vTmcmH\":[\"牛頓\"],\"vUGw3w\":[\"A day equals 86,400 seconds (24 hours). Calendars and daily planning treat the mean solar day as the basic civil time unit.\"],\"vUy5Bv\":[\"公差無法在不小心的轉換中倖存\"],\"vYtgK3\":[\"一立方米有多少公升？\"],\"vZhDqN\":[\"玻爾\"],\"veYKqf\":[\"確定權威單位。謹慎選擇硬轉換或軟轉換。使用精確的因素。轉換擬合極限。繞一圈。記錄政策。透過進行/不進行的心理評估進行驗證。\"],\"vln3eu\":[\"國際英哩正好等於 1,609.344 公尺。它仍然是美國和英國的主要長途公路單位。\"],\"vn2owh\":[\"Unit conversion does not change stopping distance physics, but mixed mental models do. If you are used to thinking “60 mph needs X metres to stop,” rebuild that intuition in km/h before mountain descents abroad.\"],\"vvA23-\":[\"麵粉、可可、磨碎的起司和切碎的堅果因包裝的不同而有很大差異。權重可以消除這種差異。如果食譜僅列出杯子，請尋找該成分的可靠重量換算，並注意麵粉是用湯匙還是舀的。\"],\"vvWnbl\":[\"The light-year as a length unit is defined using the Julian year: distance light travels in vacuum in one Julian year. That is why astronomy documentation is careful about which year it means.\"],\"vvfhCy\":[\"一平方公里 (km²) 等於一百萬平方公尺。地圖和地理將其用於城市、地區和國家。\"],\"w4Xr1y\":[\"Right-sizing the carton often saves more money than negotiating a tiny rate discount. Empty space increases dimensional weight. Lightweight void fill can still lose if the box stays huge. Dense goods in a snug carton usually bill near actual weight.\"],\"w6E5Q_\":[\"對長度、體積和麵積的公制和英制單位進行實用比較——每種系統何時獲勝以及如何自信地在它們之間進行轉換。\"],\"w6xq3D\":[\"90 minutes of parking is 1.5 hours on a meter that bills hourly. A 105-minute feature film is 1.75 hours.\"],\"w8aQU6\":[\"主要在美國使用的溫標。\"],\"w9dmsB\":[\"英制長度使用英吋、英尺、碼和英里，具有固定但非小數的比率：12 英吋等於英尺，3 英尺等於一碼，1760 碼等於一英里。國際定義現在將英寸固定為 25.4 毫米，因此一旦您使用國際英尺和英里（而不是舊的測量定義），則轉換為米是準確的。\"],\"wB0ke9\":[\"Units Converters作為便利工具免費提供。轉換結果僅用於一般資訊和教育目的。它們<0>不是</0>旨在用於危及生命、醫療、安全、法律、財務或其他高風險決策。始終使用適當的專業標準或校準儀器驗證關鍵測量結果。\"],\"wLoW7s\":[\"有關隱私的問題嗎？發送電子郵件至<0>voyagertecnologias@gmail.com</0>或造訪我們的<1>聯絡</1>頁面。另請參閱我們的<2>服務條款</2>。\"],\"wM9pzC\":[\"平方英尺到平方米和立方英尺到立方米是常見的電子表格錯誤。有人將 0.3048 儲存為名為 FT_TO_M 的常數，並將面積乘以它一次。正確的面積係數是 0.3048²。\"],\"wMgXFc\":[\"1 m² ≈ 10.7639 ft². 1 ft² ≈ 0.092903 m². Those factors are squares of the metre–foot length relationship. That is why a “10% longer room” is not a “10% larger carpet order” when you also change width.\"],\"wNAEQM\":[\"拉姆達 (λ) 是實驗室體積單位，等於一微升 (10⁻⁶ L)。較早的生物化學文獻仍然使用該名稱。\"],\"wNXXnX\":[\"強調該單位回答的是多遠，而不是持續多久。打個比方：三個小時的車程透過旅行約定描述了一段距離；這並不意味著目的地已經過了三個小時。\"],\"wSn4cc\":[\"Method A: convert stone to pounds (× 14), add leftover pounds, convert total pounds to kilograms. Method B: convert stone to kilograms (× 6.35029318) and convert leftover pounds to kilograms (× 0.45359237), then add. Both match if you use exact factors.\"],\"wULskt\":[\"Convert avoirdupois pounds to metric tonnes for export documents, port tariffs, and metric axle-load rules when the weighbridge ticket is in pounds. Divide lb by about 2,204.62. Containerized cargo filings often need tonnes.\"],\"wV4T5U\":[\"A 2.25-hour seminar is 135 minutes. Slow-cooking for 8 hours is 480 minutes on a device that only accepts minutes.\"],\"wW5k8c\":[\"為什麼我的 ft² 到 m² 轉換看起來太小？\"],\"wZ0a6O\":[\"標準度之前\"],\"w_tlhZ\":[\"Identify the airspeed type (IAS/TAS/GS) and the unit. Convert the unit only. Keep type labels attached (“TAS 140 kt ≈ 259 km/h”).\"],\"wgavnZ\":[\"Example: 500 g of material at 0.8 g/mL → volume = 500 / 0.8 = 625 mL. Convert to litres (0.625 L) if the tank chart uses litres.\"],\"wgbExZ\":[\"在前缀之间移动就是移动小数点。 3.5 km = 3 500 m = 3 500 000 mm。透過明確寫出冪：3.5 × 10³ m，避免將思維轉變與計算器拼字錯誤混為一談。\"],\"whKQ_H\":[\"一英制加侖約為 4.546 L，而美製液體加侖約為 3.785 L，約 20%。務必檢查人物使用的加侖數。\"],\"whSPb4\":[\"攝氏度和華氏度包含相對於絕對零度的偏移量，因此映射的形式為 y = ax + b，而不是單獨的 y = ax。開爾文是絕對標度，比較絕對溫度時會依比例因子轉換。\"],\"wiFqA4\":[\"Volume for shipping math is usually the rectangular product L × W × H, not the true geometric volume of an irregular shape. Carriers bill the rectangular cuboid. Convert that cuboid into the unit the divisor expects (often cm³ or in³), then apply the formula.\"],\"wmk4lB\":[\"Precision in sport and lab timing\"],\"wzAFc1\":[\"Nanosecond\"],\"wzLsq4\":[\"相關單位包括光秒、光分、光時和光日——對於太陽系尺度和通訊延遲討論很有用。\"],\"wzqqS-\":[\"主要特點\"],\"x0uKJ1\":[\"Cooking syrups: converting a recipe from “grams of honey” to tablespoons requires density (or a tested volumetric equivalent). Guessing from water’s density over-pours honey.\"],\"x0y4It\":[\"在您同意的情況下顯示相關廣告\"],\"x8zdoX\":[\"閱讀Units Converters的服務條款，包括使用免責聲明、智慧財產權、第三方廣告和責任限制。\"],\"x9_MIj\":[\"International carriers usually quote chargeable weight in kilograms. US domestic services often speak in pounds. Convert scale readings with the exact pound–kilogram relationship before comparing to dimensional weight. Comparing 10 lb to a dimensional weight of 5 kg without converting is meaningless.\"],\"xBU15m\":[\"立方公分\"],\"xCd3hA\":[\"Dividing cm by 30 instead of 30.48 adds a small but visible error on height (about 0.5 cm at 180 cm). People also convert cm→inches then forget to divide by 12 for feet. Do not treat “foot” as the anatomical foot length; use the unit definition.\"],\"xJEke2\":[\"<0>體積：</0>升、立方英吋、加侖和毫升。\"],\"xKeMa0\":[\"為什麼兩個供應商在小數點後第四位上有分歧？\"],\"xLoJAO\":[\"一毫升 (mL) 等於一立方公分。醫學、烹飪和實驗室工作使用毫升來精確測量液體體積。\"],\"xM1_13\":[\"Separate clock labels (time zones, DST) from duration units (seconds, hours, days) so meeting math and layover math stop disagreeing.\"],\"xOeXJw\":[\"A knot is a nautical mile per hour\"],\"xQB4Q9\":[\"Charts and distances are often in nautical miles. Using knots keeps speed and distance in the same mile definition, so time = distance ÷ speed stays simple.\"],\"xRJBlt\":[\"Microsecond\"],\"xSy0fo\":[\"Halving the pound value (“close enough to kg”) is ~10% low. Baby weight in pounds and ounces needs ounces converted (16 oz = 1 lb) before switching to kg. Do not use troy or tower pounds here.\"],\"xUi_8z\":[\"國際電纜長度等於 185.2 公尺（十分之一海浬）。海軍歷史上將其用於短途海上航行。\"],\"xXK4Es\":[\"未找到指南 | Units Converters\"],\"xfkVOo\":[\"Entering “11.6 stone” when someone meant 11 st 6 lb (11 stone + 6/14 ≈ 11.43 st) misstates mass. Livestock “stone” traditions vary historically—stick to the 14 lb stone for people. Do not mix stone with hundredweight without knowing long vs short hundredweight.\"],\"xgbMzR\":[\"Cubic metres give kg/m³. For liquids, kg/L is common and equals g/mL numerically for the same density value.\"],\"xicKBk\":[\"Should I convert to kilograms or pounds first?\"],\"xj4SWA\":[\"與任何幫助維護池的人共享資料卡。雙裝置可防止週末客人閱讀外國標籤時服用過量。\"],\"xjhtsV\":[\"鏈\"],\"xkuIjN\":[\"A microgram (µg) equals one billionth of a kilogram (10⁻⁹ kg). Trace nutrients, pollutants, and sensitive analytical chemistry use micrograms.\"],\"xlbRot\":[\"烤箱各不相同。架子位置、盤顏色和校準誤差與單元標籤一樣重要。使用烤箱溫度計。\"],\"xn4DRx\":[\"為什麼美國的杯子、品脫和加侖與英國的英制單位不一致，以及如何在不破壞食譜或報告的情況下轉換烹飪和液體體積。\"],\"xnqczb\":[\"這些指南解釋了 \",[\"tQuantity\"],\" 轉換（例如 \",[\"tFrom\"],\" 到 \",[\"tTo\"],\"）背後的系統、陷阱和日常用法。\"],\"xowcRf\":[\"服務條款\"],\"xrWUa0\":[\"煮飯是非工程師最常碰到單位摩擦的地方。公製配方以克和毫升為單位稱量麵粉和液體；美國食譜依賴杯子和湯匙。對於乾貨來說，重量比體積更可靠，因為包裝密度各不相同。當您必須轉換體積時，請仔細對待杯和升的轉換，並且在精度很重要時更喜歡稱重。\"],\"xs9aZ3\":[\"為什麼浮點轉換器會失敗（以及十進制數學如何修復它）\"],\"xt5Cku\":[\"以公尺為單位，一光年約 9.46 × 10^5 公尺（約 9.46 拍公尺）。以公里為單位，約 9.46 × 10^2 公里。巨大的尺寸正是天文學家喜歡這個單位的原因：銀河距離保持可讀。\"],\"xvTYZc\":[\"一平方英吋等於 645.16 平方毫米。美国习惯的技术图纸和包装通常以平方英寸指定面积。\"],\"xxuWj3\":[\"原子、分子、光的波長和晶格都遠小於毫米。重複說 0.000 000 000 2 m 是不可讀的。前綴 SI 單位和一些傳統的科學單位使數字接近人類規模。\"],\"xyfCYb\":[\"硬轉換使用精確的因子並在舍入允許的情況下盡可能保留原始意圖。軟轉換在其他單位系統中選擇一個方便的接近值，可能會調整公差，以實現本地工具的可製造性。\"],\"y3OKbU\":[\"When volume is still fine\"],\"y3Yg_9\":[\"負攝氏度讀數是正常的；負開爾文值不用於普通熱力學溫度。歷史上的怪事和流行科學的錯誤陳述有時會混淆這一點。如果轉換從合理的攝氏輸入路徑產生負開爾文，則實現是錯誤的。\"],\"y89PWI\":[\"燃油經濟性相鄰混亂\"],\"yAR8KT\":[\"Fuel Economy Units Basics\"],\"yA_nzZ\":[\"如果您透過我們的表格或電子郵件提交回饋、建議或其他內容，即表示您授予我們非排他性、免版稅的許可，以使用該資料來改善服務。您同意不會濫用本網站、試圖破壞本網站、提交非法或濫用內容或乾擾其他使用者的造訪。\"],\"yAkDHH\":[\"在車間，向機械師提供其工具展示單元中的圖紙。強迫不斷的心理轉變比任何因素表辯論都更能增加廢品。如果需要雙尺寸，請在每次繪圖更新時從一個權威的主要值匯出輔助單位。\"],\"yCEJDM\":[\"實驗室中的微米、奈米和皮克\"],\"yCVJEx\":[\"瓷磚、木板和地毯訂單通常會因切割和錯誤而增加 5-15% 的浪費。在您信任測量的面積後應用廢棄物百分比。轉換單位並不能取代廢棄物規劃。\"],\"yGxnJc\":[\"包裝通常以覆蓋指定區域的盒子形式出售。將您的淨面積（加上廢棄物）轉換為賣方的單位，然後除以每箱的覆蓋範圍。四捨五入為整箱。\"],\"yIbAkH\":[\"Weight (mass) covers kilograms, grams, pounds, ounces, stone, and related units for luggage, cooking, shipping, and body weight. Convert with exact factors and keep one home unit for logs and forms.\"],\"yKRod9\":[\"This guide focuses on unit conversion among knots, mph, km/h, and m/s. It does not replace performance charts or training on IAS/TAS relationships.\"],\"yLOiJ4\":[\"<0>終極精度：</0>由Decimal.js提供動力，實現零捨入誤差。\"],\"yQ0Kng\":[\"使用可信任轉換器或 10 的精確冪作為 SI 前綴。保留對習慣單位和特殊天文長度的仔細因子查找。\"],\"yRaXxk\":[\"土地公制單位加上公頃 (10⁴ 平方米) 和 (10² 平方米)。即使它們不是米的前綴形式，也可以與 SI 一起使用。與平方公里或英畝混合時仍以平方公尺換算。\"],\"yVZCfd\":[\"Why is my flight longer than landing time minus takeoff time?\"],\"yVsPvQ\":[\"Using 60×60 incorrectly as 3,000 or 36,000 from zero slips. Decimal hours (0.5 h = 1,800 s) differ from HH:MM:SS parsing. Leap seconds rarely matter for app timeouts under a day.\"],\"yWuRC3\":[\"有些因素是由法律或國際協議定義的且是準確的。國際吋正好是25.4毫米。一公升正好是 0.001 立方公尺。使用這些精確值可以避免引入錯誤的精確度或系統偏差。\"],\"yYWE07\":[\"Reverse: kilograms to stone for conversation—divide kg by 6.35029318 to get decimal stone, then split into whole stone and remaining pounds carefully—or convert kg → lb first, then divide by 14 for stone and remainder.\"],\"yb3igQ\":[\"Subtracting 273 from a value already near room temperature can look “almost right” and hide a 0.15 K bias. Negative Kelvin is physically invalid—if you see it, the input was wrong. Do not apply the Fahrenheit offset formulas to Kelvin.\"],\"ybVMSR\":[\"1 Julian year = 365.25 days = 8,766 hours = 525,960 minutes = 31,557,600 seconds. Those relationships are exact under the definition used here. Converters that implement Year (Julian) should match these figures.\"],\"yc-YBj\":[\"厘的使用與毫和公斤一樣廣泛嗎？\"],\"ycIpq-\":[\"人的頭髮大約有幾十微米。可見光波長約為數百奈米。原子間距約為十分之一奈米 (ångströms)。道路距離以公里為單位；機械加工使用毫米；光學和半導體的尺寸為微米和奈米。\"],\"ydLT42\":[\"一公頃 (hm) 等於 100 公尺。它是氣象學（降雨率）和一些運動距離中使用的國際單位制倍數。\"],\"ydN0n-\":[\"說出數量。確認尺寸（L、L²、L³、θ、...）。選擇相容的單位。對長度因子應用正確的冪。最後圓了。估計捕捉 100 倍錯誤的大致程度。如果棒球場失敗，請在訂購材料之前停止。\"],\"ye30Jw\":[\"School zones and temporary limits are where unit mistakes hurt most because the absolute speeds are lower but enforcement and child safety margins are tight. Convert the posted number before you “nudge a little over.”\"],\"yjU6f5\":[\"為什麼我的化學劑量看起來太強了？\"],\"ykrwS3\":[\"Divide 60 by the pace in minutes per kilometre. Example: 6:00 min/km → 60/6 = 10 km/h. Convert seconds into decimal minutes first (5:30 → 5.5).\"],\"yorl4E\":[\"Measure in whatever the scale displays. Convert to the audience’s unit with stone↔kg or lb↔kg tools. Write the compound UK form only for humans who expect it. Store metric in spreadsheets.\"],\"yotZlg\":[\"如何在表格、運動和健康記錄中在厘米、米、英尺和英寸之間轉換高度，而無需在句子中間混合系統。\"],\"yq9RVX\":[\"Tare the bowl, add the first ingredient to its target weight, tare again, add the next. Working entirely in grams reduces unit toggling. If the recipe is in ounces, either convert the whole recipe before starting or keep the scale in oz for that session—do not mix mid-bowl.\"],\"ywHWsW\":[\"實際檢查：1 m3 = 1 000 L = 1 000 000 cm3。 1 平方公尺 = 10 000 平方公分。如果轉換後的面積或體積相差 100 或 1000 倍，則懷疑前綴上缺少正方形或立方體。\"],\"ywdLUh\":[\"Convert kilograms to avoirdupois pounds for body weight, luggage, and gym plates when scales or airlines mix SI and US customary units. Shipping rate cards and protein powder tubs cross this pair constantly. One kilogram is about 2.20462 lb.\"],\"ywlqvz\":[\"Use our square metre ↔ square foot converter for the area step and metre ↔ foot for checking individual wall lengths on mixed drawings.\"],\"yz_Uj6\":[\"為了將<0>\",[\"tFrom\"],\"</0>轉換為<1>\",[\"tTo\"],\"</1>，我們的工具使用基本單位作為橋樑，透過任意精度的十進制算術確保最大精度。\"],\"z-7BXf\":[\"Carpet Area Calculator Workflow\"],\"z-8hWf\":[\"海裡（國際）\"],\"z6K72t\":[\"Square metres ↔ square feet\"],\"z6_cZc\":[\"歷史告訴轉換器者什麼\"],\"z7wFp8\":[\"A 10-yard fabric bolt section is 9.144 m—enough to plan metric pattern layouts. A first-down marker at 10 yards is 9.14 m on a metric practice field overlay.\"],\"zBLASl\":[\"拉姆達\"],\"zFY4fe\":[\"一米有多少奈米？\"],\"zI3I0m\":[\"No. 1.30 hours means 1 hour + 0.30 × 60 = 18 minutes. 1 hour 30 minutes is 1.5 hours. Do not read mm as a decimal fraction.\"],\"zIWRzB\":[\"One knot means one nautical mile per hour. The international nautical mile is exactly 1,852 metres, so 1 knot = 1.852 km/h exactly. In statute (land) miles, 1 knot ≈ 1.15078 mph. Mariners and aviators use knots so speed and chart distance share the same mile definition.\"],\"zItrmB\":[\"Using 273 instead of 273.15 is fine for rough work but wrong for precise calorimetry. Multiplying by 273.15 instead of adding is a frequent calculator error. Kelvin is never written with a degree symbol in modern SI (write 300 K, not 300 °K).\"],\"zJ-oU4\":[\"當我們觀察遠處的物體時，我們看到的是過去留下的光。對於附近的恆星來說，以年為單位的回顧時間在數值上接近以光年為單位的距離。在宇宙尺度上，宇宙膨脹效應使距離測量和回溯時間之間的關係更加微妙。\"],\"zMPCk2\":[\"Treadmill Pace: min/km and Speed Units\"],\"zNWlva\":[\"Body weight, gym plates, and health forms\"],\"zOY1MB\":[\"1 Julian year is 365.25 days. 4 Julian years are 1,461 days—the leap-day pattern baked into that average.\"],\"zVAIyg\":[\"Cookie 同意\"],\"zW9QNz\":[\"未找到單位\"],\"zY9UuN\":[\"圓密耳是直徑 0.001 英吋的圓的面積。電機工程用它來指定電線橫截面積。\"],\"zYqng0\":[\"Green light near 550 nm is 5.5×10⁻⁷ m in wave equations. A 7 nm semiconductor node dimension is 7×10⁻⁹ m—useful when comparing to atomic radii quoted in metres.\"],\"zdrl26\":[\"建築佔地面積與地塊大小\"],\"zk7B8P\":[\"Treating 1 oz as 25 g or 30 g shifts chocolate tempering and postage. “Net wt 16 oz” is one pound (453.6 g), not 16 × 30. Distinguish ounce-force if you came from an older engineering table.\"],\"zkqP5e\":[\"Identify which variable you know. Convert mass and volume into a consistent pair. Apply the triangle. Convert the answer into the display unit last.\"],\"zlfei8\":[\"Time units nest by sixty—and then by twenty-four\"],\"znRg18\":[\"Historical note: the name comes from counting knots in a line paid out over a sandglass interval. Modern instruments use sensors and GNSS; the unit definition is now fixed by the international nautical mile.\"],\"zntqjv\":[\"小數、有理數和定點替代方案\"],\"zsKJ2q\":[\"儀表\"],\"zx4BuL\":[\"Week\"],\"zx6yEA\":[\"Kilograms vs Pounds in Everyday Life\"],\"zxRKuk\":[\"Why convert speed when talking about fuel economy?\"],\"zygSd2\":[\"mph to km/h for Road Trips\"]}")as Messages;